import request from '@/utils/request';
import type { HttpCollection } from '@/types/http-contract';

export interface DictData {
  dictLabel: string;
  dictValue: string;
  dictType?: string;
  listClass?: string;
  cssClass?: string;
  status?: string;
}

// 查询字典数据列表
export function listData(query?: Record<string, any>) {
  return request({
    url: '/system/dict/data/list',
    method: 'get',
    params: query,
  });
