import { useGraphInstance } from './useGraphInstance';

export function useClipboard(graphInstance = null) {
  let graph;

  try {
    graph = graphInstance || useGraphInstance();
  } catch (error) {
    graph = graphInstance;
  }

  const copy = (cells) => {
    const g = graph?.value || graph;
    if (g) {
      const clipboard = g.getPlugin('clipboard');
      if (clipboard) {
        clipboard.copy(cells || g.getSelectedCells());
      }
    }
  };

  const paste = (options = {}) => {
    const g = graph?.value || graph;
    if (g) {
      const clipboard = g.getPlugin('clipboard');
      if (clipboard) {
        // 默认配置确保粘贴的节点有新的ID
        const defaultOptions = {
          offset: 20,
          ...options,
        };
        return clipboard.paste(defaultOptions);
      }
    }
    return [];
  };

  const cut = (cells) => {
    const g = graph?.value || graph;
    if (g) {
      const clipboard = g.getPlugin('clipboard');
      if (clipboard) {
        clipboard.cut(cells || g.getSelectedCells());
      }
    }
  };

  const isEmpty = () => {
    const g = graph?.value || graph;
    if (g) {
      const clipboard = g.getPlugin('clipboard');
      if (clipboard) {
        return clipboard.isEmpty();
      }
    }
    return true;
  };

  return {
    copy,
    paste,
    cut,
    isEmpty,
  };
}

/**
 * 通用右键菜单组合式函数
 * 基于企业级最佳实践的上下文菜单管理
 */

import { ref, computed, onMounted, onUnmounted, nextTick } from 'vue';
import { useDeviceSupport } from './useDeviceSupport.js';

export function useContextMenu(graph, options = {}) {
  const { isMacOs, isCtrlKeyPressed } = useDeviceSupport();

  const contextMenu = ref({
    visible: false,
    x: 0,
    y: 0,
    items: [],
    target: null,
    type: 'blank', // 'blank' | 'node' | 'edge' | 'port'
  });

  // 右键刚打开菜单后，短时间忽略一次全局 click，防止瞬时关闭
  let lastOpenAt = 0;

  // 默认配置
  const defaultOptions = {
    enabled: true,
    enableBlankMenu: true,
    enableNodeMenu: true,
    enableEdgeMenu: true,
    customItems: {}, // 自定义菜单项，支持 position 配置（向后兼容）
    customMenuHandler: null, // 自定义菜单处理器（新方式）
  };

  const config = { ...defaultOptions, ...options };

  // 合并自定义菜单项的辅助函数
  const mergeCustomItems = (standardItems, customItems) => {
    if (!customItems || customItems.length === 0) {
      return standardItems;
    }

    const result = [...standardItems];
    const topItems = [];
    const bottomItems = [];

    // 分类自定义菜单项
    customItems.forEach((item) => {
      if (item.position === 'top') {
        topItems.push(item);
      } else {
        // 默认为 bottom
        bottomItems.push(item);
      }
    });

    // 在顶部插入菜单项
    if (topItems.length > 0) {
      result.unshift({ type: 'divider' });
      result.unshift(...topItems);
    }

    // 在底部添加菜单项
    if (bottomItems.length > 0) {
      result.push({ type: 'divider' });
      result.push(...bottomItems);
    }

    return result;
  };

  // 处理自定义菜单的核心函数
  const processCustomMenu = (standardItems, type, target = null) => {
    // 优先使用新的自定义菜单处理器
    if (typeof config.customMenuHandler === 'function') {
      try {
        const result = config.customMenuHandler(standardItems, type, target);
        // 确保返回的是数组
        return Array.isArray(result) ? result : standardItems;
      } catch (error) {
        console.error('自定义菜单处理器执行错误:', error);
        return standardItems;
      }
    }

    // 向后兼容：使用旧的合并逻辑
    return mergeCustomItems(standardItems, config.customItems[type]);
  };

  // 获取剪贴板状态（需要外部注入）
  let clipboardHandler = null;
  let historyHandler = null;
  let selectionHandler = null;

  // 设置处理器
  const setClipboardHandler = (handler) => {
    clipboardHandler = handler;
  };

  const setHistoryHandler = (handler) => {
    historyHandler = handler;
  };

  const setSelectionHandler = (handler) => {
    selectionHandler = handler;
  };

  // 标准菜单项定义
  const getBlankMenuItems = () => {
    const items = [
      {
        id: 'select-all',
        label: '全选',
        shortcut: isMacOs ? 'Cmd+A' : 'Ctrl+A',
        icon: 'Select',
        action: () => selectionHandler?.selectAll(),
        disabled: !selectionHandler,
      },
      {
        id: 'paste',
        label: '粘贴',
        shortcut: isMacOs ? 'Cmd+V' : 'Ctrl+V',
        icon: 'DocumentCopy',
        action: () => clipboardHandler?.paste(),
        disabled: !clipboardHandler || clipboardHandler.isEmpty(),
      },
      { type: 'divider' },
      {
        id: 'zoom-to-fit',
        label: '适应画布',
        shortcut: isMacOs ? 'Cmd+0' : 'Ctrl+0',
        icon: 'FullScreen',
        action: () => {
          const g = graph?.value || graph;
          g?.scaleContentToFit({ padding: 20 });
        },
        disabled: !graph,
      },
      {
        id: 'zoom-to-actual',
        label: '实际大小',
        shortcut: isMacOs ? 'Cmd+1' : 'Ctrl+1',
        icon: 'ZoomIn',
        action: () => {
          const g = graph?.value || graph;
          g?.scale(1);
          g?.centerContent();
        },
        disabled: !graph,
      },
      { type: 'divider' },
      {
        id: 'clear-canvas',
        label: '清空画布',
        icon: 'Delete',
        action: () => {
          if (confirm('确定要清空画布吗？')) {
            const g = graph?.value || graph;
            g?.clearCells();
          }
        },
        disabled: !graph,
        danger: true,
      },
    ];

    // 使用新的自定义菜单处理逻辑
    return processCustomMenu(items, 'blank');
  };

  const getNodeMenuItems = (node) => {
    const items = [
      {
        id: 'copy',
        label: '复制',
        shortcut: isMacOs ? 'Cmd+C' : 'Ctrl+C',
        icon: 'DocumentCopy',
        action: () => clipboardHandler?.copy([node]),
        disabled: !clipboardHandler,
      },
      {
        id: 'delete',
        label: '删除',
        shortcut: 'Delete',
        icon: 'Delete',
        action: () => {
          const g = graph?.value || graph;
          g?.removeCell(node);
        },
        disabled: !graph,
        danger: true,
      },
    ];

    // 使用新的自定义菜单处理逻辑
    return processCustomMenu(items, 'node', node);
  };

  const getEdgeMenuItems = (edge) => {
    const items = [
      {
        id: 'edit-label',
        label: '编辑标签',
        icon: 'Edit',
        action: () => editEdgeLabel(edge),
        disabled: !edge,
      },
      {
        id: 'delete',
        label: '删除连接',
        shortcut: 'Delete',
        icon: 'Delete',
        action: () => {
          const g = graph?.value || graph;
          g?.removeCell(edge);
        },
        disabled: !graph,
        danger: true,
      },
    ];

    // 使用新的自定义菜单处理逻辑
    return processCustomMenu(items, 'edge', edge);
  };

  // 辅助函数：切换节点锁定状态
  const LOCK_META_KEY = 'lockState/originalStroke';

  const toggleNodeLock = (node) => {
    if (!node) return;

    const locked = node.prop('locked') === true;
    const newLocked = !locked;

    node.prop('locked', newLocked);
    node.prop('movable', !newLocked);
    node.prop('draggable', !newLocked);

    try {
      if (typeof node.updateData === 'function') {
        node.updateData({ locked: newLocked });
      } else if (typeof node.setData === 'function') {
        const current = node.getData ? node.getData() || {} : {};
        node.setData({ ...current, locked: newLocked });
      }
    } catch (error) {
      console.warn('同步节点锁定数据状态失败:', error);
    }

    const storedStroke = node.prop(LOCK_META_KEY);
    const currentStroke = node.attr('body/stroke') || '#333';
    const savedStroke = storedStroke || currentStroke || '#333';

    node.prop(LOCK_META_KEY, newLocked ? savedStroke : null, { silent: true });

    if (newLocked) {
      node.attr('body/strokeDasharray', '5,5');
      node.attr('body/stroke', '#ff6b6b');
      node.attr('body/data-locked', 'true');
    } else {
      node.attr('body/strokeDasharray', '');
      node.attr('body/stroke', savedStroke);
      node.attr('body/data-locked', null);
    }

    console.log(`节点 ${node.id} ${newLocked ? '已锁定' : '已解锁'}`);
  };

  // 辅助函数：编辑边标签
  const editEdgeLabel = (edge) => {
    if (!edge) return;

    const currentLabel = getEdgeLabelText(edge);
    const newLabel = prompt('请输入边的标签:', currentLabel);

    if (newLabel !== null) {
      if (newLabel === '') {
        edge.setLabels([]);
      } else {
        edge.setLabels([
          {
            attrs: {
              label: { text: newLabel },
            },
          },
        ]);
      }
    }
  };

  // 获取边标签文本
  const getEdgeLabelText = (edge) => {
    if (!edge) return '';
    if (typeof edge.getLabelAt === 'function') {
      const label = edge.getLabelAt(0);
      if (!label) return '';
      if (typeof label === 'string') return label;
      if (label?.attrs?.label?.text != null) return label.attrs.label.text;
      if (label?.attrs?.text?.text != null) return label.attrs.text.text;
      if (typeof label?.text === 'string') return label.text;
    }
    return '';
  };

  // 显示右键菜单
  const showContextMenu = (x, y, type, target = null) => {
    console.log('showContextMenu called:', { x, y, type, target, enabled: config.enabled });

    if (!config.enabled) return;

    let items = [];

    switch (type) {
      case 'blank':
        if (!config.enableBlankMenu) return;
        items = getBlankMenuItems();
        break;
      case 'node':
        if (!config.enableNodeMenu) return;
        items = getNodeMenuItems(target);
        break;
      case 'edge':
        if (!config.enableEdgeMenu) return;
        items = getEdgeMenuItems(target);
        break;
      case 'port':
        items = processCustomMenu([], 'port', target);
        break;
      default:
        return;
    }

    // 过滤掉被禁用且不显示的项目
    items = items.filter((item) => {
      if (item.type === 'divider') return true;
      return item.hidden !== true;
    });

    contextMenu.value = {
      visible: true,
      x,
      y,
      items,
      target,
      type,
    };

    // 标记本次打开时间，用于抖动保护
    lastOpenAt = Date.now();

    // 防止菜单超出屏幕
    nextTick(() => {
      adjustMenuPosition();
    });
  };

  // 隐藏右键菜单
  const hideContextMenu = () => {
    contextMenu.value.visible = false;
  };

  // 调整菜单位置防止超出屏幕
  const adjustMenuPosition = () => {
    if (!contextMenu.value.visible) return;

    const menuEl = document.querySelector('.xflow-context-menu');
    if (!menuEl) return;

    const menuRect = menuEl.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let { x, y } = contextMenu.value;

    // 防止右侧超出
    if (x + menuRect.width > viewportWidth) {
      x = viewportWidth - menuRect.width - 10;
    }

    // 防止底部超出
    if (y + menuRect.height > viewportHeight) {
      y = viewportHeight - menuRect.height - 10;
    }

    // 防止左侧和顶部超出
    x = Math.max(10, x);
    y = Math.max(10, y);

    contextMenu.value.x = x;
    contextMenu.value.y = y;
  };

  // 处理菜单项点击
  const handleMenuClick = (item) => {
    if (item.disabled || item.type === 'divider') return;

    hideContextMenu();

    if (typeof item.action === 'function') {
      try {
        item.action();
      } catch (error) {
        console.error('Context menu action error:', error);
      }
    }
  };

  const setEnabled = (enabled) => {
    config.enabled = !!enabled;
    if (!config.enabled) {
      hideContextMenu();
    }
  };

  // 设置自定义菜单处理器
  const setCustomMenuHandler = (handler) => {
    if (typeof handler === 'function' || handler === null) {
      config.customMenuHandler = handler;
    } else {
      console.warn('customMenuHandler 必须是一个函数或 null');
    }
  };

  // 设置图形事件监听
  const setupGraphEvents = (graphInstance = null) => {
    const g = graphInstance || graph?.value || graph;
    if (!g || typeof g.on !== 'function') {
      console.warn('Graph instance is not ready for context menu setup');
      return;
    }

    // 节点右键
    g.on('node:contextmenu', ({ e, node }) => {
      console.log('node:contextmenu triggered', { e, node });
      e.preventDefault();
      showContextMenu(e.clientX, e.clientY, 'node', node);
    });

    // 边右键
    g.on('edge:contextmenu', ({ e, edge }) => {
      console.log('edge:contextmenu triggered', { e, edge });
      e.preventDefault();
      showContextMenu(e.clientX, e.clientY, 'edge', edge);
    });

    // 空白区域右键
    g.on('blank:contextmenu', ({ e }) => {
      console.log('blank:contextmenu triggered', { e });
      e.preventDefault();
      showContextMenu(e.clientX, e.clientY, 'blank');
    });

    // 端口右键
    g.on('port:contextmenu', ({ e, port, node }) => {
      console.log('port:contextmenu triggered', { e, port, node });
      e.preventDefault();
      showContextMenu(e.clientX, e.clientY, 'port', { port, node });
    });

    // 点击空白/节点/边时隐藏菜单（忽略右键点击，避免刚打开就被关闭）
    g.on('blank:click', ({ e }) => {
      if (e && e.button === 2) return;
      hideContextMenu();
    });
    g.on('node:click', ({ e }) => {
      if (e && e.button === 2) return;
      hideContextMenu();
    });
    g.on('edge:click', ({ e }) => {
      if (e && e.button === 2) return;
      hideContextMenu();
    });
  };

  // 全局点击事件监听
  const handleGlobalClick = (e) => {
    // 右键（contextmenu）不触发隐藏，仅在左键单击空白处隐藏
    if (e.button === 2) return;
    // 打开菜单后的第一次 click（常在右键后立即发生）忽略
    if (lastOpenAt && Date.now() - lastOpenAt < 200) return;
    const menuEl = document.querySelector('.xflow-context-menu');
    if (menuEl && menuEl.contains(e.target)) return;
    hideContextMenu();
  };

  // 全局按键监听：允许 ESC 取消菜单
  const handleGlobalKeydown = (e) => {
    if (e.key === 'Escape') {
      hideContextMenu();
    }
  };

  // 初始化
  onMounted(() => {
    document.addEventListener('click', handleGlobalClick);
    document.addEventListener('keydown', handleGlobalKeydown, true);
  });

  // 清理
  onUnmounted(() => {
    document.removeEventListener('click', handleGlobalClick);
    document.removeEventListener('keydown', handleGlobalKeydown, true);
  });

  return {
    contextMenu: computed(() => contextMenu.value),
    showContextMenu,
    hideContextMenu,
    handleMenuClick,
    setEnabled,
    setClipboardHandler,
    setHistoryHandler,
    setSelectionHandler,
    setCustomMenuHandler, // 新增：设置自定义菜单处理器
    setupGraphEvents, // 允许手动设置事件
  };
}

import { onBeforeUnmount, ref, onMounted, watch, inject, isRef } from 'vue';
import { Dnd } from '@antv/x6-plugin-dnd';
import { GRAPH_INSTANCE_KEY } from './useGraphInstance';

export function useDnd(arg1 = null, arg2 = {}) {
  let graphRef = null;
  let options;

  const isGraphInstance = (candidate) => !!candidate && typeof candidate?.createNode === 'function';

  const isGraphLike = (g) => {
    if (!g) return false;
    if (typeof g === 'function') {
      try {
        const val = g();
        if (val == null) {
          return true;
        }
        return isGraphInstance(val);
      } catch {
        // Treat function resolvers as lazy graph providers even if they throw for now
        return true;
      }
    }
    if (isRef(g)) {
      const val = g.value;
      if (val == null) {
        return true;
      }
      return isGraphInstance(val);
    }
    return isGraphInstance(g);
  };

  if (isGraphLike(arg1)) {
    graphRef = arg1;
    options = arg2 || {};
    console.log('[useDnd] Using provided graph instance');
  } else {
    options = arg1 || {};
    // 延迟获取 graph - 在 Vue setup 上下文中通过 inject 获取
    try {
      const context = inject(GRAPH_INSTANCE_KEY, null);
      if (context && context.graph) {
        graphRef = context.graph;
        console.log('[useDnd] Got graph from inject:', {
          isRef: !!graphRef?.__v_isRef,
          hasValue: !!graphRef?.value,
          valueType: graphRef?.value?.constructor?.name,
        });
      } else {
        console.log('[useDnd] No graph context available yet, will wait for it');
        graphRef = ref(null);
      }
    } catch (e) {
      console.log('[useDnd] inject failed (not in setup context), creating empty ref');
      graphRef = ref(null);
    }
  }

  // 确保 graphRef 始终是一个 ref
  if (!graphRef) {
    console.log('[useDnd] graphRef is null, creating empty ref');
    graphRef = ref(null);
  }

  const dndRef = ref(null);

  const resolveGraphInstance = (candidate, depth = 0) => {
    if (!candidate || depth > 5) {
      return null;
    }

    if (typeof candidate?.createNode === 'function') {
      return candidate;
    }

    if (candidate?.value && candidate.value !== candidate) {
      return resolveGraphInstance(candidate.value, depth + 1);
    }

    return null;
  };

  const readGraphSource = () => {
    if (!graphRef) return null;
    if (typeof graphRef === 'function') {
      try {
        return graphRef();
      } catch (error) {
        console.log('[useDnd] readGraphSource: graph resolver threw error:', error);
        return null;
      }
    }
    if (isRef(graphRef)) {
      return graphRef.value;
    }
    return graphRef;
  };

  const describeGraphCandidate = () => {
    const source = readGraphSource();
    if (!source) {
      if (typeof graphRef === 'function') {
        return 'function';
      }
      if (isRef(graphRef)) {
        return 'null';
      }
      return 'null';
    }
    return source.constructor?.name ?? typeof source;
  };

  const getGraph = () => {
    if (!graphRef) {
      console.log('[useDnd] getGraph: graphRef is null/undefined');
      return null;
    }
    if (typeof graphRef === 'function') {
      try {
        const result = graphRef();
        const resolved = resolveGraphInstance(result);
        console.log('[useDnd] getGraph: graphRef is function, result:', {
          resultType: result?.constructor?.name,
          hasCreateNode: typeof resolved?.createNode === 'function',
        });
        return resolved;
      } catch (e) {
        console.log('[useDnd] getGraph: graphRef function threw error:', e);
        return null;
      }
    }
    const candidate = readGraphSource();
    const resolved = resolveGraphInstance(candidate ?? graphRef);
    console.log('[useDnd] getGraph: returning graphRef.value or graphRef:', {
      hasValue: isRef(graphRef) ? graphRef.value != null : undefined,
      candidateType: candidate?.constructor?.name ?? typeof candidate,
      hasCreateNode: typeof resolved?.createNode === 'function',
    });
    if (!resolved) {
      console.log('[useDnd] getGraph: graph instance not ready (missing createNode)');
    }
    return resolved;
  };

  const ensureInit = () => {
    const g = getGraph();
    console.log('[useDnd] ensureInit called - graph:', !!g, 'dndRef:', !!dndRef.value);
    if (g && !dndRef.value) {
      console.log('[useDnd] Initializing DnD with graph:', g?.constructor?.name);
      try {
        dndRef.value = new Dnd({
          target: g,
          scaled: false,
          animation: false,
          validateNode() {
            return true;
          },
          getDragNode: (node) => node.clone(),
          getDropNode: (node) => node.clone(),
          ...options,
        });
        console.log('[useDnd] DnD initialized successfully');
      } catch (error) {
        console.error('[useDnd] Failed to initialize DnD:', error);
      }
    } else if (!g) {
      console.log('[useDnd] Cannot initialize DnD: graph not available');
    } else if (dndRef.value) {
      console.log('[useDnd] DnD already initialized');
    }
  };

  onMounted(() => {
    console.log('[useDnd] onMounted - checking if graph is ready');
    ensureInit();
  });

  // 惰性监听 graph 的可用性
  const shouldWatchGraph =
    graphRef && typeof watch === 'function' && (isRef(graphRef) || typeof graphRef === 'function');

  if (shouldWatchGraph) {
    watch(
      () => readGraphSource(),
      (newGraph) => {
        console.log('[useDnd] Graph changed:', {
          hasGraph: !!newGraph,
          type: newGraph?.constructor?.name,
          hasCreateNode: typeof newGraph?.createNode === 'function',
        });
        if (newGraph && typeof newGraph.createNode === 'function') {
          console.log('[useDnd] Graph became available, initializing DnD...');
          ensureInit();
        }
      },
      { immediate: true }
    );
  }

  let pendingStart = null;
  let stopPendingWatch = null;
  let pendingTimeout = null;

  const clearPending = () => {
    pendingStart = null;
    if (stopPendingWatch) {
      stopPendingWatch();
      stopPendingWatch = null;
    }
    if (pendingTimeout) {
      clearTimeout(pendingTimeout);
      pendingTimeout = null;
    }
  };

  const runStart = (nodeOptions, event) => {
    const g = getGraph();
    console.log(
      '[useDnd] runStart called - graph available:',
      !!g,
      'hasCreateNode:',
      typeof g?.createNode === 'function'
    );
    if (!g || typeof g.createNode !== 'function') {
      console.log('[useDnd] No valid graph instance available');
      return 'no-graph';
    }
    if (!dndRef.value) {
      console.log('[useDnd] DnD not initialized, initializing now...');
      ensureInit();
    }
    if (!dndRef.value) {
      console.error('[useDnd] Failed to initialize DnD even after ensureInit');
      return 'no-dnd';
    }

    try {
      const node = g.createNode(nodeOptions);
      console.log('[useDnd] Created node for drag:', node?.id);
      dndRef.value.start(node, event);
      console.log('[useDnd] DnD started successfully');
      return 'success';
    } catch (error) {
      console.error('[useDnd] Error in runStart:', error);
      return 'error';
    }
  };

  const startDrag = (nodeOptions, event) => {
    console.log('[useDnd] startDrag called');
    const result = runStart(nodeOptions, event);
    if (result === 'success' || result === 'error') {
      clearPending();
      return;
    }

    if (result !== 'no-graph' && result !== 'no-dnd') {
      return;
    }

    console.warn('[useDnd] Graph not ready for DnD, waiting for availability...');
    console.log('[useDnd] Current graph state:', describeGraphCandidate());
    pendingStart = { nodeOptions, event };

    // 设置 watch 监听 graphRef 和 dndRef 的变化
    if (!stopPendingWatch && shouldWatchGraph) {
      console.log('[useDnd] Setting up watch for pending drag operation...');
      stopPendingWatch = watch(
        () => [readGraphSource(), dndRef.value],
        ([graphValue, dnd]) => {
          if (!pendingStart) return;
          console.log('[useDnd] Watch triggered - graph:', !!graphValue, 'dnd:', !!dnd);
          const status = runStart(pendingStart.nodeOptions, pendingStart.event);
          if (status === 'success' || status === 'error') {
            clearPending();
          }
        },
        { immediate: true }
      );
    }

    // 设置超时机制作为备选方案
    if (pendingTimeout) {
      clearTimeout(pendingTimeout);
    }
    pendingTimeout = setTimeout(() => {
      if (!pendingStart) return;
      console.log('[useDnd] Timeout reached, trying one last time...');
      const status = runStart(pendingStart.nodeOptions, pendingStart.event);
      if (status !== 'success') {
        console.error('[useDnd] No graph available for DnD after waiting 3000ms');
        console.log('[useDnd] Final graph state:', describeGraphCandidate());
      }
      clearPending();
    }, 3000);
  };

  onBeforeUnmount(() => {
    clearPending();
  });

  return {
    startDrag,
  };
}

import { Export } from '@antv/x6-plugin-export';
import { useGraphInstance } from './useGraphInstance';

let CachedJsPDF = null;

const ensureJsPDF = async () => {
  if (CachedJsPDF) return CachedJsPDF;
  const mod = await import('jspdf');
  CachedJsPDF = mod?.default || mod?.jsPDF || mod;
  return CachedJsPDF;
};

const isRefLike = (maybeRef) =>
  Boolean(maybeRef && typeof maybeRef === 'object' && 'value' in maybeRef);

const downloadBlob = (content, fileName, mimeType) => {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
};

const loadImage = (src) =>
  new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });

export function useExport(graphInstance = null) {
  let graph;

  try {
    graph = graphInstance || useGraphInstance();
  } catch (error) {
    graph = graphInstance;
  }

  const getGraph = () => {
    if (!graph) return null;
    return isRefLike(graph) ? graph.value : graph;
  };

  const ensureGraph = () => {
    const g = getGraph();
    if (!g) {
      throw new Error(
        'Graph instance is not available – make sure the graph has been initialised before exporting.'
      );
    }
    return g;
  };

  const ensureExportPlugin = (g) => {
    if (!g) return null;
    const existing = typeof g.getPlugin === 'function' ? g.getPlugin('export') : null;
    if (existing) return existing;
    const instance = new Export();
    if (typeof g.use === 'function') {
      g.use(instance);
    }
    return instance;
  };

  const getElementChildren = (element) =>
    Array.from(element?.childNodes || []).filter((node) => node.nodeType === 1);

  const inlineComputedStyle = (sourceEl, targetEl) => {
    if (!sourceEl || !targetEl) return;
    const win = sourceEl.ownerDocument?.defaultView;
    if (!win) return;

    try {
      const computed = win.getComputedStyle(sourceEl);
      const styleText = Array.from(computed)
        .map((prop) => `${prop}:${computed.getPropertyValue(prop)};`)
        .join('');
      const existing = targetEl.getAttribute('style');
      targetEl.setAttribute('style', existing ? `${existing};${styleText}` : styleText);
    } catch (error) {
      // ignore style copy failures caused by inaccessible computed styles
    }

    const sourceChildren = getElementChildren(sourceEl);
    const targetChildren = getElementChildren(targetEl);

    for (let i = 0; i < targetChildren.length; i += 1) {
      inlineComputedStyle(sourceChildren[i], targetChildren[i]);
    }
  };

  const inlineForeignObjectStyles = (svgEl, g) => {
    if (!svgEl || !g) return;
    const sourceSVG = g.container?.querySelector?.('svg');
    if (!sourceSVG) return;

    const sourceBodies = Array.from(sourceSVG.querySelectorAll('foreignObject > body'));
    const targetBodies = Array.from(svgEl.querySelectorAll('foreignObject > body'));

    targetBodies.forEach((targetBody, index) => {
      inlineComputedStyle(sourceBodies[index], targetBody);
    });
  };

  const mergeExportOptions = (options, g) => {
    const merged = { ...options };
    if (merged.copyStyles === undefined) merged.copyStyles = true;
    if (merged.preserveDimensions === undefined) merged.preserveDimensions = true;
    const userBeforeSerialize = merged.beforeSerialize;

    merged.beforeSerialize = function beforeSerialize(svgEl) {
      try {
        inlineForeignObjectStyles(svgEl, g);
      } catch (error) {
        // ignore failures here and continue with export
      }

      if (typeof userBeforeSerialize === 'function') {
        const result = userBeforeSerialize.call(this, svgEl);
        if (result instanceof SVGSVGElement) {
          return result;
        }
      }

      return svgEl;
    };

    return merged;
  };

  const normalizeArgs = (fileNameOrOptions, maybeOptions) => {
    if (typeof fileNameOrOptions === 'string' || typeof fileNameOrOptions === 'number') {
      return [fileNameOrOptions, maybeOptions || {}];
    }
    if (fileNameOrOptions && typeof fileNameOrOptions === 'object') {
      return [undefined, fileNameOrOptions];
    }
    return [undefined, maybeOptions || {}];
  };

  const toSVGString = async (options = {}) => {
    const g = ensureGraph();
    ensureExportPlugin(g);

    const run = (opts) =>
      new Promise((resolve, reject) => {
        try {
          g.toSVG((svg) => resolve(svg), opts);
        } catch (error) {
          reject(error);
        }
      });

    const mergedOptions = mergeExportOptions(options, g);

    try {
      return await run(mergedOptions);
    } catch (error) {
      if (mergedOptions.copyStyles !== false) {
        return run({ ...mergedOptions, copyStyles: false });
      }
      throw error;
    }
  };

  const toDataURL = async (type = 'image/png', options = {}) => {
    const normalized = typeof type === 'string' ? type.toLowerCase() : 'image/png';
    const g = ensureGraph();
    ensureExportPlugin(g);
    const method = normalized.includes('jpeg') || normalized.includes('jpg') ? 'toJPEG' : 'toPNG';

    const mergedOptions = mergeExportOptions(options, g);

    if (typeof g[method] !== 'function') {
      throw new Error(
        `Graph export plugin is missing method ${method}. Did you forget to include <XFlowExport />?`
      );
    }

    return new Promise((resolve, reject) => {
      try {
        g[method]((dataUri) => resolve(dataUri), mergedOptions);
      } catch (error) {
        reject(error);
      }
    });
  };

  const exportPNG = (fileNameOrOptions, options = {}) => {
    const g = ensureGraph();
    ensureExportPlugin(g);
    const [fileName, exportOptions] = normalizeArgs(fileNameOrOptions, options);
    const mergedOptions = mergeExportOptions(exportOptions, g);
    const name = fileName || 'graph.png';
    g.exportPNG(name, mergedOptions);
    return name;
  };

  const exportJPEG = (fileNameOrOptions, options = {}) => {
    const g = ensureGraph();
    ensureExportPlugin(g);
    const [fileName, exportOptions] = normalizeArgs(fileNameOrOptions, options);
    const mergedOptions = mergeExportOptions(exportOptions, g);
    const name = fileName || 'graph.jpg';
    g.exportJPEG(name, mergedOptions);
    return name;
  };

  const exportSVG = async (fileNameOrOptions, options = {}) => {
    const g = ensureGraph();
    ensureExportPlugin(g);
    const [fileName, exportOptions] = normalizeArgs(fileNameOrOptions, options);
    const baseName = fileName != null ? String(fileName) : 'graph.svg';
    const name = baseName.endsWith('.svg') ? baseName : `${baseName}.svg`;

    const svgString = await toSVGString({ preserveDimensions: true, ...exportOptions });
    if (!svgString) return null;
    const xml = svgString.startsWith('<?xml')
      ? svgString
      : `<?xml version="1.0" encoding="UTF-8"?>\n${svgString}`;
    downloadBlob(xml, name, 'image/svg+xml;charset=utf-8');
    return xml;
  };

  const exportPDF = async (fileNameOrOptions, options = {}) => {
    const [fileName, exportOptions] = normalizeArgs(fileNameOrOptions, options);
    const {
      type = 'image/png',
      orientation,
      format = 'a4',
      margin = 24,
      pdfOptions = {},
      ...imageOptions
    } = exportOptions || {};

    const normalizedType = typeof type === 'string' ? type.toLowerCase() : 'image/png';
    const dataUrl = await toDataURL(normalizedType, imageOptions);
    if (!dataUrl) return null;

    const img = await loadImage(dataUrl);
    const PdfCtor = await ensureJsPDF();

    const orientationHint = orientation || (img.width >= img.height ? 'l' : 'p');
    const pdf = new PdfCtor({ orientation: orientationHint, unit: 'pt', format, ...pdfOptions });

    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();
    const horizMargin = typeof margin === 'number' ? margin : (margin?.horizontal ?? 24);
    const vertMargin = typeof margin === 'number' ? margin : (margin?.vertical ?? 24);
    const maxWidth = pageWidth - horizMargin * 2;
    const maxHeight = pageHeight - vertMargin * 2;
    const scale = Math.min(maxWidth / img.width, maxHeight / img.height, 1);
    const drawWidth = img.width * scale;
    const drawHeight = img.height * scale;
    const offsetX = (pageWidth - drawWidth) / 2;
    const offsetY = (pageHeight - drawHeight) / 2;

    const imageType =
      normalizedType.includes('jpeg') || normalizedType.includes('jpg') ? 'JPEG' : 'PNG';
    pdf.addImage(dataUrl, imageType, offsetX, offsetY, drawWidth, drawHeight);

    const saveAs = fileName || 'graph.pdf';
    pdf.save(saveAs);
    return saveAs;
  };

  return {
    exportPNG,
    exportJPEG,
    exportSVG,
    exportPDF,
    toDataURL,
    toSVGString,
  };
}

import { inject, provide, ref } from 'vue';

export const GRAPH_INSTANCE_KEY = Symbol('graphInstance');

// 提供 Graph 实例
export function provideGraphInstance() {
  const graph = ref(null);

  provide(GRAPH_INSTANCE_KEY, {
    graph,
    setGraph: (instance) => {
      graph.value = instance;
    },
  });

  return {
    graph,
    setGraph: (instance) => {
      graph.value = instance;
    },
  };
}

// 使用 Graph 实例
export function useGraphInstance(options = {}) {
  const { required = true, warnIfMissing = !required } = options;
  // 传入默认值以避免 Vue 在注入缺失时输出控制台告警
  const context = inject(GRAPH_INSTANCE_KEY, null);

  if (!context) {
    if (required) {
      throw new Error('useGraphInstance must be used within XFlow component');
    }

    if (warnIfMissing && import.meta.env.DEV) {
      console.warn(
        '[ZxFlow] Graph instance context not found. Dag features may not work as expected.'
      );
    }

    return ref(null);
  }

  return context.graph;
}

export function useOptionalGraphInstance() {
  return useGraphInstance({ required: false, warnIfMissing: false });
}

import { useGraphInstance } from './useGraphInstance';

export function useHistory(graphInstance = null) {
  let graph;

  try {
    graph = graphInstance || useGraphInstance();
  } catch (error) {
    graph = graphInstance;
  }

  const undo = () => {
    const g = graph?.value || graph;
    if (g) {
      const history = g.getPlugin('history');
      if (history) {
        history.undo();
      }
    }
  };

  const redo = () => {
    const g = graph?.value || graph;
    if (g) {
      const history = g.getPlugin('history');
      if (history) {
        history.redo();
      }
    }
  };

  const canUndo = () => {
    const g = graph?.value || graph;
    if (g) {
      const history = g.getPlugin('history');
      if (history) {
        return history.canUndo();
      }
    }
    return false;
  };

  const canRedo = () => {
    const g = graph?.value || graph;
    if (g) {
      const history = g.getPlugin('history');
      if (history) {
        return history.canRedo();
      }
    }
    return false;
  };

  const clean = () => {
    const g = graph?.value || graph;
    if (g) {
      const history = g.getPlugin('history');
      if (history) {
        history.clean();
      }
    }
  };

  return {
    undo,
    redo,
    canUndo,
    canRedo,
    clean,
  };
}

import { onMounted, onUnmounted, ref, watch } from 'vue';
import { useGraphInstance } from './useGraphInstance';
import { useLatest } from './useLatest';

export function useKeyboard(key, callback, action = 'keydown') {
  const graph = useGraphInstance();
  const latestCallback = useLatest(callback);

  // 更新回调引用
  const updateCallback = (newCallback) => {
    latestCallback.value = newCallback;
  };

  const bindKey = () => {
    if (graph && graph.value) {
      graph.value.bindKey(
        key,
        (e) => {
          if (latestCallback && latestCallback.value) {
            latestCallback.value(e);
          }
        },
        action
      );
    }
  };

  const unbindKey = () => {
    if (graph && graph.value) {
      graph.value.unbindKey(key);
    }
  };

  // 监听 graph 变化
  watch(
    graph,
    (newGraph) => {
      if (newGraph) {
        bindKey();
      }
    },
    { immediate: true }
  );

  onUnmounted(() => {
    unbindKey();
  });

  return {
    updateCallback,
    bindKey,
    unbindKey,
  };
}

import { computed } from 'vue';
import { useGraphInstance } from './useGraphInstance';

/**
 * 插件加载状态检测 Hook
 * 用于检查指定插件是否已加载，避免在插件未就绪时调用相关功能
 */
export function useLoaded(pluginName) {
  const graph = useGraphInstance();

  // 检查插件是否已加载
  const isLoaded = computed(() => {
    if (!graph || !graph.value) {
      return false;
    }

    const plugin = graph.value.getPlugin(pluginName);
    return !!plugin;
  });

  // 安全调用函数（只有在插件加载后才执行）
  const safeCall = (callback) => {
    if (!graph || !graph.value) {
      console.warn('Graph instance not available');
      return false;
    }

    const plugin = graph.value.getPlugin(pluginName);
    if (!plugin) {
      console.warn(
        `Plugin ${pluginName} is not loaded. Please ensure the corresponding component is included.`
      );
      return false;
    }

    if (typeof callback === 'function') {
      try {
        return callback(plugin);
      } catch (error) {
        console.error(`Error calling function for plugin ${pluginName}:`, error);
        return false;
      }
    }

    return true;
  };

  // 等待插件加载完成
  const waitForPlugin = (timeout = 5000) => {
    return new Promise((resolve, reject) => {
      const startTime = Date.now();

      const check = () => {
        if (isLoaded.value) {
          resolve(graph.value.getPlugin(pluginName));
          return;
        }

        if (Date.now() - startTime > timeout) {
          reject(new Error(`Plugin ${pluginName} failed to load within ${timeout}ms`));
          return;
        }

        setTimeout(check, 50);
      };

      check();
    });
  };

  return {
    isLoaded,
    safeCall,
    waitForPlugin,
  };
}

/**
 * 标准交互管理器
 * 集成企业级标准的图编辑器交互功能
 */

import { ref, onMounted, onUnmounted, nextTick } from 'vue';
import { useContextMenu } from './useContextMenu.js';
import { useDeviceSupport } from './useDeviceSupport.js';

export function useStandardInteractions(graph, options = {}) {
  const { isMacOs, isCtrlKeyPressed } = useDeviceSupport();
  const safeCleanSelection = (graphInstance) => {
    const g = graphInstance;
    if (!g) return;
    if (typeof g.cleanSelection === 'function') {
      g.cleanSelection();
      return;
    }
    const selected = g.getSelectedCells?.();
    if (selected && Array.isArray(selected) && selected.length > 0) {
      selected.forEach((cell) => g.unselect?.(cell));
    }
  };

  // 默认配置
  const defaultOptions = {
    enableContextMenu: true,
    enableDoubleClickFit: true,
    enableStandardSelection: true,
    enableKeyboardShortcuts: true,
    contextMenuOptions: {},
    // 是否允许边被选择/框选
    allowEdgeSelection: false,
  };

  const config = { ...defaultOptions, ...options };

  // 初始化右键菜单
  const contextMenuComposable = config.enableContextMenu
    ? useContextMenu(graph, config.contextMenuOptions)
    : null;

  const blankDblclickHandler = () => {
    const g = getGraphInstance();
    g?.scaleContentToFit({ padding: 20 });
  };

  const updateDoubleClickFitListener = (graphInstance = null) => {
    const g = graphInstance || getGraphInstance();
    if (!g || typeof g.on !== 'function') return;
    g.off('blank:dblclick', blankDblclickHandler);
    if (config.enableDoubleClickFit) {
      g.on('blank:dblclick', blankDblclickHandler);
    }
  };

  // 选择状态
  const selectedCells = ref([]);
  // 框选模式状态（Shift+拖拽时为 true）
  const isRubberbandMode = ref(false);
  // Shift 键按压状态，用于在框选模式下禁用画布拖拽
  const isShiftPressed = ref(false);
  // 避免橡皮筋结束后被 blank:click 立即清除选择
  const skipNextBlankClick = ref(false);
  let wasPannableBeforeShift = null;

  const getGraphInstance = () => graph?.value || graph;

  const handleShiftKeyDown = (event) => {
    if (event.key !== 'Shift' || event.repeat || event.metaKey || event.ctrlKey || event.altKey) {
      return;
    }
    isShiftPressed.value = true;
    const g = getGraphInstance();
    if (!g || typeof g.disablePanning !== 'function') return;
    wasPannableBeforeShift = g.isPannable?.() ?? null;
    if (wasPannableBeforeShift) {
      g.disablePanning();
    }
  };

  const handleShiftKeyUp = (event) => {
    if (event.key !== 'Shift') return;
    isShiftPressed.value = false;
    const g = getGraphInstance();
    if (g && wasPannableBeforeShift) {
      g.enablePanning?.();
    }
    wasPannableBeforeShift = null;
  };

  onMounted(() => {
    window.addEventListener('keydown', handleShiftKeyDown, true);
    window.addEventListener('keyup', handleShiftKeyUp, true);
  });

  onUnmounted(() => {
    window.removeEventListener('keydown', handleShiftKeyDown, true);
    window.removeEventListener('keyup', handleShiftKeyUp, true);
    if (isShiftPressed.value) {
      const g = getGraphInstance();
      if (g && wasPannableBeforeShift) {
        g.enablePanning?.();
      }
    }
    isShiftPressed.value = false;
    wasPannableBeforeShift = null;
  });

  // 设置标准交互事件
  const setupStandardEvents = (graphInstance = null) => {
    const g = graphInstance || getGraphInstance();
    if (!g || typeof g.on !== 'function') {
      console.warn('Graph instance is not ready for event setup');
      return;
    }

    if (isShiftPressed.value && typeof g.disablePanning === 'function') {
      if (wasPannableBeforeShift == null) {
        wasPannableBeforeShift = g.isPannable?.() ?? null;
      }
      if (wasPannableBeforeShift) {
        g.disablePanning();
      }
    }

    // 选择变化监听
    g.on('selection:changed', ({ selected }) => {
      // 按照新逻辑：
      // 1. 框选模式（Shift+拖拽）：允许选择所有元素
      // 2. 正常模式：只允许选择节点，但 Cmd/Ctrl + 点击边例外
      // 3. 不过滤已经通过 Cmd/Ctrl + 点击选中的边
      selectedCells.value = selected;
    });

    // 双击空白区域适应画布
    updateDoubleClickFitListener(g);

    // 标准选择交互
    if (config.enableStandardSelection) {
      setupSelectionInteractions(g);
    }

    // 右键菜单事件已在 useContextMenu 中处理
    if (contextMenuComposable) {
      contextMenuComposable.setupGraphEvents(g);
    }
  };

  // 设置选择交互
  const setupSelectionInteractions = (graphInstance = null) => {
    const g = graphInstance || graph?.value || graph;
    if (!g || typeof g.on !== 'function') return;

    // 监听框选开始和结束
    g.on('selection:rubberband:start', ({ e }) => {
      // 只有按住 Shift 键才进入框选模式
      if (e.shiftKey) {
        isRubberbandMode.value = true;
      }
    });

    g.on('selection:rubberband:end', () => {
      isRubberbandMode.value = false;
      skipNextBlankClick.value = true;
    });

    // 点击空白区域：在未按住修饰键时清除选择
    g.on('blank:click', ({ e }) => {
      if (skipNextBlankClick.value) {
        skipNextBlankClick.value = false;
        return;
      }
      if (e.shiftKey || isRubberbandMode.value) {
        return;
      }
      if (!isCtrlKeyPressed(e)) {
        safeCleanSelection(g);
      }
    });

    // 节点点击选择逻辑
    g.on('node:click', ({ e, node }) => {
      // X6 在 detail >= 2 时代表同一节点连续点击；保持节点已有选中状态并提前返回，
      // 避免再次执行 cleanSelection/select 导致节点重新渲染，从而丢失 dblclick 判定。
      if (e?.detail >= 2) {
        return;
      }
      if (isCtrlKeyPressed(e)) {
        // 交给 Selection 插件处理多选/反选逻辑
        return;
      }
      // 普通点击：单选
      safeCleanSelection(g);
      g.select(node);
    });

    // 边点击选择逻辑 - 按照新需求：正常模式下边不可被点击选中，但 Cmd/Ctrl + 点击可以选中
    g.on('edge:click', ({ e, edge }) => {
      if (isCtrlKeyPressed(e)) {
        // Cmd/Ctrl + 点击边：允许选中并显示选择框
        if (g.isSelected(edge)) {
          g.unselect(edge);
        } else {
          // 增量加入当前选择集合，避免覆盖已有选中
          if (typeof g.addToSelection === 'function') {
            g.addToSelection(edge);
          } else {
            // 兜底：获取已选 + 当次边，重新设置选择
            const current = (g.getSelectedCells && g.getSelectedCells()) || [];
            g.select([...current, edge], { silent: false });
          }
        }
        return;
      }

      // 正常点击：只有在明确允许边选择时才能选中
      if (!config.allowEdgeSelection) {
        return; // 边有hover态但不被选中
      }

      // 普通点击：单选
      safeCleanSelection(g);
      g.select(edge);
    });
  };

  // 选择操作方法
  const selectAll = () => {
    const g = graph?.value || graph;
    if (g) {
      // X6 无内置 selectAll 方法，需要手动选择所有元素
      const cells = config.allowEdgeSelection
        ? g.getCells
          ? g.getCells()
          : []
        : g.getNodes
          ? g.getNodes()
          : [];
      if (cells && cells.length > 0) {
        g.select(cells);
      }
    }
  };

  const clearSelection = () => {
    const g = graph?.value || graph;
    safeCleanSelection(g);
  };

  const deleteSelected = () => {
    const g = graph?.value || graph;
    if (g && selectedCells.value.length > 0) {
      g.removeCells(selectedCells.value);
    }
  };

  // 视图操作方法
  const zoomToFit = () => {
    const g = graph?.value || graph;
    if (g) {
      g.scaleContentToFit({ padding: 20 });
    }
  };

  const zoomToActual = () => {
    const g = graph?.value || graph;
    if (g) {
      g.scale(1);
      g.centerContent();
    }
  };

  const centerContent = () => {
    const g = graph?.value || graph;
    if (g) {
      g.centerContent();
    }
  };

  // 设置处理器给右键菜单
  const setupHandlers = (clipboardActions, historyActions) => {
    if (contextMenuComposable) {
      // 设置剪贴板处理器
      contextMenuComposable.setClipboardHandler(clipboardActions);

      // 设置历史处理器
      contextMenuComposable.setHistoryHandler(historyActions);

      // 设置选择处理器
      contextMenuComposable.setSelectionHandler({
        selectAll,
        clearSelection,
        deleteSelected,
      });
    }
  };

  // 获取当前选择的处理器
  const getSelectionHandler = () => ({
    selectedCells: selectedCells.value,
    selectAll,
    clearSelection,
    deleteSelected,
  });

  // 获取视图操作处理器
  const getViewHandler = () => ({
    zoomToFit,
    zoomToActual,
    centerContent,
  });

  // 初始化将由外部调用

  return {
    // 状态
    selectedCells,

    // 右键菜单
    contextMenu: contextMenuComposable?.contextMenu,
    handleMenuClick: contextMenuComposable?.handleMenuClick,

    // 操作方法
    selectAll,
    clearSelection,
    deleteSelected,
    zoomToFit,
    zoomToActual,
    centerContent,

    // 处理器设置
    setupHandlers,
    getSelectionHandler,
    getViewHandler,

    // 事件设置
    setupStandardEvents,
    setContextMenuEnabled: contextMenuComposable?.setEnabled,
    setDoubleClickFitEnabled: (enabled) => {
      config.enableDoubleClickFit = !!enabled;
      updateDoubleClickFitListener();
    },
  };
}

/**
 * 键盘管理器 - 基于 X6 Keyboard 插件的企业级键盘事件管理
 * 参考 Figma/Sketch/Adobe XD 的交互设计
 */

import { Keyboard } from '@antv/x6-plugin-keyboard';
import { Selection } from '@antv/x6-plugin-selection';
import { useDeviceSupport } from '../composables/useDeviceSupport.js';

// 生成基于设备的快捷键配置
export function createKeyboardConfig() {
  const { isMacOs } = useDeviceSupport();
  const ctrlKey = isMacOs ? 'meta' : 'ctrl';

  return {
    // 选择操作
    [`${ctrlKey}+a`]: 'select-all',

    // 历史操作
    [`${ctrlKey}+z`]: 'undo',
    [`${ctrlKey}+shift+z`]: 'redo',
    ...(isMacOs ? {} : { 'ctrl+y': 'redo' }), // Windows额外支持Ctrl+Y

    // 剪贴板操作
    [`${ctrlKey}+c`]: 'copy',
    [`${ctrlKey}+v`]: 'paste',
    [`${ctrlKey}+x`]: 'cut',

    // 删除操作
    delete: 'delete-selected',
    backspace: 'delete-selected',

    // 取消当前操作 / 清除选择
    esc: 'clear-selection',

    // 视图操作
    [`${ctrlKey}+0`]: 'zoom-to-fit',
    [`${ctrlKey}+1`]: 'zoom-to-actual',

    // 临时拖拽（空格键）
    space: 'temp-pan-start',
  };
}

// 默认配置（向后兼容）
export const DEFAULT_KEYBOARD_CONFIG = createKeyboardConfig();

// 交互模式定义
export const INTERACTION_MODES = {
  PAN: 'pan', // 画布拖拽模式
  SELECT: 'select', // 框选模式
  CONNECT: 'connect', // 连接模式
  EDIT: 'edit', // 编辑模式
};

/**
 * 键盘管理器类
 */
export class KeyboardManager {
  constructor(graph, options = {}) {
    this.graph = graph;
    this.deviceSupport = useDeviceSupport();
    this.options = {
      keyboardConfig: createKeyboardConfig(),
      globalKeys: ['space'], // 需要全局监听的键
      enableStandardInteractions: true, // 启用标准交互
      enableContextMenu: true, // 启用右键菜单
      // 是否允许边被选择/框选（与图层配置保持一致）
      allowEdgeSelection: false,
      ...options,
    };

    this.keyboardPlugin = null;
    this.currentMode = INTERACTION_MODES.PAN;
    this.spacePressed = false;
    this.originalPannable = true;

    this.actionHandlers = new Map();
    this.globalKeyListeners = new Map();
    this.selectionOptions = {
      enabled: true,
      multiple: true,
      rubberband: true,
      modifiers: ['shift'],
      multipleSelectionModifiers: ['ctrl', 'meta'],
      showNodeSelectionBox: true,
      showEdgeSelectionBox: this.options.allowEdgeSelection === true,
      selectEdgeOnMoveEdge: false,
      strict: false,
    };

    this.init();
  }

  /**
   * 初始化键盘管理器
   */
  init() {
    this.setupKeyboardPlugin();
    this.setupGlobalKeys();
    this.registerDefaultActions();
    // 初始化Selection插件，使用默认的PAN模式配置
    this.setInteractionMode(this.currentMode);
  }

  /**
   * 设置 X6 键盘插件
   */
  setupKeyboardPlugin() {
    // 移除现有插件
    if (this.graph.getPlugin('keyboard')) {
      this.graph.disposePlugins('keyboard');
    }

    // 添加键盘插件
    this.keyboardPlugin = new Keyboard({
      enabled: true,
      global: false, // 不使用全局模式，避免冲突
    });

    this.graph.use(this.keyboardPlugin);

    // 绑定快捷键
    Object.entries(this.options.keyboardConfig).forEach(([key, action]) => {
      if (!this.options.globalKeys.includes(key.split('+').pop())) {
        this.graph.bindKey(key, (e) => this.handleAction(action, e));
      }
    });
  }

  /**
   * 设置全局键盘监听（仅限必要的键）
   */
  setupGlobalKeys() {
    this.options.globalKeys.forEach((key) => {
      const keydownHandler = (e) => {
        if (e.code === 'Space' && e.target === document.body) {
          this.handleSpaceDown(e);
        }
      };

      const keyupHandler = (e) => {
        if (e.code === 'Space') {
          this.handleSpaceUp(e);
        }
      };

      document.addEventListener('keydown', keydownHandler);
      document.addEventListener('keyup', keyupHandler);

      // 保存引用用于清理
      this.globalKeyListeners.set(key, { keydownHandler, keyupHandler });
    });
  }

  /**
   * 注册默认动作处理器
   */
  registerDefaultActions() {
    // 选择操作
    this.registerAction('select-all', () => this.selectAll());
    this.registerAction('clear-selection', () => this.clearSelection());

    // 删除操作
    this.registerAction('delete-selected', () => this.deleteSelected());

    // 视图操作
    this.registerAction('zoom-to-fit', () => this.zoomToFit());
    this.registerAction('zoom-to-actual', () => this.zoomToActual());

    // 剪贴板操作需要外部注入
    this.registerAction('copy', () => this.handleClipboard('copy'));
    this.registerAction('paste', () => this.handleClipboard('paste'));
    this.registerAction('cut', () => this.handleClipboard('cut'));

    // 历史操作需要外部注入
    this.registerAction('undo', () => this.handleHistory('undo'));
    this.registerAction('redo', () => this.handleHistory('redo'));
  }

  /**
   * 选择所有元素
   */
  selectAll() {
    if (this.graph) {
      // X6 无内置 selectAll 方法；这里按配置选择节点（可选边）
      const cells = this.options.allowEdgeSelection
        ? this.graph.getCells
          ? this.graph.getCells()
          : []
        : this.graph.getNodes
          ? this.graph.getNodes()
          : [];
      if (cells && cells.length > 0) {
        this.graph.select(cells);
      }
    }
  }

  /**
   * 清除选择
   */
  clearSelection() {
    if (this.graph) {
      this.graph.cleanSelection();
    }
  }

  /**
   * 适应画布
   */
  zoomToFit() {
    if (this.graph) {
      this.graph.scaleContentToFit({ padding: 20 });
    }
  }

  /**
   * 实际大小
   */
  zoomToActual() {
    if (this.graph) {
      this.graph.scale(1);
      this.graph.centerContent();
    }
  }

  /**
   * 注册动作处理器
   */
  registerAction(action, handler) {
    this.actionHandlers.set(action, handler);
  }

  /**
   * 执行动作
   */
  handleAction(action, event) {
    const handler = this.actionHandlers.get(action);
    if (handler) {
      event?.preventDefault();
      handler(event);
    }
  }

  /**
   * 设置交互模式
   */
  setInteractionMode(mode) {
    this.currentMode = mode;

    switch (mode) {
      case INTERACTION_MODES.PAN:
        this.graph.enablePanning();
        this.updateSelectionPlugin({
          rubberband: true,
          modifiers: ['shift'],
          multiple: true,
        });
        break;

      case INTERACTION_MODES.SELECT:
        this.graph.disablePanning();
        this.updateSelectionPlugin({
          rubberband: true,
          modifiers: null,
          multiple: true,
        });
        break;

      // 可扩展其他模式
    }
  }

  /**
   * 更新选择插件配置
   */
  updateSelectionPlugin(options) {
    // 移除现有插件
    if (this.graph.getPlugin('selection')) {
      this.graph.disposePlugins('selection');
    }

    this.selectionOptions = {
      ...this.selectionOptions,
      showEdgeSelectionBox: this.options.allowEdgeSelection === true,
      ...options,
    };

    // 重新添加插件，使用新配置
    this.graph.use(
      new Selection({
        ...this.selectionOptions,
      })
    );
  }

  /**
   * 处理空格键按下
   */
  handleSpaceDown(e) {
    if (this.spacePressed) return;

    this.spacePressed = true;
    this.originalPannable = this.graph.options.panning?.enabled !== false;

    // 临时启用拖拽
    this.graph.enablePanning();
    e.preventDefault();
  }

  /**
   * 处理空格键释放
   */
  handleSpaceUp(e) {
    if (!this.spacePressed) return;

    this.spacePressed = false;

    // 恢复原来的拖拽状态
    if (this.currentMode === INTERACTION_MODES.SELECT) {
      this.graph.disablePanning();
    }

    e.preventDefault();
  }

  /**
   * 删除选中元素
   */
  deleteSelected() {
    const selectedCells = this.graph.getSelectedCells();
    if (selectedCells.length > 0) {
      this.graph.removeCells(selectedCells);
    }
  }

  /**
   * 处理剪贴板操作（需要外部注入处理器）
   */
  handleClipboard(action) {
    if (this.clipboardHandler) {
      this.clipboardHandler(action);
    }
  }

  /**
   * 处理历史操作（需要外部注入处理器）
   */
  handleHistory(action) {
    if (this.historyHandler) {
      this.historyHandler(action);
    }
  }

  /**
   * 注入剪贴板处理器
   */
  setClipboardHandler(handler) {
    this.clipboardHandler = handler;
  }

  /**
   * 注入历史处理器
   */
  setHistoryHandler(handler) {
    this.historyHandler = handler;
  }

  /**
   * 销毁管理器
   */
  destroy() {
    // 清理全局事件监听
    this.globalKeyListeners.forEach(({ keydownHandler, keyupHandler }, key) => {
      document.removeEventListener('keydown', keydownHandler);
      document.removeEventListener('keyup', keyupHandler);
    });

    this.globalKeyListeners.clear();
    this.actionHandlers.clear();

    // X6 插件会在 graph.dispose() 时自动清理
  }
}

/**
 * 创建键盘管理器的工厂函数
 */
export function createKeyboardManager(graph, options = {}) {
  return new KeyboardManager(graph, options);
}

// XFlow Vue 库的基础图形支持
// 这里只提供通用的图形注册工具和基础形状

import { Graph } from '@antv/x6';
import { register } from '@antv/x6-vue-shape';

/**
 * 基础图形注册工具类
 * 提供给业务层使用的通用注册方法
 */
export class ShapeRegistry {
  static flags = {};

  /**
   * 检查图形是否已注册
   */
  static isRegistered(shapeName) {
    return !!this.flags[shapeName];
  }

  /**
   * 标记图形已注册
   */
  static markRegistered(shapeName) {
    this.flags[shapeName] = true;
  }

  /**
   * 安全注册图形（防重复）
   */
  static safeRegister(shapeName, config, callback) {
    if (this.isRegistered(shapeName)) {
      console.warn(`Shape ${shapeName} already registered`);
      return false;
    }

    try {
      const result = callback(config);
      this.markRegistered(shapeName);
      console.log(`Shape ${shapeName} registered successfully`);
      return true;
    } catch (e) {
      console.warn(`Failed to register shape ${shapeName}:`, e);
      return false;
    }
  }

  /**
   * 注册普通节点
   */
  static registerNode(shapeName, config) {
    return this.safeRegister(shapeName, config, (cfg) => {
      Graph.registerNode(shapeName, cfg);
    });
  }

  /**
   * 注册边
   */
  static registerEdge(shapeName, config) {
    return this.safeRegister(shapeName, config, (cfg) => {
      Graph.registerEdge(shapeName, cfg);
    });
  }

  /**
   * 注册 Vue 组件节点
   */
  static registerVueNode(shapeName, config) {
    return this.safeRegister(shapeName, config, (cfg) => {
      register({
        shape: shapeName,
        ...cfg,
      });
    });
  }
}

