// 导出常用工具
export { register as registerVueShape } from '@antv/x6-vue-shape';
export { Graph } from '@antv/x6';

import { defineStore } from 'pinia';
import { StringExt } from '@antv/x6';

// 命令类型定义
export const COMMANDS = {
  INIT: 'init',
  ADD_NODES: 'addNodes',
  REMOVE_NODES: 'removeNodes',
  UPDATE_NODE: 'updateNode',
  ADD_EDGES: 'addEdges',
  REMOVE_EDGES: 'removeEdges',
  UPDATE_EDGE: 'updateEdge',
};

// 工具函数：深度合并对象
function apply(target, source) {
  if (!source) return target;

  Object.keys(source).forEach((key) => {
    if (source[key] !== null && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      if (!target[key] || typeof target[key] !== 'object') {
        target[key] = {};
      }
      apply(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  });

  return target;
}

export const useGraphStore = defineStore('graph', {
  state: () => ({
    nodes: [],
    edges: [],
    changeList: [],
  }),

  actions: {
    initData(data, options = {}) {
      this.nodes = data.nodes || [];
      this.edges = data.edges || [];

      if (!options.silent) {
        this.changeList.push({
          command: COMMANDS.INIT,
          data,
        });
      }
    },

    addNodes(ns, options = {}) {
      if (!ns || !ns.length) return;

      // 生成节点 ID
      ns.forEach((n) => {
        if (!n.id) {
          n.id = StringExt.uuid();
        }
      });

      // 检查重复 ID
      const duplicated = this.nodes.find((n) => ns.some((m) => m.id && m.id === n.id));

      if (!duplicated) {
        this.nodes.push(...ns);
        if (!options.silent) {
          this.changeList.push({
            command: COMMANDS.ADD_NODES,
            data: ns,
          });
        }
      } else {
        console.error(`node id=${duplicated.id} already existed`);
      }
    },

    removeNodes(ids, options = {}) {
      if (!ids || !ids.length) return;

      this.nodes = this.nodes.filter((n) => !ids.includes(n.id));

      if (!options.silent) {
        this.changeList.push({
          command: COMMANDS.REMOVE_NODES,
          data: ids,
        });
      }
    },

    updateNode(id, data, options = {}) {
      const node = this.nodes.find((n) => n.id === id);
      if (node) {
        const changed = typeof data === 'function' ? data({ ...node }) : data;

        if (changed.id !== undefined || changed.shape !== undefined) {
          console.error(`id and shape can't be changed`);
          return;
        }

        apply(node, changed);

        if (!options.silent) {
          this.changeList.push({
            command: COMMANDS.UPDATE_NODE,
            data: { id, data: changed },
          });
        }
      }
    },

    addEdges(es, options = {}) {
      if (!es || !es.length) return;

      // 生成边 ID
      es.forEach((e) => {
        if (!e.id) {
          e.id = StringExt.uuid();
        }
      });

      // 检查重复 ID
      const duplicated = this.edges.find((e) => es.some((m) => m.id && m.id === e.id));

      if (!duplicated) {
        this.edges.push(...es);
        if (!options.silent) {
          this.changeList.push({
            command: COMMANDS.ADD_EDGES,
            data: es,
          });
        }
      } else {
        console.error(`edge id=${duplicated.id} already existed`);
      }
    },

    removeEdges(ids, options = {}) {
      if (!ids || !ids.length) return;

      this.edges = this.edges.filter((n) => !ids.includes(n.id));

      if (!options.silent) {
        this.changeList.push({
          command: COMMANDS.REMOVE_EDGES,
          data: ids,
        });
      }
    },

    updateEdge(id, data, options = {}) {
      const edge = this.edges.find((n) => n.id === id);
      if (edge) {
        const changed = typeof data === 'function' ? data({ ...edge }) : data;

        if (changed.id !== undefined || changed.shape !== undefined) {
          console.error(`id and shape can't be changed`);
          return;
        }

        apply(edge, changed);

        if (!options.silent) {
          this.changeList.push({
            command: COMMANDS.UPDATE_EDGE,
            data: { id, data: changed },
          });
        }
      }
    },

    clearChangeList() {
      this.changeList = [];
    },

    // 批量更新方法（支持函数式更新）
    $patch(updater) {
      if (typeof updater === 'function') {
        const currentState = {
          nodes: [...this.nodes],
          edges: [...this.edges],
          changeList: [...this.changeList],
        };
        const newState = updater(currentState);

        if (newState.nodes) this.nodes = newState.nodes;
        if (newState.edges) this.edges = newState.edges;
        if (newState.changeList) this.changeList = newState.changeList;
      } else {
        // 对象式更新
        if (updater.nodes) this.nodes = updater.nodes;
        if (updater.edges) this.edges = updater.edges;
        if (updater.changeList) this.changeList = updater.changeList;
      }
    },
  },

  getters: {
    getNodeById: (state) => (id) => {
      return state.nodes.find((node) => node.id === id);
    },

    getEdgeById: (state) => (id) => {
      return state.edges.find((edge) => edge.id === id);
    },

    getAllNodes: (state) => state.nodes,

    getAllEdges: (state) => state.edges,

    getChangeList: (state) => state.changeList,
  },
});

import { computed, reactive, shallowReactive, unref } from 'vue';
import { useDialog } from '@zxio/zxui';
import type { CSSProperties } from 'vue';
import { formLayoutPolicy, type FormColumns } from './policy';

export { default as FormGrid } from './FormGrid.vue';
export type { FormColumns } from './policy';

type DialogOptions<T extends Record<string, any>> = NonNullable<Parameters<typeof useDialog<T>>[0]>;
type FormDialogStyle = Omit<CSSProperties, 'width' | 'height'> & { width?: never; height?: never };
export type FormDialogOptions<T extends Record<string, any>> = Omit<
  DialogOptions<T>,
  'width' | 'height' | 'dialogStyle'
> & {
  columns: FormColumns;
  width?: never;
  height?: never;
  dialogStyle?: FormDialogStyle;
};

function checkColumns(columns: FormColumns) {
  if (![1, 2, 3].includes(columns)) {
    throw new TypeError('[useFormDialog] columns must explicitly be 1, 2 or 3');
  }
}

function sanitize<T extends Record<string, any>>(options: Partial<FormDialogOptions<T>>) {
  const { columns: _columns, width, height, dialogStyle, dialogSize: _size, ...rest } = options;
  const safeStyle = dialogStyle ? { ...dialogStyle } : undefined;
  if (
    import.meta.env.DEV &&
    (width !== undefined ||
      height !== undefined ||
      (safeStyle && ('width' in safeStyle || 'height' in safeStyle)))
  ) {
    console.warn(
      '[useFormDialog] width/height are ignored; use columns, dialogSize or dialogStyle.maxHeight'
    );
  }
  if (safeStyle) {
    delete safeStyle.width;
    delete safeStyle.height;
  }
  return { ...rest, ...(safeStyle ? { dialogStyle: safeStyle } : {}) };
}

export function useFormDialog<T extends Record<string, any> = Record<string, any>>(
  options: FormDialogOptions<T>
) {
  checkColumns(options.columns);
  const layoutProps = reactive({ columns: options.columns });
  const sizeOverride = shallowReactive({ value: options.dialogSize });
  const dialogSize = computed(() => {
    const size = unref(sizeOverride.value) ?? formLayoutPolicy.dialogSize[layoutProps.columns];
    if (!['sm', 'md', 'lg', 'xl', 'small', 'large'].includes(String(size))) {
      throw new TypeError('[useFormDialog] dialogSize must be a supported preset');
    }
    return size;
  });
  const dialog = useDialog<T>({ showFullScreen: false, ...sanitize(options), dialogSize });
  return {
    ...dialog,
    formProps: { labelWidth: formLayoutPolicy.labelWidth },
    layoutProps,
    updateOptions(value: Partial<FormDialogOptions<T>>) {
      if (value.columns !== undefined) {
        checkColumns(value.columns);
        layoutProps.columns = value.columns;
      }
      if ('dialogSize' in value) sizeOverride.value = value.dialogSize;
      dialog.updateOptions({ ...sanitize(value), dialogSize });
    },
  };
}

import request from '@/utils/request';

/**
 * Custom Upload Adapter for CKEditor 5
 */
export default class MyUploadAdapter {
  loader: any;
  uploadUrl: string;

  constructor(loader: any, uploadUrl: string) {
    // The file loader instance to use during the upload.
    this.loader = loader;
    this.uploadUrl = uploadUrl;
  }

  // Starts the upload process.
  upload(): Promise<{ default: string }> {
    return this.loader.file.then(
      (file: File) =>
        new Promise((resolve, reject) => {
          const data = new FormData();
          data.append('file', file);

          request({
            url: this.uploadUrl,
            method: 'post',
            data: data,
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          })
            .then((res: any) => {
              // HTTP 2xx 已由拦截器判定，直接处理成功响应
              resolve({
                default: res.url, // Assuming the backend returns the full URL in 'url' field, or construct it
              });
            })
            .catch((error: any) => {
              // 错误已由拦截器统一处理
              reject(error);
            });
        })
    );
  }

  // Aborts the upload process.
  abort(): void {
    // Implement abort logic if needed, but axios cancellation requires a cancel token
    // For simplicity, we can leave this empty or implement it later if strictly required
  }
}

import { ref, computed, shallowRef, onMounted, watchEffect } from 'vue';

export type DataSourceFetcher = () => Promise<any[]>;

export type DataSourceOptions = {
  fetch?: DataSourceFetcher;
  static?: any[];
  labelKey?: string;
  valueKey?: string;
  cacheKey?: string;
};

const cacheStore = new Map<string, any[]>();

export function useDataSource(options: DataSourceOptions) {
  const loading = ref(false);
  const error = shallowRef<unknown>(null);
  const items = ref<any[]>([]);

  const labelKey = options.labelKey ?? 'label';
  const valueKey = options.valueKey ?? 'value';

  const transformed = computed(() =>
    (items.value || []).map((item) => ({
      label: item[labelKey],
      value: item[valueKey],
      raw: item,
    }))
  );

  const fetchData = async () => {
    if (options.cacheKey && cacheStore.has(options.cacheKey)) {
      items.value = cacheStore.get(options.cacheKey) || [];
      return;
    }

    if (!options.fetch) return;
    loading.value = true;
    error.value = null;
    try {
      const list = await options.fetch();
      items.value = Array.isArray(list) ? list : [];
      if (options.cacheKey) {
        cacheStore.set(options.cacheKey, items.value);
      }
    } catch (err) {
      error.value = err;
    } finally {
      loading.value = false;
    }
  };

  onMounted(() => {
    if (options.static) {
      items.value = options.static;
      if (options.cacheKey) cacheStore.set(options.cacheKey, items.value);
      return;
    }
    fetchData();
  });

  return {
    loading,
    error,
    items,
    options: transformed,
    reload: fetchData,
  };
}

import type { VxeTableDefines } from 'vxe-table';
import type { VxeSchemaColumn } from './index.vue';

export type VxeWidgetResolver = (column: VxeSchemaColumn) => Partial<VxeSchemaColumn>;
export type VxeWidgetResolverMap = Record<string, VxeWidgetResolver>;

const globalRegistry: VxeWidgetResolverMap = {};

export function registerVxeWidget(name: string, resolver: VxeWidgetResolver) {
  globalRegistry[name] = resolver;
}

export function getVxeWidget(name?: string, local?: VxeWidgetResolverMap) {
  if (!name) return undefined;
  return local?.[name] ?? globalRegistry[name];
}

export function resolveWidgetColumn(
  column: VxeSchemaColumn,
  local?: VxeWidgetResolverMap
): Partial<VxeSchemaColumn> {
  const resolver = getVxeWidget(column.widget, local);
  return resolver ? resolver(column) : {};
}

const mergeEditRender = (base?: any, override?: any): any => {
  if (!base) return override;
  if (!override) return base;
  return {
    ...base,
    ...override,
    props: { ...(base.props || {}), ...(override.props || {}) },
  };
};

export function mergeColumnOptions(
  base: Partial<VxeSchemaColumn>,
  column: VxeSchemaColumn
): VxeSchemaColumn {
  const merged: VxeSchemaColumn = {
    ...base,
    ...column,
  };

  merged.editRender = mergeEditRender(base.editRender, column.editRender);

  if (base.slots || column.slots) {
    merged.slots = { ...(base.slots || {}), ...(column.slots || {}) };
  }

  return merged;
}

// 默认内置的通用组件映射
registerVxeWidget('input', () => ({
  editRender: { name: 'input' },
}));

registerVxeWidget('number', () => ({
  editRender: { name: 'input', props: { type: 'number' } },
}));

registerVxeWidget('textarea', () => ({
  editRender: { name: 'textarea' },
}));

registerVxeWidget('select', (column) => ({
  editRender: {
    name: 'select',
    props: {
      clearable: true,
      ...(column.widgetProps || {}),
    },
  },
}));

registerVxeWidget('dict-autocomplete', (column) => {
  const props = column.widgetProps || {};
  if (props.dataSource && !props.dictType) {
    // dataSource 由 schema 提供，交给组件解析
    return {
      editRender: {
        name: 'DictAutocomplete',
        props,
      },
    };
  }
  return {
    editRender: {
      name: 'DictAutocomplete',
      props: {
        placeholder: '请输入或选择',
        ...(column.widgetProps || {}),
      },
    },
  };
});

/**
 * VXE-Table 通用校验框架 - 类型定义
 * 设计理念：类似 Element Plus / async-validator 的规则配置方式
 */

/** 校验级别 */
export type ValidationLevel = 'error' | 'warning' | 'info';

/** 校验触发时机 */
export type ValidationTrigger = 'change' | 'blur' | 'manual';

/** 校验规则基础类型 */
export interface ValidationRule {
  /** 是否必填 */
  required?: boolean;
  /** 错误消息 */
  message?: string | ((value: any, row: any) => string);
  /** 校验级别，默认 error */
  level?: ValidationLevel;
  /** 触发时机 */
  trigger?: ValidationTrigger | ValidationTrigger[];
  /** 数据类型校验 */
  type?:
    | 'string'
    | 'number'
    | 'integer'
    | 'float'
    | 'boolean'
    | 'array'
    | 'object'
    | 'date'
    | 'url'
    | 'email';
  /** 最小值（数字）或最小长度（字符串/数组） */
  min?: number;
  /** 最大值（数字）或最大长度（字符串/数组） */
  max?: number;
  /** 精确长度 */
  len?: number;
  /** 正则表达式 */
  pattern?: RegExp | string;
  /** 枚举值，值必须在列表中 */
  enum?: any[];
  /** 自定义校验器 */
  validator?: ValidatorFunction;
  /** 异步校验器 */
  asyncValidator?: AsyncValidatorFunction;
  /** 转换函数，校验前先转换值 */
  transform?: (value: any) => any;
  /** 条件校验：只在条件满足时才校验 */
  when?: (row: any, index: number) => boolean;
}

/** 校验器函数 */
export type ValidatorFunction = (
  value: any,
  row: any,
  index: number,
  field: string
) => boolean | string | void;

/** 异步校验器函数 */
export type AsyncValidatorFunction = (
  value: any,
  row: any,
  index: number,
  field: string
) => Promise<boolean | string | void>;

/** 字段校验规则配置 */
export type FieldRules = Record<string, ValidationRule | ValidationRule[]>;

/** 全局校验器（跨行/跨字段校验） */
export interface GlobalValidator {
  /** 校验器名称 */
  name: string;
  /** 校验器函数 */
  validator: (
    data: any[],
    context?: ValidationContext
  ) => ValidationIssue | ValidationIssue[] | null;
  /** 校验级别 */
  level?: ValidationLevel;
}

/** 校验上下文 */
export interface ValidationContext {
  /** 额外数据，业务可自定义 */
  [key: string]: any;
}

/** 校验问题项 */
export interface ValidationIssue {
  /** 校验级别 */
  level: ValidationLevel;
  /** 行索引，-1 表示全局问题 */
  rowIndex: number;
  /** 字段名 */
  field: string;
  /** 字段显示名称 */
  fieldLabel?: string;
  /** 错误消息 */
  message: string;
  /** 原始值 */
  value?: any;
  /** 修复建议 */
  suggestion?: string;
  /** 规则名称（用于调试） */
  ruleName?: string;
}

/** 校验结果 */
export interface ValidationResult {
  /** 是否校验通过 */
  valid: boolean;
  /** 错误数量 */
  errorCount: number;
  /** 警告数量 */
  warningCount: number;
  /** 信息数量 */
  infoCount: number;
  /** 所有问题 */
  issues: ValidationIssue[];
  /** 按行索引分组的问题 */
  issuesByRow: Map<number, ValidationIssue[]>;
  /** 按字段分组的问题（key: rowIndex-field） */
  issuesByCell: Map<string, ValidationIssue[]>;
}

/** VXE-Table edit-rules 配置项 */
export interface VxeEditRule {
  required?: boolean;
  min?: number;
  max?: number;
  type?: string;
  pattern?: RegExp | string;
  message?: string;
  trigger?: string;
  validator?: (params: {
    cellValue: any;
    row: any;
    rowIndex: number;
    column: any;
  }) => void | Error | Promise<void | Error>;
}

/** useVxeTableValidation 配置 */
export interface UseVxeTableValidationOptions {
  /** 字段校验规则 */
  rules?: FieldRules;
  /** 全局校验器列表 */
  globalValidators?: GlobalValidator[];
  /** 字段标签映射（用于显示友好名称） */
  fieldLabels?: Record<string, string>;
  /** 是否自动校验（编辑后自动触发） */
  autoValidate?: boolean;
  /** 自动校验防抖延迟（毫秒） */
  autoValidateDelay?: number;
  /** 校验上下文 */
  context?: ValidationContext;
  /** 校验完成回调 */
  onValidated?: (result: ValidationResult) => void;
}

/** 字段列配置（用于从 VXE-Table 列配置中提取校验规则） */
export interface FieldColumnConfig {
  field: string;
  title?: string;
  editRender?: any;
  // 扩展：支持直接在列配置中定义校验规则
  validationRules?: ValidationRule | ValidationRule[];
}

/**
 * VXE-Table 通用校验框架 - 核心 Composable
 *
 * 使用方式类似 Element Plus 表单验证：
 *
 * ```ts
 * const { validate, issues, getRowClassName, getCellClassName } = useVxeTableValidation({
 *   rules: {
 *     fieldName: [{ required: true, message: '名称不能为空' }],
 *     byteCount: [{ type: 'integer', min: 1, message: '必须是正整数' }]
 *   },
 *   fieldLabels: {
 *     fieldName: '信息名称',
 *     byteCount: '字节数'
 *   }
 * });
 * ```
 */

import { ref, computed, watch, shallowRef, type Ref, type ComputedRef } from 'vue';
import type {
  ValidationRule,
  FieldRules,
  GlobalValidator,
  ValidationIssue,
  ValidationResult,
  ValidationContext,
  UseVxeTableValidationOptions,
  VxeEditRule,
  ValidationLevel,
} from './types';
import { validateByRule, isEmpty } from './validators';

/** 防抖函数 */
const debounce = <T extends (...args: any[]) => any>(fn: T, delay: number) => {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<T>) => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
};

/**
 * VXE-Table 校验 Composable
 */
export function useVxeTableValidation<T = any>(options: UseVxeTableValidationOptions = {}) {
  const {
    rules = {},
    globalValidators = [],
    fieldLabels = {},
    autoValidate = false,
    autoValidateDelay = 300,
    context: initialContext = {},
    onValidated,
  } = options;

  // ==================== 状态 ====================

  /** 校验问题列表 */
  const issues = ref<ValidationIssue[]>([]);

  /** 当前校验规则 */
  const currentRules = shallowRef<FieldRules>(rules);

  /** 当前全局校验器 */
  const currentGlobalValidators = shallowRef<GlobalValidator[]>(globalValidators);

  /** 校验上下文 */
  const validationContext = ref<ValidationContext>(initialContext);

  /** 是否正在校验 */
  const validating = ref(false);

  // ==================== 计算属性 ====================

  /** 错误数量 */
  const errorCount = computed(() => issues.value.filter((i) => i.level === 'error').length);

  /** 警告数量 */
  const warningCount = computed(() => issues.value.filter((i) => i.level === 'warning').length);

  /** 信息数量 */
  const infoCount = computed(() => issues.value.filter((i) => i.level === 'info').length);

  /** 是否有问题 */
  const hasIssues = computed(() => issues.value.length > 0);

  /** 是否有错误 */
  const hasErrors = computed(() => errorCount.value > 0);

  /** 按行索引分组的问题 */
  const issuesByRow = computed(() => {
    const map = new Map<number, ValidationIssue[]>();
    issues.value.forEach((issue) => {
      if (issue.rowIndex >= 0) {
        const list = map.get(issue.rowIndex) || [];
        list.push(issue);
        map.set(issue.rowIndex, list);
      }
    });
    return map;
  });

  /** 按单元格分组的问题（key: rowIndex-field） */
  const issuesByCell = computed(() => {
    const map = new Map<string, ValidationIssue[]>();
    issues.value.forEach((issue) => {
      if (issue.rowIndex >= 0 && issue.field) {
        const key = `${issue.rowIndex}-${issue.field}`;
        const list = map.get(key) || [];
        list.push(issue);
        map.set(key, list);
      }
    });
    return map;
  });

  /** 全局问题（rowIndex = -1） */
  const globalIssues = computed(() => issues.value.filter((i) => i.rowIndex === -1));

  // ==================== 核心方法 ====================

  /**
   * 执行校验
   * @param data 要校验的数据
   * @param ctx 校验上下文
   * @returns 校验结果
   */
  const validate = async (data: T[], ctx?: ValidationContext): Promise<ValidationResult> => {
    validating.value = true;
    const allIssues: ValidationIssue[] = [];
    const mergedContext = { ...validationContext.value, ...ctx };

    // 1. 字段规则校验
    if (Array.isArray(data)) {
      data.forEach((row, rowIndex) => {
        Object.entries(currentRules.value).forEach(([field, fieldRules]) => {
          const rulesArray = Array.isArray(fieldRules) ? fieldRules : [fieldRules];
          const value = (row as any)[field];

          rulesArray.forEach((rule, ruleIndex) => {
            const errorMsg = validateByRule(value, rule, row, rowIndex, field);
            if (errorMsg) {
              allIssues.push({
                level: rule.level || 'error',
                rowIndex,
                field,
                fieldLabel: fieldLabels[field] || field,
                message: errorMsg,
                value,
                ruleName: `${field}[${ruleIndex}]`,
              });
            }
          });
        });
      });
    }

    // 2. 全局校验器
    for (const validator of currentGlobalValidators.value) {
      const result = validator.validator(data as any[], mergedContext);
      if (result) {
        const resultArray = Array.isArray(result) ? result : [result];
        resultArray.forEach((issue) => {
          allIssues.push({
            ...issue,
            level: issue.level || validator.level || 'error',
            ruleName: validator.name,
          });
        });
      }
    }

    // 3. 异步校验器（如果有的话）
    // TODO: 支持异步校验

    // 更新状态
    issues.value = allIssues;
    validating.value = false;

    // 构建结果
    const result: ValidationResult = {
      valid: allIssues.filter((i) => i.level === 'error').length === 0,
      errorCount: allIssues.filter((i) => i.level === 'error').length,
      warningCount: allIssues.filter((i) => i.level === 'warning').length,
      infoCount: allIssues.filter((i) => i.level === 'info').length,
      issues: allIssues,
      issuesByRow: issuesByRow.value,
      issuesByCell: issuesByCell.value,
    };

    // 回调
    onValidated?.(result);

    return result;
  };

  /**
   * 校验并在失败时抛出错误（用于阻断保存流程）
   * @param data 要校验的数据
   * @param ctx 校验上下文
   * @throws ValidationError 当存在错误级别的问题时抛出
   *
   * @example
   * ```ts
   * const handleSave = async () => {
   *   try {
   *     await validateOrThrow(tableData.value);
   *     // 校验通过，继续保存
   *     await saveData();
   *   } catch (e) {
   *     // 校验失败，e.message 包含错误信息
   *     ElMessage.error(e.message);
   *   }
   * };
   * ```
   */
  const validateOrThrow = async (data: T[], ctx?: ValidationContext): Promise<ValidationResult> => {
    const result = await validate(data, ctx);

    if (!result.valid) {
      const error = new Error(
        `校验失败：发现 ${result.errorCount} 个错误` +
          (result.warningCount > 0 ? `，${result.warningCount} 个警告` : '')
      );
      (error as any).validationResult = result;
      (error as any).isValidationError = true;
      throw error;
    }

    return result;
  };

  /**
   * 校验是否通过（简化版，直接返回布尔值）
   * @param data 要校验的数据
   * @param ctx 校验上下文
   * @returns true 表示通过，false 表示有错误
   */
  const isValid = async (data: T[], ctx?: ValidationContext): Promise<boolean> => {
    const result = await validate(data, ctx);
    return result.valid;
  };

  /**
   * 校验单行
   */
  const validateRow = async (row: T, rowIndex: number): Promise<ValidationIssue[]> => {
    const rowIssues: ValidationIssue[] = [];

    Object.entries(currentRules.value).forEach(([field, fieldRules]) => {
      const rulesArray = Array.isArray(fieldRules) ? fieldRules : [fieldRules];
      const value = (row as any)[field];

      rulesArray.forEach((rule, ruleIndex) => {
        const errorMsg = validateByRule(value, rule, row, rowIndex, field);
        if (errorMsg) {
          rowIssues.push({
            level: rule.level || 'error',
            rowIndex,
            field,
            fieldLabel: fieldLabels[field] || field,
            message: errorMsg,
            value,
            ruleName: `${field}[${ruleIndex}]`,
          });
        }
      });
    });

    // 更新该行的问题
    issues.value = [...issues.value.filter((i) => i.rowIndex !== rowIndex), ...rowIssues];

    return rowIssues;
  };

  /**
   * 校验单个字段
   */
  const validateField = (
    value: any,
    field: string,
    row: T,
    rowIndex: number
  ): ValidationIssue[] => {
    const fieldRules = currentRules.value[field];
    if (!fieldRules) return [];

    const rulesArray = Array.isArray(fieldRules) ? fieldRules : [fieldRules];
    const fieldIssues: ValidationIssue[] = [];

    rulesArray.forEach((rule, ruleIndex) => {
      const errorMsg = validateByRule(value, rule, row, rowIndex, field);
      if (errorMsg) {
        fieldIssues.push({
          level: rule.level || 'error',
          rowIndex,
          field,
          fieldLabel: fieldLabels[field] || field,
          message: errorMsg,
          value,
          ruleName: `${field}[${ruleIndex}]`,
        });
      }
    });

    // 更新该字段的问题
    const cellKey = `${rowIndex}-${field}`;
    issues.value = [
      ...issues.value.filter((i) => !(i.rowIndex === rowIndex && i.field === field)),
      ...fieldIssues,
    ];

    return fieldIssues;
  };

  /**
   * 清除校验结果
   */
  const clearValidation = () => {
    issues.value = [];
  };

  /**
   * 清除指定行的校验结果
   */
  const clearRowValidation = (rowIndex: number) => {
    issues.value = issues.value.filter((i) => i.rowIndex !== rowIndex);
  };

  /**
   * 清除指定字段的校验结果
   */
  const clearFieldValidation = (field: string, rowIndex?: number) => {
    issues.value = issues.value.filter((i) => {
      if (i.field !== field) return true;
      if (rowIndex !== undefined && i.rowIndex !== rowIndex) return true;
      return false;
    });
  };

  // ==================== VXE-Table 集成 ====================

  /**
   * 获取行的样式类（用于 row-class-name）
   */
  const getRowClassName = ({ rowIndex }: { rowIndex: number }): string => {
    const rowIssues = issuesByRow.value.get(rowIndex);
    if (!rowIssues || rowIssues.length === 0) return '';

    if (rowIssues.some((i) => i.level === 'error')) return 'vxe-row--validation-error';
    if (rowIssues.some((i) => i.level === 'warning')) return 'vxe-row--validation-warning';
    if (rowIssues.some((i) => i.level === 'info')) return 'vxe-row--validation-info';

    return '';
  };

  /**
   * 获取单元格的样式类（用于 cell-class-name）
   */
  const getCellClassName = ({ rowIndex, column }: { rowIndex: number; column: any }): string => {
    const field = column?.field;
    if (!field) return '';

    const key = `${rowIndex}-${field}`;
    const cellIssues = issuesByCell.value.get(key);
    if (!cellIssues || cellIssues.length === 0) return '';

    if (cellIssues.some((i) => i.level === 'error')) return 'vxe-cell--validation-error';
    if (cellIssues.some((i) => i.level === 'warning')) return 'vxe-cell--validation-warning';
    if (cellIssues.some((i) => i.level === 'info')) return 'vxe-cell--validation-info';

    return '';
  };

  /**
   * 获取单元格的 tooltip 内容
   */
  const getCellTooltip = (rowIndex: number, field: string): string | null => {
    const key = `${rowIndex}-${field}`;
    const cellIssues = issuesByCell.value.get(key);
    if (!cellIssues || cellIssues.length === 0) return null;

    return cellIssues.map((i) => i.message).join('\n');
  };

  /**
   * 转换为 VXE-Table 的 edit-rules 格式
   */
  const toVxeEditRules = (): Record<string, any[]> => {
    const vxeRules: Record<string, VxeEditRule[]> = {};

    Object.entries(currentRules.value).forEach(([field, fieldRules]) => {
      const rulesArray = Array.isArray(fieldRules) ? fieldRules : [fieldRules];

      vxeRules[field] = rulesArray.map((rule) => {
        const vxeRule: VxeEditRule = {};

        if (rule.required) vxeRule.required = true;
        if (rule.min !== undefined) vxeRule.min = rule.min;
        if (rule.max !== undefined) vxeRule.max = rule.max;
        if (rule.pattern) {
          vxeRule.pattern =
            typeof rule.pattern === 'string' ? new RegExp(rule.pattern) : rule.pattern;
        }
        if (rule.message) {
          vxeRule.message =
            typeof rule.message === 'function' ? rule.message(undefined, {}) : rule.message;
        }

        // 如果有自定义校验器，转换为 VXE 格式
        if (rule.validator || rule.type) {
          vxeRule.validator = ({ cellValue, row, rowIndex }) => {
            const errorMsg = validateByRule(cellValue, rule, row, rowIndex, field);
            if (errorMsg) {
              return new Error(errorMsg);
            }
            return undefined;
          };
        }

        return vxeRule;
      });
    });

    return vxeRules;
  };

  /**
   * VXE-Table 4.x valid-config 配置
   * message: 'tooltip' 鼠标悬停时显示校验消息（右上角三角号触发）
   */
  const vxeValidConfig = {
    // 显示校验消息
    showMessage: true,
    // VXE-Table 4.x: 'tooltip' | 'inline' | 'default'
    // 'tooltip' 鼠标悬停时显示，配合右上角三角号使用
    message: 'tooltip' as const,
    // 'single' 只显示第一个错误，'full' 显示所有
    msgMode: 'single' as const,
    // 校验主题：'beautify'(红底白字) | 'normal'(白底红字)
    theme: 'normal' as const,
    // 自动定位到错误位置
    autoPos: true,
    // 校验失败时不自动清除（保持错误状态）
    autoClear: false,
  };

  // ==================== 动态配置 ====================

  /**
   * 更新校验规则
   */
  const setRules = (newRules: FieldRules) => {
    currentRules.value = newRules;
  };

  /**
   * 添加字段规则
   */
  const addFieldRules = (field: string, rules: ValidationRule | ValidationRule[]) => {
    const existing = currentRules.value[field];
    const existingArray = existing ? (Array.isArray(existing) ? existing : [existing]) : [];
    const newArray = Array.isArray(rules) ? rules : [rules];
    currentRules.value = {
      ...currentRules.value,
      [field]: [...existingArray, ...newArray],
    };
  };

  /**
   * 移除字段规则
   */
  const removeFieldRules = (field: string) => {
    const { [field]: _, ...rest } = currentRules.value;
    currentRules.value = rest;
  };

  /**
   * 添加全局校验器
   */
  const addGlobalValidator = (validator: GlobalValidator) => {
    currentGlobalValidators.value = [...currentGlobalValidators.value, validator];
  };

  /**
   * 移除全局校验器
   */
  const removeGlobalValidator = (name: string) => {
    currentGlobalValidators.value = currentGlobalValidators.value.filter((v) => v.name !== name);
  };

  /**
   * 更新校验上下文
   */
  const setContext = (ctx: ValidationContext) => {
    validationContext.value = { ...validationContext.value, ...ctx };
  };

  // ==================== 自动校验 ====================

  /**
   * 创建自动校验的数据监听器
   */
  const createAutoValidator = (dataRef: Ref<T[]>) => {
    const debouncedValidate = debounce(() => {
      validate(dataRef.value);
    }, autoValidateDelay);

    if (autoValidate) {
      watch(dataRef, debouncedValidate, { deep: true });
    }

    return debouncedValidate;
  };

  // ==================== 返回 ====================

  return {
    // 状态
    issues,
    validating,
    errorCount,
    warningCount,
    infoCount,
    hasIssues,
    hasErrors,
    issuesByRow,
    issuesByCell,
    globalIssues,

    // 核心方法
    validate,
    validateOrThrow, // 校验失败时抛出错误，用于阻断保存
    isValid, // 简化版，直接返回布尔值
    validateRow,
    validateField,
    clearValidation,
    clearRowValidation,
    clearFieldValidation,

    // VXE-Table 集成
    getRowClassName,
    getCellClassName,
    getCellTooltip,
    toVxeEditRules,
    vxeValidConfig,

    // 动态配置
    setRules,
    addFieldRules,
    removeFieldRules,
    addGlobalValidator,
    removeGlobalValidator,
    setContext,
    validationContext,

    // 自动校验
    createAutoValidator,
  };
}

// ==================== 类型导出 ====================

export type UseVxeTableValidationReturn = ReturnType<typeof useVxeTableValidation>;

/**
 * VXE-Table 通用校验框架 - 预置校验器
 * 提供常用的校验规则，类似 async-validator
 */

import type { ValidationRule, ValidatorFunction, GlobalValidator, ValidationIssue } from './types';

// ==================== 工具函数 ====================

/** 判断值是否为空 */
export const isEmpty = (value: any): boolean => {
  if (value === null || value === undefined) return true;
  if (typeof value === 'string' && value.trim() === '') return true;
  if (Array.isArray(value) && value.length === 0) return true;
  return false;
};

/** 解析数值 */
export const parseNumber = (value: any): number | null => {
  if (value === null || value === undefined || value === '') return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
};

/** 获取值的长度 */
export const getLength = (value: any): number => {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'string') return value.length;
  if (Array.isArray(value)) return value.length;
  return String(value).length;
};

// ==================== 类型校验器 ====================

const typeValidators: Record<string, (value: any) => boolean> = {
  string: (value) => typeof value === 'string',
  number: (value) => {
    const num = parseNumber(value);
    return num !== null;
  },
  integer: (value) => {
    const num = parseNumber(value);
    return num !== null && Number.isInteger(num);
  },
  float: (value) => {
    const num = parseNumber(value);
    return num !== null;
  },
  boolean: (value) =>
    typeof value === 'boolean' ||
    value === 'true' ||
    value === 'false' ||
    value === 0 ||
    value === 1,
  array: (value) => Array.isArray(value),
  object: (value) => typeof value === 'object' && value !== null && !Array.isArray(value),
  date: (value) => {
    if (value instanceof Date) return !isNaN(value.getTime());
    const date = new Date(value);
    return !isNaN(date.getTime());
  },
  url: (value) => {
    if (typeof value !== 'string') return false;
    try {
      new URL(value);
      return true;
    } catch {
      return /^https?:\/\/.+/.test(value);
    }
  },
  email: (value) => {
    if (typeof value !== 'string') return false;
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  },
};

// ==================== 核心校验函数 ====================

/**
 * 执行单条规则校验
 */
export const validateByRule = (
  value: any,
  rule: ValidationRule,
  row: any,
  rowIndex: number,
  field: string
): string | null => {
  // 条件校验
  if (rule.when && !rule.when(row, rowIndex)) {
    return null;
  }

  // 值转换
  let validValue = value;
  if (rule.transform) {
    validValue = rule.transform(value);
  }

  // 必填校验
  if (rule.required && isEmpty(validValue)) {
    return getMessage(rule.message, '此字段为必填项', validValue, row);
  }

  // 空值跳过后续校验（非必填时）
  if (isEmpty(validValue)) {
    return null;
  }

  // 类型校验
  if (rule.type && typeValidators[rule.type]) {
    if (!typeValidators[rule.type](validValue)) {
      const typeMessages: Record<string, string> = {
        string: '必须是字符串',
        number: '必须是有效数字',
        integer: '必须是整数',
        float: '必须是数字',
        boolean: '必须是布尔值',
        array: '必须是数组',
        object: '必须是对象',
        date: '必须是有效日期',
        url: '必须是有效的URL',
        email: '必须是有效的邮箱地址',
      };
      return getMessage(rule.message, typeMessages[rule.type] || '类型不正确', validValue, row);
    }
  }

  // 长度/范围校验
  const numValue = parseNumber(validValue);
  const lenValue = getLength(validValue);

  if (rule.len !== undefined) {
    if (rule.type === 'number' || rule.type === 'integer' || rule.type === 'float') {
      if (numValue !== rule.len) {
        return getMessage(rule.message, `必须等于 ${rule.len}`, validValue, row);
      }
    } else {
      if (lenValue !== rule.len) {
        return getMessage(rule.message, `长度必须是 ${rule.len}`, validValue, row);
      }
    }
  }

  if (rule.min !== undefined) {
    if (rule.type === 'number' || rule.type === 'integer' || rule.type === 'float') {
      if (numValue !== null && numValue < rule.min) {
        return getMessage(rule.message, `不能小于 ${rule.min}`, validValue, row);
      }
    } else {
      if (lenValue < rule.min) {
        return getMessage(rule.message, `长度不能小于 ${rule.min}`, validValue, row);
      }
    }
  }

  if (rule.max !== undefined) {
    if (rule.type === 'number' || rule.type === 'integer' || rule.type === 'float') {
      if (numValue !== null && numValue > rule.max) {
        return getMessage(rule.message, `不能大于 ${rule.max}`, validValue, row);
      }
    } else {
      if (lenValue > rule.max) {
        return getMessage(rule.message, `长度不能超过 ${rule.max}`, validValue, row);
      }
    }
  }

  // 正则校验
  if (rule.pattern) {
    const regex = typeof rule.pattern === 'string' ? new RegExp(rule.pattern) : rule.pattern;
    if (!regex.test(String(validValue))) {
      return getMessage(rule.message, '格式不正确', validValue, row);
    }
  }

  // 枚举校验
  if (rule.enum && !rule.enum.includes(validValue)) {
    return getMessage(rule.message, `必须是 [${rule.enum.join(', ')}] 之一`, validValue, row);
  }

  // 自定义校验器
  if (rule.validator) {
    const result = rule.validator(validValue, row, rowIndex, field);
    if (result === false) {
      return getMessage(rule.message, '校验失败', validValue, row);
    }
    if (typeof result === 'string') {
      return result;
    }
  }

  return null;
};

/** 获取消息 */
const getMessage = (
  message: string | ((value: any, row: any) => string) | undefined,
  defaultMsg: string,
  value: any,
  row: any
): string => {
  if (!message) return defaultMsg;
  if (typeof message === 'function') return message(value, row);
  return message;
};

// ==================== 预置规则工厂 ====================

/** 必填规则 */
export const required = (message?: string): ValidationRule => ({
  required: true,
  message: message || '此字段为必填项',
});

/** 数字类型规则 */
export const number = (message?: string): ValidationRule => ({
  type: 'number',
  message: message || '请输入有效数字',
});

/** 整数规则 */
export const integer = (message?: string): ValidationRule => ({
  type: 'integer',
  message: message || '请输入整数',
});

/** 正整数规则 */
export const positiveInteger = (message?: string): ValidationRule => ({
  type: 'integer',
  min: 1,
  message: message || '请输入正整数',
});

/** 非负整数规则 */
export const nonNegativeInteger = (message?: string): ValidationRule => ({
  type: 'integer',
  min: 0,
  message: message || '请输入非负整数',
});

/** 范围规则 */
export const range = (min: number, max: number, message?: string): ValidationRule => ({
  type: 'number',
  min,
  max,
  message: message || `必须在 ${min} - ${max} 之间`,
});

/** 长度范围规则 */
export const lengthRange = (min: number, max: number, message?: string): ValidationRule => ({
  min,
  max,
  message: message || `长度必须在 ${min} - ${max} 之间`,
});

/** 精确长度规则 */
export const length = (len: number, message?: string): ValidationRule => ({
  len,
  message: message || `长度必须是 ${len}`,
});

/** 正则规则 */
export const pattern = (regex: RegExp | string, message?: string): ValidationRule => ({
  pattern: regex,
  message: message || '格式不正确',
});

/** 邮箱规则 */
export const email = (message?: string): ValidationRule => ({
  type: 'email',
  message: message || '请输入有效的邮箱地址',
});

/** URL规则 */
export const url = (message?: string): ValidationRule => ({
  type: 'url',
  message: message || '请输入有效的URL',
});

/** 枚举规则 */
export const oneOf = (values: any[], message?: string): ValidationRule => ({
  enum: values,
  message: message || `必须是 [${values.join(', ')}] 之一`,
});

/** 自定义校验规则 */
export const custom = (
  validator: ValidatorFunction,
  message?: string,
  options?: Partial<ValidationRule>
): ValidationRule => ({
  validator,
  message,
  ...options,
});

/** 警告级别规则（不阻止提交） */
export const warning = (rule: ValidationRule): ValidationRule => ({
  ...rule,
  level: 'warning',
});

/** 信息级别规则（仅提示） */
export const info = (rule: ValidationRule): ValidationRule => ({
  ...rule,
  level: 'info',
});

// ==================== 业务常用校验器 ====================

/** 端口号校验 */
export const port = (message?: string): ValidationRule => ({
  type: 'integer',
  min: 0,
  max: 65535,
  message: message || '端口号范围应在 0-65535',
});

/** IP地址校验 */
export const ipAddress = (message?: string): ValidationRule => ({
  pattern:
    /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
  message: message || '请输入有效的IP地址',
});

/** MAC地址校验 */
export const macAddress = (message?: string): ValidationRule => ({
  pattern: /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/,
  message: message || '请输入有效的MAC地址',
});

/** 字节数校验（正整数，可选最大值） */
export const byteCount = (maxBytes?: number, message?: string): ValidationRule => ({
  type: 'integer',
  min: 1,
  max: maxBytes,
  message: message || (maxBytes ? `字节数必须在 1-${maxBytes} 之间` : '字节数必须为正整数'),
});

/**
 * 比例尺校验（非零数字）
 *
 * @param zeroMessage 自定义比例尺为0时的提示
 * @param typeMessage 自定义类型错误提示（默认：必须是有效数字）
 */
export const scale = (zeroMessage?: string, typeMessage?: string): ValidationRule => ({
  type: 'number',
  // 不设置默认 message，避免类型错误时覆盖成「不能为0」
  message: typeMessage,
  validator: (value) => {
    // 空值跳过（由 required 规则处理）
    if (isEmpty(value)) {
      return true;
    }

    const num = parseNumber(value);

    // 如果无法解析为数字，返回类型错误
    if (num === null) {
      return typeMessage || '必须是有效数字';
    }

    // 如果为0，返回不能为0的错误
    if (num === 0) {
      return zeroMessage || '比例尺不能为0';
    }

    return true;
  },
});

// ==================== 全局校验器工厂 ====================

/**
 * 创建带宽校验器
 */
export const createBandwidthValidator = (options: {
  /** 获取帧长度的函数 */
  getFrameLength: (data: any[]) => number;
  /** 获取传输频率的函数 */
  getFrequency: (context?: any) => number;
  /** 获取带宽限制的函数 */
  getBandwidthLimit: (context?: any) => number;
  /** 格式化带宽显示 */
  formatBandwidth?: (bps: number) => string;
}): GlobalValidator => {
  const defaultFormat = (bps: number): string => {
    if (bps >= 1e9) return `${(bps / 1e9).toFixed(2)} Gbps`;
    if (bps >= 1e6) return `${(bps / 1e6).toFixed(2)} Mbps`;
    if (bps >= 1e3) return `${(bps / 1e3).toFixed(2)} Kbps`;
    return `${bps} bps`;
  };

  const formatBandwidth = options.formatBandwidth || defaultFormat;

  return {
    name: 'bandwidth',
    validator: (data, context) => {
      const frameLength = options.getFrameLength(data);
      const frequency = options.getFrequency(context);
      const limit = options.getBandwidthLimit(context);

      if (!limit || !frequency) return null;

      const requiredBandwidth = frameLength * 8 * frequency;

      if (requiredBandwidth > limit) {
        return {
          level: 'error',
          rowIndex: -1,
          field: 'bandwidth',
          fieldLabel: '带宽',
          message: `数据带宽需求 (${formatBandwidth(requiredBandwidth)}) 超出限制 (${formatBandwidth(limit)})`,
          value: requiredBandwidth,
          suggestion: `当前帧长度 ${frameLength} 字节，传输频率 ${frequency}Hz`,
        };
      }

      if (requiredBandwidth > limit * 0.8) {
        return {
          level: 'warning',
          rowIndex: -1,
          field: 'bandwidth',
          fieldLabel: '带宽',
          message: `带宽使用率已达 ${Math.round((requiredBandwidth / limit) * 100)}%`,
          value: requiredBandwidth,
          suggestion: '建议预留一定带宽余量',
        };
      }

      return null;
    },
  };
};

/**
 * 创建帧长度校验器
 */
export const createFrameLengthValidator = (options: {
  /** 获取实际帧长度的函数 */
  getActualLength: (data: any[]) => number;
  /** 获取配置的帧长度限制 */
  getConfiguredLimit?: (context?: any) => number | undefined;
  /** 总线类型帧长度限制 */
  busLimits?: Record<string, number>;
  /** 获取当前总线类型 */
  getBusType?: (context?: any) => string | undefined;
}): GlobalValidator => {
  return {
    name: 'frameLength',
    validator: (data, context) => {
      const actualLength = options.getActualLength(data);
      const configuredLimit = options.getConfiguredLimit?.(context);
      const busType = options.getBusType?.(context);
      const busLimit = busType && options.busLimits ? options.busLimits[busType] : undefined;

      const issues: ValidationIssue[] = [];

      if (configuredLimit && actualLength > configuredLimit) {
        issues.push({
          level: 'error',
          rowIndex: -1,
          field: 'frameLength',
          fieldLabel: '帧长度',
          message: `实际数据长度 (${actualLength} 字节) 超出配置的帧长度 (${configuredLimit} 字节)`,
          value: actualLength,
          suggestion: '请增加配置的帧长度或减少字段数据',
        });
      }

      if (busLimit && actualLength > busLimit) {
        issues.push({
          level: 'error',
          rowIndex: -1,
          field: 'frameLength',
          fieldLabel: '帧长度',
          message: `实际数据长度 (${actualLength} 字节) 超出 ${busType} 总线限制 (${busLimit} 字节)`,
          value: actualLength,
          suggestion: `${busType} 总线单帧最大支持 ${busLimit} 字节`,
        });
      }

      return issues.length > 0 ? issues : null;
    },
  };
};

/**
 * 创建数值范围溢出校验器
 */
export const createValueRangeValidator = (options: {
  /** 数据类型字段名 */
  dataTypeField: string;
  /** 值域字段名 */
  valueRangeField: string;
  /** 数据类型对应的值范围 */
  typeRanges: Record<string, { min: number; max: number }>;
}): GlobalValidator => {
  return {
    name: 'valueRange',
    validator: (data) => {
      const issues: ValidationIssue[] = [];

      data.forEach((row, index) => {
        const dataType = row[options.dataTypeField];
        const valueRange = row[options.valueRangeField];

        if (!dataType || !valueRange) return;

        const typeKey = String(dataType).toUpperCase();
        const range = options.typeRanges[typeKey];
        if (!range) return;

        // 尝试从值域中提取数值范围
        const rangeMatch = String(valueRange).match(
          /(-?\d+(?:\.\d+)?)\s*[-~,]\s*(-?\d+(?:\.\d+)?)/
        );
        if (rangeMatch) {
          const minVal = parseFloat(rangeMatch[1]);
          const maxVal = parseFloat(rangeMatch[2]);

          if (minVal < range.min || maxVal > range.max) {
            issues.push({
              level: 'error',
              rowIndex: index,
              field: options.valueRangeField,
              fieldLabel: '值域',
              message: `值域 [${minVal}, ${maxVal}] 超出 ${dataType} 的有效范围 [${range.min}, ${range.max}]`,
              value: valueRange,
              suggestion: `${dataType} 的有效范围是 ${range.min} ~ ${range.max}`,
            });
          }
        }
      });

      return issues.length > 0 ? issues : null;
    },
  };
};

/**
 * 创建唯一性校验器
 */
export const createUniqueValidator = (options: {
  /** 需要唯一的字段名 */
  field: string;
  /** 字段显示名称 */
  fieldLabel?: string;
  /** 是否忽略空值 */
  ignoreEmpty?: boolean;
}): GlobalValidator => {
  return {
    name: `unique-${options.field}`,
    validator: (data) => {
      const issues: ValidationIssue[] = [];
      const seen = new Map<any, number>();

      data.forEach((row, index) => {
        const value = row[options.field];
        if (options.ignoreEmpty !== false && isEmpty(value)) return;

        if (seen.has(value)) {
          issues.push({
            level: 'error',
            rowIndex: index,
            field: options.field,
            fieldLabel: options.fieldLabel || options.field,
            message: `"${value}" 与第 ${seen.get(value)! + 1} 行重复`,
            value,
            suggestion: '请确保此字段值唯一',
          });
        } else {
          seen.set(value, index);
        }
      });

      return issues.length > 0 ? issues : null;
    },
  };
};

/**
 * v-copyText 复制文本内容
 * Copyright (c) 2022 ruoyi
 */

export default {
  beforeMount(el, { value, arg }) {
    if (arg === 'callback') {
      el.$copyCallback = value;
    } else {
      el.$copyValue = value;
      const handler = () => {
        copyTextToClipboard(el.$copyValue);
        if (el.$copyCallback) {
          el.$copyCallback(el.$copyValue);
        }
      };
      el.addEventListener('click', handler);
      el.$destroyCopy = () => el.removeEventListener('click', handler);
    }
  },
};

function copyTextToClipboard(input, { target = document.body } = {}) {
  const element = document.createElement('textarea');
  const previouslyFocusedElement = document.activeElement;

  element.value = input;

  // Prevent keyboard from showing on mobile
  element.setAttribute('readonly', '');

  element.style.contain = 'strict';
  element.style.position = 'absolute';
  element.style.left = '-9999px';
  element.style.fontSize = '12pt'; // Prevent zooming on iOS

  const selection = document.getSelection();
  const originalRange = selection.rangeCount > 0 && selection.getRangeAt(0);

  target.append(element);
  element.select();

  // Explicit selection workaround for iOS
  element.selectionStart = 0;
  element.selectionEnd = input.length;

  let isSuccess = false;
  try {
    isSuccess = document.execCommand('copy');
  } catch {}

  element.remove();

  if (originalRange) {
    selection.removeAllRanges();
    selection.addRange(originalRange);
  }

  // Get the focus back on the previously focused element, if any
  if (previouslyFocusedElement) {
    previouslyFocusedElement.focus();
  }

  return isSuccess;
}

/**
 * v-hasPermi 操作权限处理
 * Copyright (c) 2019 ruoyi
 */

import useUserStore from '@/store/modules/user';

export default {
  mounted(el, binding, vnode) {
    const { value } = binding;
    const all_permission = '*:*:*';
    const permissions = useUserStore().permissions;

    if (value && value instanceof Array && value.length > 0) {
      const permissionFlag = value;

      const hasPermissions = permissions.some((permission) => {
        return all_permission === permission || permissionFlag.includes(permission);
      });

      if (!hasPermissions) {
        el.parentNode && el.parentNode.removeChild(el);
      }
    } else {
      throw new Error(`请设置操作权限标签值`);
    }
  },
};

/**
 * v-hasRole 角色权限处理
 * Copyright (c) 2019 ruoyi
 */

import useUserStore from '@/store/modules/user';

export default {
  mounted(el, binding, vnode) {
    const { value } = binding;
    const super_admin = 'admin';
    const roles = useUserStore().roles;

    if (value && value instanceof Array && value.length > 0) {
      const roleFlag = value;

      const hasRole = roles.some((role) => {
        return super_admin === role || roleFlag.includes(role);
      });

      if (!hasRole) {
        el.parentNode && el.parentNode.removeChild(el);
      }
    } else {
      throw new Error(`请设置角色权限标签值`);
    }
  },
};

import { setupWorker, type SetupWorker } from 'msw/browser';

import { createScenarioHandlers } from './scenarios';
import type { MockRuntimeHandler, MockScenario, MockStrategy, StartMockOptions } from './types';

declare global {
  interface Window {
    __MSW_WORKER__?: SetupWorker;
    __MSW_STRATEGY__?: MockStrategy;
    __MSW_SCENARIO__?: MockScenario;
    __MSW_RUNTIME_HANDLERS__?: MockRuntimeHandler[];
  }
}

function ensureWorker(
  strategy: MockStrategy,
  scenario: MockScenario,
  handlers: MockRuntimeHandler[]
): SetupWorker {
  const existing = window.__MSW_WORKER__;
  if (existing) {
    existing.resetHandlers(...handlers);
    window.__MSW_STRATEGY__ = strategy;
    window.__MSW_SCENARIO__ = scenario;
    window.__MSW_RUNTIME_HANDLERS__ = handlers;
    return existing;
  }

  const worker = setupWorker(...handlers);
  window.__MSW_WORKER__ = worker;
  window.__MSW_STRATEGY__ = strategy;
  window.__MSW_SCENARIO__ = scenario;
  window.__MSW_RUNTIME_HANDLERS__ = handlers;
  return worker;
}

export async function startBrowserMock(
  options: StartMockOptions = {}
): Promise<SetupWorker | undefined> {
  if (typeof window === 'undefined') {
    return undefined;
  }

  const strategy: MockStrategy = options.strategy ?? 'fallback';
  const scenario: MockScenario = options.scenario ?? (strategy === 'pure' ? 'pure' : 'default');
  const handlers: MockRuntimeHandler[] =
    options.handlers ?? createScenarioHandlers(strategy, scenario);

  const worker = ensureWorker(strategy, scenario, handlers);
  await worker.start({
    onUnhandledRequest: options.onUnhandledRequest ?? 'bypass',
  });
  return worker;
}

// Vite HMR 热更新支持
if (import.meta.hot) {
  import.meta.hot.accept('./handlers/index', () => {
    const worker = window.__MSW_WORKER__;
    const strategy = window.__MSW_STRATEGY__ ?? 'fallback';
    const scenario = window.__MSW_SCENARIO__ ?? 'default';
    if (worker) {
      const handlers =
        window.__MSW_RUNTIME_HANDLERS__ ?? createScenarioHandlers(strategy, scenario);
      worker.resetHandlers(...handlers);
      console.log('[MSW] Handlers 已热更新');
    }
  });
}

