import router from './router';
import NProgress from 'nprogress';
import 'nprogress/nprogress.css';
import { getToken } from '@/utils/auth';
import { isPathMatch } from '@/utils/validate';
import { isRelogin } from '@/utils/request';
import useUserStore from '@/store/modules/user';
import useSettingsStore from '@/store/modules/settings';
import usePermissionStore from '@/store/modules/permission';
import type { RouteLocationNormalized, NavigationGuardNext } from 'vue-router';
import { isDemoOfflineMode, resolveRuntimeConfig } from '@/mocks/runtime/mode';

NProgress.configure({ showSpinner: false });

const whiteList: string[] = ['/login', '/register'];
let restoringSessionPromise: Promise<boolean> | null = null;

const isWhiteList = (path: string): boolean => {
  return whiteList.some((pattern) => isPathMatch(pattern, path));
};

const isAuthExpiredError = (error: unknown): boolean => {
  const message = (error as { message?: string })?.message || '';
  const status = (error as { response?: { status?: number } })?.response?.status;
  return status === 401 || message.includes('401') || message.includes('会话已过期');
};

const resolveLandingRedirect = (path: string, firstMenuPath: string): string => {
  if (!firstMenuPath) {
    return '';
  }
  if (path === '/' || path === '') {
    return firstMenuPath;
  }
  if (path === '/index' && firstMenuPath !== '/index') {
    return firstMenuPath;
  }
  return '';
};

const restoreSessionOnce = (): Promise<boolean> => {
  if (!restoringSessionPromise) {
    restoringSessionPromise = useUserStore()
      .restoreSession()
      .finally(() => {
        restoringSessionPromise = null;
      });
  }
  return restoringSessionPromise;
};

const shouldAttemptSilentSessionRestore = (): boolean => {
  return !isDemoOfflineMode(resolveRuntimeConfig().mode);
};

router.beforeEach(
  (to: RouteLocationNormalized, from: RouteLocationNormalized, next: NavigationGuardNext) => {
    NProgress.start();
    if (getToken()) {
      const permissionStore = usePermissionStore();
      if (to.meta.title) {
        useSettingsStore().setTitle(to.meta.title as string);
      }
      /* has token*/
      if (to.path === '/login') {
        next({ path: '/' });
        NProgress.done();
      } else if (isWhiteList(to.path)) {
        next();
      } else {
        if (useUserStore().roles.length === 0) {
          isRelogin.show = true;
          // 判断当前用户是否已拉取完user_info信息
          useUserStore()
            .getInfo()
            .then(() => permissionStore.generateRoutes())
            .then(() => {
              isRelogin.show = false;
              const redirectPath = resolveLandingRedirect(to.path, permissionStore.firstMenuPath);
              if (redirectPath) {
                next({ path: redirectPath, replace: true });
              } else {
                next({ ...to, replace: true }); // hack方法 确保addRoutes已完成
              }
            })
            .catch((err: unknown) => {
              isRelogin.show = false;
              useUserStore()
                .logOut({ silentSuccess: true, silentError: true })
                .then(() => {
                  if (!isAuthExpiredError(err)) {
                    const errorMsg = (err as { message?: string })?.message || '获取用户信息失败';
                    console.error('[permission] restore user info failed:', errorMsg, err);
                  }
                  next({ path: '/' });
                });
            });
        } else {
          const redirectPath = resolveLandingRedirect(to.path, permissionStore.firstMenuPath);
          if (redirectPath) {
            next({ path: redirectPath, replace: true });
            NProgress.done();
          } else {
            next();
          }
        }
      }
    } else {
      // 没有token
      if (isWhiteList(to.path)) {
        // 在免登录白名单，直接进入
        next();
      } else if (!shouldAttemptSilentSessionRestore()) {
        next(`/login?redirect=${to.fullPath}`);
        NProgress.done();
      } else {
        restoreSessionOnce()
          .then((restored) => {
            if (restored) {
              next({ ...to, replace: true });
              return;
            }
            next(`/login?redirect=${to.fullPath}`);
            NProgress.done();
          })
          .catch(() => {
            next(`/login?redirect=${to.fullPath}`);
            NProgress.done();
          });
      }
    }
  }
);

router.afterEach(() => {
  NProgress.done();
});

import { ElLoading, ElMessage } from 'element-plus';
import { saveAs } from 'file-saver';
import { http } from '@/utils/http';
import errorCode from '@/utils/errorCode';
import { blobValidate } from '@/utils/ruoyi';

let downloadLoadingInstance;

const downloadRequestOptions = {
  isReturnNativeResponse: true,
  isTransformResponse: false,
};

async function requestFile(config) {
  return http.get(
    {
      responseType: 'blob',
      feedback: { mode: 'silent' },
      ...config,
    },
    downloadRequestOptions
  );
}

async function handleBlobResponse(response, defaultName, mimeType) {
  const data = response?.data;
  if (blobValidate(data)) {
    const inferredName =
      response?.headers?.['download-filename'] &&
      decodeURIComponent(response.headers['download-filename']);
    const blob = mimeType ? new Blob([data], { type: mimeType }) : new Blob([data]);
    saveAs(blob, inferredName || defaultName || 'download');
    return;
  }
  await printErrMsg(data);
}

async function printErrMsg(data) {
  try {
    const text =
      typeof data === 'string' ? data : typeof data?.text === 'function' ? await data.text() : '';
    if (!text) {
      ElMessage.error('下载文件出现错误，请联系管理员！');
      return;
    }
    const rspObj = JSON.parse(text);
    const errMsg =
      rspObj?.detail ||
      rspObj?.title ||
      errorCode[rspObj?.errorCode] ||
      errorCode[rspObj?.status] ||
      errorCode['default'];
    ElMessage.error(errMsg);
  } catch (error) {
    console.error(error);
    ElMessage.error('下载文件出现错误，请联系管理员！');
  }
}

export default {
  async name(name, isDelete = true) {
    try {
      const url = `/common/download?fileName=${encodeURIComponent(name)}&delete=${isDelete}`;
      const response = await requestFile({ url });
      await handleBlobResponse(response, name);
    } catch (error) {
      console.error(error);
      ElMessage.error('下载文件出现错误，请联系管理员！');
    }
  },
  async resource(resource) {
    try {
      const url = `/common/download/resource?resource=${encodeURIComponent(resource)}`;
      const response = await requestFile({ url });
      await handleBlobResponse(response, resource);
    } catch (error) {
      console.error(error);
      ElMessage.error('下载文件出现错误，请联系管理员！');
    }
  },
  async zip(url, name) {
    // The mask colour comes from the theme (--el-mask-color).
    downloadLoadingInstance = ElLoading.service({
      text: '正在下载数据，请稍候',
    });
    try {
      const response = await requestFile({ url });
      await handleBlobResponse(response, name, 'application/zip');
    } catch (error) {
      console.error(error);
      ElMessage.error('下载文件出现错误，请联系管理员！');
    } finally {
      downloadLoadingInstance?.close?.();
    }
  },
  saveAs(text, name, opts) {
    saveAs(text, name, opts);
  },
  printErrMsg,
};

import { App, h } from 'vue';
import VXETable from 'vxe-table';
import 'vxe-table/lib/style.css';
import '@zxio/zxui/style/vxe-table.css';
import '@/components/ui/VxeTableValidation/validation.less'; // VXE-Table 通用校验样式
import VXETablePluginElement from 'vxe-table-plugin-element';
import zhCN from 'vxe-table/lib/locale/lang/zh-CN';
import VxeDictAutocomplete from '@/components/business/VxeDictAutocomplete/index.vue';
import { installVxeThemeLayout } from './vxe-layout';

type DictRendererEvents = {
  input?: (args: Record<string, unknown>) => void;
  change?: (args: Record<string, unknown>) => void;
};

type DictRendererProps = {
  dictType?: string;
  placeholder?: string;
  disabled?: boolean;
  inputType?: string;
  clearable?: boolean;
};

type DictRendererOptions = {
  props?: DictRendererProps | ((params: DictRendererParams) => DictRendererProps);
  events?: DictRendererEvents;
};

type DictRendererRow = Record<string, string | number | undefined>;

type DictRendererParams = {
  row: DictRendererRow;
  column: { field: string };
  [key: string]: unknown;
};

export function setupVXETable(app: App) {
  installVxeThemeLayout(app);
  VXETable.use(VXETablePluginElement);
  VXETable.setConfig({
    i18n: (key, _args) => zhCN[key],
  });

  VXETable.renderer.add('DictAutocomplete', {
    // Ensure the input is focused as soon as the cell enters edit mode
    autofocus: '.el-input__inner',
    renderEdit(renderOpts, params) {
      const option = renderOpts as DictRendererOptions;
      const typedParams = params as unknown as DictRendererParams;
      const { row, column } = typedParams;
      const field = column.field;
      const propFactory = option.props;
      const resolvedProps =
        typeof propFactory === 'function' ? propFactory(typedParams) : propFactory || {};

      const emitEvent = (eventName: 'input' | 'change', value: string | number | undefined) => {
        const handler = option.events?.[eventName];
        handler?.({
          ...(typedParams as Record<string, unknown>),
          value,
        });
      };

      const normalizeValue = (val: any) => {
        if (val && typeof val === 'object' && 'value' in val) {
          return val.value as string | number | undefined;
        }
        return val as string | number | undefined;
      };

      const handleInput = (value: any) => {
        row[field] = normalizeValue(value) ?? '';
        emitEvent('input', row[field]);
      };

      const handleChange = (value: any) => {
        row[field] = normalizeValue(value) ?? '';
        emitEvent('change', value);
      };

      return [
        h(VxeDictAutocomplete, {
          modelValue: row[field],
          'onUpdate:modelValue': handleInput,
          onChange: handleChange,
          params: {
            ...typedParams,
            ...(resolvedProps as Record<string, unknown>),
          },
        }),
      ];
    },
  });

  app.use(VXETable);
}

