/**
 * Filter attributes that should be applied to
 * the root element of an input component. Remaining
 * attributes should be passed to the <input> element inside.
 */
export function filterInputAttrs(attrs: Record<string, unknown>) {
  const [events, props] = pickWithRest(attrs, [onRE]);
  const inputEvents = omit(events, bubblingEvents);
  const [rootAttrs, inputAttrs] = pickWithRest(props, ['class', 'style', 'id', /^data-/]);
  Object.assign(rootAttrs, events);
  Object.assign(inputAttrs, inputEvents);
  return [rootAttrs, inputAttrs];
}

/**
 * Returns the set difference of B and A, i.e. the set of elements in B but not in A
 */
export function arrayDiff(a: any[], b: any[]): any[] {
  const diff: any[] = [];
  for (let i = 0; i < b.length; i++) {
    if (!a.includes(b[i])) diff.push(b[i]);
  }
  return diff;
}

type IfAny<T, Y, N> = 0 extends 1 & T ? Y : N;
export function wrapInArray<T>(
  v: T | null | undefined
): T extends readonly any[] ? IfAny<T, T[], T> : NonNullable<T>[] {
  return v == null ? ([] as any) : Array.isArray(v) ? (v as any) : ([v] as any);
}

export function defaultFilter(value: any, search: string | null, item: any) {
  return (
    value != null &&
    search != null &&
    typeof value !== 'boolean' &&
    value.toString().toLocaleLowerCase().indexOf(search.toLocaleLowerCase()) !== -1
  );
}

export function debounce(fn: Function, delay: MaybeRef<number>) {
  let timeoutId = 0 as any;
  const wrap = (...args: any[]) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), unref(delay));
  };
  wrap.clear = () => {
    clearTimeout(timeoutId);
  };
  wrap.immediate = fn;
  return wrap;
}

export function throttle<T extends (...args: any[]) => any>(fn: T, limit: number) {
  let throttling = false;
  return (...args: Parameters<T>): void | ReturnType<T> => {
    if (!throttling) {
      throttling = true;
      setTimeout(() => (throttling = false), limit);
      return fn(...args);
    }
  };
}

export function clamp(value: number, min = 0, max = 1) {
  return Math.max(min, Math.min(max, value));
}

export function getDecimals(value: number) {
  const trimmedStr = value.toString().trim();
  return trimmedStr.includes('.') ? trimmedStr.length - trimmedStr.indexOf('.') - 1 : 0;
}

export function padEnd(str: string, length: number, char = '0') {
  return str + char.repeat(Math.max(0, length - str.length));
}

export function padStart(str: string, length: number, char = '0') {
  return char.repeat(Math.max(0, length - str.length)) + str;
}

export function chunk(str: string, size = 1) {
  const chunked: string[] = [];
  let index = 0;
  while (index < str.length) {
    chunked.push(str.substr(index, size));
    index += size;
  }
  return chunked;
}

export function chunkArray(array: any[], size = 1) {
  return Array.from({ length: Math.ceil(array.length / size) }, (v, i) =>
    array.slice(i * size, i * size + size)
  );
}

export function humanReadableFileSize(bytes: number, base: 1000 | 1024 = 1000): string {
  if (bytes < base) {
    return `${bytes} B`;
  }

  const prefix = base === 1024 ? ['Ki', 'Mi', 'Gi'] : ['k', 'M', 'G'];
  let unit = -1;
  while (Math.abs(bytes) >= base && unit < prefix.length - 1) {
    bytes /= base;
    ++unit;
  }
  return `${bytes.toFixed(1)} ${prefix[unit]}B`;
}

export function mergeDeep(
  source: Record<string, any> = {},
  target: Record<string, any> = {},
  arrayFn?: (a: unknown[], b: unknown[]) => unknown[]
) {
  const out: Record<string, any> = {};

  for (const key in source) {
    out[key] = source[key];
  }

  for (const key in target) {
    const sourceProperty = source[key];
    const targetProperty = target[key];

    // Only continue deep merging if
    // both properties are plain objects
    if (isPlainObject(sourceProperty) && isPlainObject(targetProperty)) {
      out[key] = mergeDeep(sourceProperty, targetProperty, arrayFn);

      continue;
    }

    if (arrayFn && Array.isArray(sourceProperty) && Array.isArray(targetProperty)) {
      out[key] = arrayFn(sourceProperty, targetProperty);

      continue;
    }

    out[key] = targetProperty;
  }

  return out;
}

export function flattenFragments(nodes: VNode[]): VNode[] {
  return nodes
    .map((node) => {
      if (node.type === Fragment) {
        return flattenFragments(node.children as VNode[]);
      } else {
        return node;
      }
    })
    .flat();
}

export function toKebabCase(str = '') {
  if (toKebabCase.cache.has(str)) return toKebabCase.cache.get(str)!;
  const kebab = str
    .replace(/[^a-z]/gi, '-')
    .replace(/\B([A-Z])/g, '-$1')
    .toLowerCase();
  toKebabCase.cache.set(str, kebab);
  return kebab;
}
toKebabCase.cache = new Map<string, string>();

export type MaybeRef<T> = T | Ref<T>;

export function findChildrenWithProvide(
  key: InjectionKey<any> | symbol,
  vnode?: VNodeChild
): ComponentInternalInstance[] {
  if (!vnode || typeof vnode !== 'object') return [];

  if (Array.isArray(vnode)) {
    return vnode.map((child) => findChildrenWithProvide(key, child)).flat(1);
  } else if (vnode.suspense) {
    const suspenseContent = (vnode as typeof vnode & { ssContent?: VNodeChild }).ssContent;
    return findChildrenWithProvide(key, suspenseContent);
  } else if (Array.isArray(vnode.children)) {
    return vnode.children.map((child) => findChildrenWithProvide(key, child)).flat(1);
  } else if (vnode.component) {
    const provides = (vnode.component as ComponentInternalInstance & { provides?: object })
      .provides;
    if (provides && Object.getOwnPropertySymbols(provides).includes(key as symbol)) {
      return [vnode.component];
    } else if (vnode.component.subTree) {
      return findChildrenWithProvide(key, vnode.component.subTree).flat(1);
    }
  }

  return [];
}

export class CircularBuffer<T = never> {
  readonly #arr: Array<T> = [];
  #pointer = 0;

  constructor(public readonly size: number) {}

  get isFull() {
    return this.#arr.length === this.size;
  }

  push(val: T) {
    this.#arr[this.#pointer] = val;
    this.#pointer = (this.#pointer + 1) % this.size;
  }

  values(): T[] {
    return this.#arr.slice(this.#pointer).concat(this.#arr.slice(0, this.#pointer));
  }

  clear() {
    this.#arr.length = 0;
    this.#pointer = 0;
  }
}

export type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (
  k: infer I
) => void
  ? I
  : never;

export function getEventCoordinates(e: MouseEvent | TouchEvent) {
  if ('touches' in e) {
    return { clientX: e.touches[0].clientX, clientY: e.touches[0].clientY };
  }

  return { clientX: e.clientX, clientY: e.clientY };
}

// Only allow a single return type
type NotAUnion<T> = [T] extends [infer U] ? _NotAUnion<U, U> : never;
type _NotAUnion<T, U> = U extends any ? ([T] extends [U] ? unknown : never) : never;

type ToReadonlyRefs<T> = { [K in keyof T]: Readonly<ToRef<T[K]>> };

/**
 * Convert a computed ref to a record of refs.
 * The getter function must always return an object with the same keys.
 */
export function destructComputed<T extends object>(
  getter: ComputedGetter<T & NotAUnion<T>>
): ToReadonlyRefs<T>;
export function destructComputed<T extends object>(getter: ComputedGetter<T>) {
  const refs = reactive({}) as T;
  watchEffect(
    () => {
      const base = getter();
      for (const key in base) {
        refs[key] = base[key];
      }
    },
    { flush: 'sync' }
  );
  const obj = {} as ToReadonlyRefs<T>;
  for (const key in refs) {
    obj[key] = toRef(() => refs[key]) as any;
  }
  return obj;
}

/** Array.includes but value can be any type */
export function includes(arr: readonly any[], val: any) {
  return arr.includes(val);
}

export function eventName(propName: string) {
  return propName[2].toLowerCase() + propName.slice(3);
}

// TODO: this should be an array but vue's types don't accept arrays: vuejs/core#8025
export type EventProp<T extends any[] = any[], F = (...args: T) => void> = F;
export const EventProp = <T extends any[] = any[]>() => [Function, Array] as PropType<EventProp<T>>;

export function hasEvent(props: Record<string, any>, name: string) {
  name = 'on' + capitalize(name);
  return !!(
    props[name] ||
    props[`${name}Once`] ||
    props[`${name}Capture`] ||
    props[`${name}OnceCapture`] ||
    props[`${name}CaptureOnce`]
  );
}

export function callEvent<T extends any[]>(
  handler: EventProp<T> | EventProp<T>[] | undefined,
  ...args: T
) {
  if (Array.isArray(handler)) {
    for (const h of handler) {
      h(...args);
    }
  } else if (typeof handler === 'function') {
    handler(...args);
  }
}

export function focusableChildren(el: Element, filterByTabIndex = true) {
  const targets = [
    'button',
    '[href]',
    'input:not([type="hidden"])',
    'select',
    'textarea',
    '[tabindex]',
  ]
    .map((s) => `${s}${filterByTabIndex ? ':not([tabindex="-1"])' : ''}:not([disabled])`)
    .join(', ');
  return [...el.querySelectorAll(targets)] as HTMLElement[];
}

export function getNextElement(
  elements: HTMLElement[],
  location?: 'next' | 'prev',
  condition?: (el: HTMLElement) => boolean
) {
  let _el;
  let idx = elements.indexOf(document.activeElement as HTMLElement);
  const inc = location === 'next' ? 1 : -1;
  do {
    idx += inc;
    _el = elements[idx];
  } while (
    (!_el || _el.offsetParent == null || !(condition?.(_el) ?? true)) &&
    idx < elements.length &&
    idx >= 0
  );
  return _el;
}

export function focusChild(el: Element, location?: 'next' | 'prev' | 'first' | 'last' | number) {
  const focusable = focusableChildren(el);

  if (location == null) {
    if (el === document.activeElement || !el.contains(document.activeElement)) {
      focusable[0]?.focus();
    }
  } else if (location === 'first') {
    focusable[0]?.focus();
  } else if (location === 'last') {
    focusable.at(-1)?.focus();
  } else if (typeof location === 'number') {
    focusable[location]?.focus();
  } else {
    const _el = getNextElement(focusable, location);
    if (_el) _el.focus();
    else focusChild(el, location === 'next' ? 'first' : 'last');
  }
}

export function isEmpty(val: any): boolean {
  return val === null || val === undefined || (typeof val === 'string' && val.trim() === '');
}

export function noop() {}

/** Returns null if the selector is not supported or we can't check */
export function matchesSelector(el: Element | undefined, selector: string): boolean | null {
  const supportsSelector =
    IN_BROWSER &&
    typeof CSS !== 'undefined' &&
    typeof CSS.supports !== 'undefined' &&
    CSS.supports(`selector(${selector})`);

  if (!supportsSelector) return null;

  try {
    return !!el && el.matches(selector);
  } catch (err) {
    return null;
  }
}

export function ensureValidVNode(vnodes: VNodeArrayChildren): VNodeArrayChildren | null {
  return vnodes.some((child) => {
    if (!isVNode(child)) return true;
    if (child.type === Comment) return false;
    return child.type !== Fragment || ensureValidVNode(child.children as VNodeArrayChildren);
  })
    ? vnodes
    : null;
}

type Slot<T> = [T] extends [never] ? () => VNodeChild : (arg: T) => VNodeChild;

export function renderSlot<T>(
  slot: Slot<never> | undefined,
  fallback?: Slot<never> | undefined
): VNodeChild;
export function renderSlot<T>(
  slot: Slot<T> | undefined,
  props: T,
  fallback?: Slot<T> | undefined
): VNodeChild;
export function renderSlot(slot?: Slot<unknown>, props?: unknown, fallback?: Slot<unknown>) {
  // TODO: check if slot returns elements: #18308
  return slot?.(props) ?? fallback?.(props);
}

export function defer(timeout: number, cb: () => void) {
  if (!IN_BROWSER || timeout === 0) {
    cb();

    return () => {};
  }

  const timeoutId = window.setTimeout(cb, timeout);

  return () => window.clearTimeout(timeoutId);
}

export function isClickInsideElement(event: MouseEvent, targetDiv: HTMLElement) {
  const mouseX = event.clientX;
  const mouseY = event.clientY;

  const divRect = targetDiv.getBoundingClientRect();
  const divLeft = divRect.left;
  const divTop = divRect.top;
  const divRight = divRect.right;
  const divBottom = divRect.bottom;

  return mouseX >= divLeft && mouseX <= divRight && mouseY >= divTop && mouseY <= divBottom;
}

export type TemplateRef = {
  (target: Element | ComponentPublicInstance | null): void;
  value: HTMLElement | ComponentPublicInstance | null | undefined;
  readonly el: HTMLElement | undefined;
};
export function templateRef() {
  const el = shallowRef<HTMLElement | ComponentPublicInstance | null>();
  const fn = (target: HTMLElement | ComponentPublicInstance | null) => {
    el.value = target;
  };
  Object.defineProperty(fn, 'value', {
    enumerable: true,
    get: () => el.value,
    set: (val) => (el.value = val),
  });
  Object.defineProperty(fn, 'el', {
    enumerable: true,
    get: () => refElement(el.value),
  });

  return fn as TemplateRef;
}

export function checkPrintable(e: KeyboardEvent) {
  const isPrintableChar = e.key.length === 1;
  const noModifier = !e.ctrlKey && !e.metaKey && !e.altKey;
  return isPrintableChar && noModifier;
}

export type Primitive = string | number | boolean | symbol | bigint;
export function isPrimitive(value: unknown): value is Primitive {
  return (
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean' ||
    typeof value === 'bigint'
  );
}

export function escapeForRegex(sign: string) {
  return '\\^$*+?.()|{}[]'.includes(sign) ? `\\${sign}` : sign;
}

export function extractNumber(
  text: string,
  decimalDigitsLimit: number | null,
  decimalSeparator: string
) {
  const onlyValidCharacters = new RegExp(`[\\d\\-${escapeForRegex(decimalSeparator)}]`);
  const cleanText = text
    .split('')
    .filter((x) => onlyValidCharacters.test(x))
    .filter(
      (x, i, all) =>
        (i === 0 && /[-]/.test(x)) || // sign allowed at the start
        (x === decimalSeparator && i === all.indexOf(x)) || // decimal separator allowed only once
        /\d/.test(x)
    )
    .join('');

  if (decimalDigitsLimit === 0) {
    return cleanText.split(decimalSeparator)[0];
  }

  const decimalPart = new RegExp(`${escapeForRegex(decimalSeparator)}\\d`);
  if (decimalDigitsLimit !== null && decimalPart.test(cleanText)) {
    const parts = cleanText.split(decimalSeparator);
    return [parts[0], parts[1].substring(0, decimalDigitsLimit)].join(decimalSeparator);
  }

  return cleanText;
}

export function camelizeProps<T extends Record<string, unknown>>(props: T | null): T {
  const out = {} as T;
  for (const prop in props) {
    out[camelize(prop) as keyof T] = props[prop];
  }
  return out;
}

export function onlyDefinedProps(props: Record<string, any>) {
  const booleanAttributes = ['checked', 'disabled'];
  return Object.fromEntries(
    Object.entries(props).filter(([key, v]) =>
      booleanAttributes.includes(key) ? !!v : v !== undefined
    )
  );
}

