// 添加日期范围
export function addDateRange(params: any, dateRange: string[], propName?: string): any {
  let search = params;
  dateRange = Array.isArray(dateRange) ? dateRange : [];
  if (typeof propName === 'undefined') {
    search['beginTime'] = dateRange[0];
    search['endTime'] = dateRange[1];
  } else {
    search['begin' + propName] = dateRange[0];
    search['end' + propName] = dateRange[1];
  }
  return search;
}

/**
 * 序列化日期范围参数
 * dateRange: ['2024-01-01', '2024-01-31'] -> beginTime/endTime
 * @param propName 自定义字段名后缀，如 'CreateTime' -> beginCreateTime/endCreateTime
 */
export function serializeDateRange(
  query: Record<string, any>,
  propName?: string
): Record<string, any> {
  const result = { ...query };
  const dateRange = result.dateRange;

  if (Array.isArray(dateRange) && dateRange.length >= 2) {
    const [begin, end] = dateRange;
    if (begin || end) {
      if (propName) {
        result[`begin${propName}`] = begin;
        result[`end${propName}`] = end;
      } else {
        result.beginTime = begin;
        result.endTime = end;
      }
    }
    delete result.dateRange;
  }

  return result;
}

// 回显数据字典
export function selectDictLabel(datas: DictItem[], value: string | number): string {
  if (value === undefined) {
    return '';
  }
  const matched = datas.find((item) => item.value == '' + value);
  if (matched) {
    return matched.label;
  }
  return String(value);
}

// 回显数据字典（字符串数组）
export function selectDictLabels(
  datas: DictItem[],
  value: string | string[],
  separator?: string
): string {
  if (value === undefined || (Array.isArray(value) && value.length === 0)) {
    return '';
  }
  const currentSeparator = separator ?? ',';
  const values = Array.isArray(value)
    ? value
    : value.split(value.includes(currentSeparator) ? currentSeparator : ',');

  return values
    .map((item) => {
      const matched = datas.find((dict) => dict.value == '' + item);
      return matched ? matched.label : item;
    })
    .join(currentSeparator);
}

// 字符串格式化(%s )
export function sprintf(str: string, ...args: any[]): string {
  var flag = true,
    i = 0;
  str = str.replace(/%s/g, function () {
    var arg = args[i++];
    if (typeof arg === 'undefined') {
      flag = false;
      return '';
    }
    return arg;
  });
  return flag ? str : '';
}

