/**
 * 图形样式管理 Composable
 * 负责节点和边的样式控制、状态管理
 */
import { ref } from 'vue';

export function useGraphStyle() {
  const edgeOriginalStyles = new Map();

  // 节点状态样式配置
  const nodeStateStyles = {
    idle: {
      borderColor: '#cbd5f5',
      backgroundColor: '#ffffff',
      boxShadow: '',
      opacity: 1,
    },
    active: {
      borderColor: '#16a34a',
      backgroundColor: '#f0fdf4',
      boxShadow: '0 0 8px rgba(22,163,74,0.45)',
      opacity: 1,
    },
    processing: {
      borderColor: '#f59e0b',
      backgroundColor: '#fffbeb',
      boxShadow: '0 0 8px rgba(245,158,11,0.5)',
      opacity: 1,
    },
    done: {
      borderColor: '#0ea5e9',
      backgroundColor: '#f0f9ff',
      boxShadow: '',
      opacity: 0.95,
    },
    error: {
      borderColor: '#dc2626',
      backgroundColor: '#fee2e2',
      boxShadow: '0 0 8px rgba(220,38,38,0.45)',
      opacity: 1,
    },
    sending: {
      borderColor: '#2563eb',
      backgroundColor: '#eff6ff',
      boxShadow: '0 0 10px rgba(37,99,235,0.45)',
      opacity: 1,
    },
    receiving: {
      borderColor: '#7c3aed',
      backgroundColor: '#f5f3ff',
      boxShadow: '0 0 10px rgba(124,58,237,0.35)',
      opacity: 1,
    },
    synchronizing: {
      borderColor: '#14b8a6',
      backgroundColor: '#ecfeff',
      boxShadow: '0 0 10px rgba(20,184,166,0.4)',
      opacity: 1,
    },
  };

  // 边高亮样式配置
  const edgeHighlightStyles = {
    queued: {
      stroke: '#94a3b8',
      strokeWidth: 2,
      strokeDasharray: 6,
    },
    current: {
      stroke: '#22c55e',
      strokeWidth: 3,
      strokeDasharray: 0,
    },
  };

  /**
   * 判断是否为仿真令牌节点
   */
  function isSimulationToken(node) {
    const data = typeof node?.getData === 'function' ? node.getData() : node?.data;
    return Boolean(data?.isSimToken);
  }

  /**
   * 合并节点样式
   */
  function mergeNodeStyle(currentStyle, preset) {
    const nextStyle = { ...(currentStyle || {}) };
    if (preset.borderColor) {
      nextStyle.borderColor = preset.borderColor;
    } else if (nextStyle.borderColor) {
      delete nextStyle.borderColor;
    }
    if (preset.backgroundColor) {
      nextStyle.backgroundColor = preset.backgroundColor;
    } else if (nextStyle.backgroundColor) {
      delete nextStyle.backgroundColor;
    }
    if (preset.boxShadow !== undefined) {
      nextStyle.boxShadow = preset.boxShadow;
    } else if (nextStyle.boxShadow) {
      delete nextStyle.boxShadow;
    }
    if (preset.opacity !== undefined) {
      nextStyle.opacity = preset.opacity;
    } else if (nextStyle.opacity) {
      delete nextStyle.opacity;
    }
    return nextStyle;
  }

  /**
   * 应用节点状态
   */
  function applyNodeState(node, state) {
    if (!node || isSimulationToken(node)) {
      return;
    }
    const data = node.getData?.() || {};
    const preset = nodeStateStyles[state] || nodeStateStyles.idle;
    const nextStyle = mergeNodeStyle(data.style, preset);
    node.setData(
      {
        ...data,
        simState: state,
        style: nextStyle,
      },
      { overwrite: false }
    );
  }

  /**
   * 获取边的原始样式
   */
  function getEdgeOriginalStyle(edge) {
    if (!edge) {
      return null;
    }
    if (!edgeOriginalStyles.has(edge.id)) {
      const attrs = edge.getAttrs?.() || {};
      const line = attrs.line || {};
      edgeOriginalStyles.set(edge.id, {
        stroke: line.stroke,
        strokeWidth: line.strokeWidth,
        strokeDasharray: line.strokeDasharray,
        targetMarker: line.targetMarker,
      });
    }
    return edgeOriginalStyles.get(edge.id);
  }

  /**
   * 应用边样式
   */
  function applyEdgeStyle(edge, overrides = {}) {
    if (!edge) {
      return;
    }
    const original = getEdgeOriginalStyle(edge) || {};
    let resolvedMarker;
    if (overrides.targetMarker === null) {
      resolvedMarker = null;
    } else if (overrides.targetMarker !== undefined) {
      resolvedMarker = overrides.targetMarker;
    } else {
      resolvedMarker = original.targetMarker;
    }
    edge.attr({
      line: {
        stroke: overrides.stroke ?? original.stroke ?? '#c2c8d5',
        strokeWidth: overrides.strokeWidth ?? original.strokeWidth ?? 1.6,
        strokeDasharray: overrides.strokeDasharray ?? original.strokeDasharray ?? 0,
        targetMarker: resolvedMarker || null,
      },
    });
  }

  /**
   * 恢复边的原始样式
   */
  function restoreEdgeStyle(edge) {
    const original = getEdgeOriginalStyle(edge);
    if (!original) {
      return;
    }
    edge.attr({
      line: {
        stroke: original.stroke ?? '#c2c8d5',
        strokeWidth: original.strokeWidth ?? 1.6,
        strokeDasharray: original.strokeDasharray ?? 0,
        targetMarker: original.targetMarker || null,
      },
    });
  }

  /**
   * 高亮边
   */
  function highlightEdge(edge, mode) {
    if (!edge) {
      return;
    }
    if (!mode || mode === 'idle' || mode === 'completed') {
      restoreEdgeStyle(edge);
      return;
    }
    const preset = edgeHighlightStyles[mode];
    if (!preset) {
      restoreEdgeStyle(edge);
      return;
    }
    applyEdgeStyle(edge, preset);
  }

  /**
   * 重置图的仿真状态
   */
  function resetGraphSimulationState(graph) {
    if (!graph) {
      return;
    }
    const nodes = graph.getNodes?.() || [];
    nodes.forEach((node) => {
      if (isSimulationToken(node)) {
        node.remove?.();
        return;
      }
      applyNodeState(node, 'idle');
    });
    const edges = graph.getEdges?.() || [];
    edges.forEach((edge) => {
      highlightEdge(edge, 'idle');
    });
  }

  /**
   * 标记队列中的边
   */
  function markQueuedEdges(steps) {
    const markedEdges = new Set();
    steps.forEach((step) => {
      if (!markedEdges.has(step.id)) {
        highlightEdge(step.edge, 'queued');
        markedEdges.add(step.id);
      }
    });
    const firstStep = steps[0];
    if (firstStep) {
      applyNodeState(firstStep.sourceNode, 'active');
    }
  }

  return {
    isSimulationToken,
    applyNodeState,
    highlightEdge,
    resetGraphSimulationState,
    markQueuedEdges,
  };
}

/**
 * 仿真核心逻辑 Composable
 * 负责仿真流程控制、步骤管理、状态机
 */
import { ref } from 'vue';
import { ElMessage } from 'element-plus';

// 边阶段序列配置
const EDGE_PHASE_SEQUENCE = [
  {
    key: 'handshake',
    label: '建立握手',
    badge: '握手请求',
    direction: 'forward',
    sourceState: 'active',
    targetState: 'processing',
    postSourceState: 'processing',
    postTargetState: 'active',
    timelineTag: 'info',
    description: (sourceName, targetName, busType) =>
      `${sourceName} 通过 ${busType} 通道向 ${targetName} 发起握手，请求建立通信链路`,
  },
  {
    key: 'handshakeAck',
    label: '握手确认',
    badge: '握手确认',
    direction: 'reverse',
    sourceState: 'processing',
    targetState: 'active',
    postSourceState: 'active',
    postTargetState: 'processing',
    timelineTag: 'success',
    description: (sourceName, targetName) =>
      `${sourceName} 确认收到握手，返回确认信号，${targetName} 准备发送业务数据`,
  },
  {
    key: 'dataTransfer',
    label: '数据传输',
    badge: '数据传输',
    direction: 'forward',
    sourceState: 'sending',
    targetState: 'receiving',
    postSourceState: 'receiving',
    postTargetState: 'sending',
    timelineTag: 'primary',
    description: (sourceName, targetName, busType) =>
      `${sourceName} 正以 ${busType} 总线向 ${targetName} 推送任务数据包`,
  },
  {
    key: 'resultConfirm',
    label: '结果确认',
    badge: '结果确认',
    direction: 'reverse',
    sourceState: 'receiving',
    targetState: 'sending',
    postSourceState: 'done',
    postTargetState: 'done',
    timelineTag: 'warning',
    description: (sourceName, targetName) =>
      `${sourceName} 返回处理确认，${targetName} 完成闭环校验`,
  },
];

const EDGE_PHASE_META = EDGE_PHASE_SEQUENCE.reduce((acc, phase) => {
  acc[phase.key] = phase;
  return acc;
}, {});

const SIMULATION_STEP_DURATION = 950;
const SIMULATION_LOOP_DELAY = 800; // 循环间隔延时

export function useSimulationCore({ graphStyleUtils, animationUtils }) {
  const simulationStatus = ref('idle');
  const simulationSteps = ref([]);
  const simulationPointer = ref(0);
  const simulationLoading = ref(false);
  const simulationNarration = ref(null);
  const simulationTimelinePhases = ref([]);
  const simulationResultPayload = ref(null);
  const simulationLoopCount = ref(0); // 仿真循环次数
  const simulationContinuousMode = ref(true); // 持续仿真模式

  const simulationRunner = {
    currentStepResolver: null,
    activeController: null,
    runningPromise: null,
  };

  /**
   * 导出节点名称
   */
  function deriveNodeName(node) {
    if (!node) {
      return '未命名节点';
    }
    const data = node.getData?.() || {};
    return data.name || data.label || data.deviceName || node.id || '未命名节点';
  }

  /**
   * 导出边总线类型
   */
  function deriveEdgeBusType(edge) {
    if (!edge) {
      return 'BUS';
    }
    const data = edge.getData?.() || {};
    const candidate =
      data.busType || data.interfaceType || data.protocolType || edge.attrs?.line?.busType;
    return candidate || 'BUS';
  }

  /**
   * 构建仿真步骤
   */
  function buildSimulationSteps(graph) {
    const edges = graph?.getEdges?.() || [];
    const orderedSteps = edges
      .map((edge, index) => {
        const sourceId = edge.getSourceCellId?.();
        const targetId = edge.getTargetCellId?.();
        if (!sourceId || !targetId) {
          return null;
        }
        const sourceNode = graph.getCellById?.(sourceId);
        const targetNode = graph.getCellById?.(targetId);
        if (
          !sourceNode ||
          !targetNode ||
          graphStyleUtils.isSimulationToken(sourceNode) ||
          graphStyleUtils.isSimulationToken(targetNode)
        ) {
          return null;
        }
        const order = edge.getData?.()?.simOrder ?? index;
        return {
          id: edge.id,
          edge,
          sourceNode,
          targetNode,
          order,
          sourceName: deriveNodeName(sourceNode),
          targetName: deriveNodeName(targetNode),
          busType: deriveEdgeBusType(edge),
        };
      })
      .filter(Boolean)
      .sort((a, b) => a.order - b.order);

    const expandedSteps = [];
    orderedSteps.forEach((connection) => {
      EDGE_PHASE_SEQUENCE.forEach((phase) => {
        const isForward = phase.direction === 'forward';
        const actualSourceNode = isForward ? connection.sourceNode : connection.targetNode;
        const actualTargetNode = isForward ? connection.targetNode : connection.sourceNode;
        const sourceName = isForward ? connection.sourceName : connection.targetName;
        const targetName = isForward ? connection.targetName : connection.sourceName;
        const description = phase.description
          ? phase.description(sourceName, targetName, connection.busType)
          : `${sourceName} → ${targetName}`;
        expandedSteps.push({
          id: connection.id,
          edge: connection.edge,
          sourceNode: actualSourceNode,
          targetNode: actualTargetNode,
          sourceName,
          targetName,
          order: connection.order,
          direction: isForward ? 'forward' : 'reverse',
          phase: phase.key,
          description,
          busType: connection.busType,
          badge: phase.badge,
          timelineTag: phase.timelineTag,
        });
      });
    });
    return expandedSteps;
  }

  /**
   * 构建阶段时间线
   */
  function buildPhaseTimeline(steps) {
    if (!Array.isArray(steps) || !steps.length) {
      return [];
    }
    return steps.map((step, index) => {
      const meta = EDGE_PHASE_META[step.phase] || {};
      return {
        id: `${step.id}-${step.phase}-${index}`,
        title: `${meta.label || '阶段'}｜${step.sourceName} → ${step.targetName}`,
        description: step.description,
        timestamp: `${((index + 1) * 0.8).toFixed(1)} s`,
        busTypeTag: meta.timelineTag || 'info',
      };
    });
  }

  /**
   * 更新仿真旁白
   */
  function updateSimulationNarration(step) {
    const meta = EDGE_PHASE_META[step?.phase];
    if (!meta) {
      return;
    }
    simulationNarration.value = {
      badge: meta.badge,
      title: `${meta.label}｜${step.sourceName} → ${step.targetName}`,
      description: step.description,
      busType: step.busType,
    };
  }

  /**
   * 重置仿真旁白
   */
  function resetSimulationNarration() {
    simulationNarration.value = null;
  }

  /**
   * 宣布仿真调度
   */
  function announceSimulationSchedule(steps) {
    if (!Array.isArray(steps) || !steps.length) {
      return;
    }
    const edgeCount = new Set(steps.map((item) => item.id)).size;
    simulationNarration.value = {
      badge: '排程',
      title: '仿真路径已生成',
      description: `检测到 ${edgeCount} 条链路，共 ${steps.length} 个阶段，将展示握手、数据传输与确认全过程`,
      busType: '',
    };
  }

  /**
   * 播放单个仿真步骤
   */
  function playSimulationStep(step) {
    return new Promise((resolve) => {
      if (!step?.edge) {
        resolve({ interrupted: true });
        return;
      }
      let settled = false;
      const finish = (payload) => {
        if (settled) {
          return;
        }
        settled = true;
        simulationRunner.currentStepResolver = null;
        simulationRunner.activeController = null;
        resolve(payload);
      };
      simulationRunner.currentStepResolver = finish;
      const phaseMeta = EDGE_PHASE_META[step.phase] || {};
      updateSimulationNarration(step);
      graphStyleUtils.highlightEdge(step.edge, 'current');
      if (phaseMeta.sourceState) {
        graphStyleUtils.applyNodeState(step.sourceNode, phaseMeta.sourceState);
      }
      if (phaseMeta.targetState) {
        graphStyleUtils.applyNodeState(step.targetNode, phaseMeta.targetState);
      }
      const controller = animationUtils.animateEdgeToken(
        step.edge,
        step.direction,
        SIMULATION_STEP_DURATION,
        {
          onCompleted: () => {
            graphStyleUtils.highlightEdge(step.edge, 'completed');
            if (phaseMeta.postSourceState) {
              graphStyleUtils.applyNodeState(step.sourceNode, phaseMeta.postSourceState);
            }
            if (phaseMeta.postTargetState) {
              graphStyleUtils.applyNodeState(step.targetNode, phaseMeta.postTargetState);
            }
            finish({ interrupted: false });
          },
          onCancelled: () => {
            graphStyleUtils.highlightEdge(step.edge, 'queued');
            graphStyleUtils.applyNodeState(step.sourceNode, 'processing');
            finish({ interrupted: true });
          },
        },
        step.busType // 传递总线类型以显示不同颜色
      );
      simulationRunner.activeController = controller;
      if (!controller) {
        finish({ interrupted: true });
      }
    });
  }

  /**
   * 延时工具函数
   */
  function delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * 运行仿真流程（支持持续循环模式）
   */
  function runSimulationFlow() {
    if (simulationRunner.runningPromise) {
      return simulationRunner.runningPromise;
    }
    const runnerTask = (async () => {
      // 持续循环运行
      while (simulationStatus.value === 'running') {
        // 执行一轮完整的仿真步骤
        while (simulationPointer.value < simulationSteps.value.length) {
          if (simulationStatus.value !== 'running') {
            return;
          }
          const step = simulationSteps.value[simulationPointer.value];
          const result = await playSimulationStep(step);
          if (result?.interrupted) {
            return;
          }
          simulationPointer.value += 1;
        }

        // 一轮完成
        simulationLoopCount.value += 1;

        // 如果是持续模式，重置指针并继续循环
        if (simulationContinuousMode.value && simulationStatus.value === 'running') {
          // 更新旁白显示循环信息
          simulationNarration.value = {
            badge: `第${simulationLoopCount.value}轮`,
            title: '仿真持续运行中',
            description: `已完成 ${simulationLoopCount.value} 轮仿真，正在准备下一轮...`,
            busType: '',
          };

          // 重置图形状态，准备下一轮
          const graph = simulationSteps.value[0]?.edge?.model?.graph;
          if (graph) {
            graphStyleUtils.resetGraphSimulationState(graph);
            graphStyleUtils.markQueuedEdges(simulationSteps.value);
          }

          // 重置指针
          simulationPointer.value = 0;

          // 短暂延时后开始下一轮
          await delay(SIMULATION_LOOP_DELAY);
        } else {
          // 非持续模式，正常结束
          finalizeSimulation();
          simulationStatus.value = 'completed';
          return;
        }
      }
    })();
    simulationRunner.runningPromise = runnerTask.finally(() => {
      simulationRunner.runningPromise = null;
    });
    return simulationRunner.runningPromise;
  }

  /**
   * 完成仿真
   */
  function finalizeSimulation() {
    animationUtils.disposeSimulationAnimations();
    animationUtils.disposeAllSimulationTokens();
    simulationNarration.value = {
      badge: '完成',
      title: '仿真结束',
      description: '所有链路已完成握手、数据传输与结果确认，正在生成报表',
      busType: '',
    };
  }

  /**
   * 停止仿真运行器
   */
  function stopSimulationRunner(nextStatus) {
    if (simulationRunner.activeController?.cancel) {
      simulationRunner.activeController.cancel();
    }
    if (typeof simulationRunner.currentStepResolver === 'function') {
      simulationRunner.currentStepResolver({ interrupted: true });
    }
    simulationRunner.activeController = null;
    simulationRunner.currentStepResolver = null;
    simulationRunner.runningPromise = null;
    if (nextStatus) {
      simulationStatus.value = nextStatus;
    }
    if (nextStatus === 'idle') {
      resetSimulationNarration();
    }
  }

  /**
   * 队列仿真结果
   */
  function queueSimulationResult(payload) {
    simulationResultPayload.value = payload;
  }

  /**
   * 设置持续仿真模式
   */
  function setContinuousMode(enabled) {
    simulationContinuousMode.value = enabled;
  }

  /**
   * 重置仿真状态（用于重新开始）
   */
  function resetSimulationState() {
    simulationLoopCount.value = 0;
    simulationPointer.value = 0;
  }

  return {
    simulationStatus,
    simulationSteps,
    simulationPointer,
    simulationLoading,
    simulationNarration,
    simulationTimelinePhases,
    simulationResultPayload,
    simulationLoopCount,
    simulationContinuousMode,
    buildSimulationSteps,
    buildPhaseTimeline,
    announceSimulationSchedule,
    runSimulationFlow,
    stopSimulationRunner,
    queueSimulationResult,
    resetSimulationNarration,
    setContinuousMode,
    resetSimulationState,
  };
}

/**
 * 拓扑管理 Composable
 * 负责拓扑的保存、加载、构建
 */
import { ref } from 'vue';
import { ElMessage } from 'element-plus';
import { saveProjectTopology, getProjectTopology } from '@/api/project/topology';

export function useTopology(version, getGraphInstance, clearGraphContent, isSimulationToken) {
  /**
   * 构建拓扑保存 Payload
   */
  function buildTopologySavePayload(projectId, versionId) {
    const graph = getGraphInstance();
    if (!graph) {
      ElMessage.error('保存失败：图实例不存在');
      return null;
    }

    if (!projectId) {
      ElMessage.error('保存失败：缺少工程ID');
      return null;
    }

    const nodes = (graph.getNodes?.() || []).filter((node) => !isSimulationToken(node));
    const edges = graph.getEdges?.() || [];

    if (!nodes.length) {
      ElMessage.warning('请先在画布中放置设备节点');
      return null;
    }

    const graphJson = typeof graph.toJSON === 'function' ? graph.toJSON() : null;
    if (graphJson && Array.isArray(graphJson.cells)) {
      graphJson.cells = graphJson.cells.filter((cell) => !cell?.data?.isSimToken);
    }

    const nodeSummaries = nodes.map((node) => {
      const data = node.getData?.() || {};
      return {
        id: node.id,
        data,
      };
    });

    const edgeSummaries = edges.map((edge) => {
      const sourceId = edge.getSourceCellId?.();
      const targetId = edge.getTargetCellId?.();
      const sourcePortId = edge.getSourcePortId?.();
      const targetPortId = edge.getTargetPortId?.();
      return {
        id: edge.id,
        sourceId,
        targetId,
        sourcePortId,
        targetPortId,
      };
    });

    return {
      projectId,
      versionId,
      topologyData: {
        version: version.value,
        savedAt: new Date().toISOString(),
        graph: graphJson,
        nodes: nodeSummaries,
        edges: edgeSummaries,
      },
    };
  }

  /**
   * 保存拓扑
   */
  async function saveTopo(projectId, versionId) {
    if (!projectId) {
      ElMessage.error('保存失败：缺少工程ID');
      return false;
    }

    const payload = buildTopologySavePayload(projectId, versionId);
    if (!payload) {
      return false;
    }

    await saveProjectTopology(payload);
    return true;
  }

  /**
   * 恢复保存的拓扑
   */
  function restoreSavedTopology(projectId, versionId, dagRef) {
    if (!projectId) {
      return;
    }

    const tryRestore = () => {
      const graph = dagRef.value?.getGraph?.();
      if (!graph) {
        setTimeout(tryRestore, 200);
        return;
      }

      clearGraphContent(graph);

      getProjectTopology(projectId, versionId)
        .then((res) => {
          // http 客户端已解包 payload.data，res 直接是拓扑数据
          const topoData = res?.topologyData;
          const graphJson = topoData?.graph;
          if (graphJson) {
            graph.fromJSON(graphJson);
          }
        })
        .catch(() => {});
    };

    tryRestore();
  }

  /**
   * 构建端口到对端设备名的映射
   */
  function buildPeerDeviceNameByPort(node, graph) {
    if (!graph || !node) return {};

    const nodeId = node.id;
    const result = {};
    const edges = graph.getEdges?.() || [];

    const registerPeer = (portId, peerName) => {
      if (!portId || !peerName) return;
      const key = String(portId);
      const keys = [key];
      if (key.startsWith('port-')) {
        keys.push(key.replace(/^port-/, ''));
      }

      keys.forEach((k) => {
        if (!result[k]) {
          result[k] = [];
        }
        const list = Array.isArray(result[k]) ? result[k] : [result[k]];
        if (!list.includes(peerName)) {
          result[k] = list.concat(peerName);
        } else {
          result[k] = list;
        }
      });
    };

    edges.forEach((edge) => {
      const sourceId = edge.getSourceCellId?.();
      const targetId = edge.getTargetCellId?.();
      if (!sourceId || !targetId) {
        return;
      }

      let localPortId;
      let peerNodeId;

      if (sourceId === nodeId) {
        localPortId = edge.getSourcePortId?.();
        peerNodeId = targetId;
      } else if (targetId === nodeId) {
        localPortId = edge.getTargetPortId?.();
        peerNodeId = sourceId;
      } else {
        return;
      }

      if (!localPortId || !peerNodeId) {
        return;
      }

      const peerNode = graph.getCellById(peerNodeId);
      const data = peerNode?.getData?.() || {};
      const deviceName = data.name || data.label || data.deviceName || '';

      registerPeer(localPortId, deviceName);
    });

    return result;
  }

  return {
    buildTopologySavePayload,
    saveTopo,
    restoreSavedTopology,
    buildPeerDeviceNameByPort,
  };
}

/**
 * 告警处理 Composable
 *
 * 管理告警的解析、定位和高亮显示
 */

interface AlarmReasonConfig {
  label: string;
  color: string;
}

interface Alarm {
  alarmType?: string;
  targetId?: string;
  targetEdgeId?: string;
  targetNodeId?: string;
  edgeId?: string;
  edgeIds?: string[];
  affectedNodes?: string[];
  affected_nodes?: string[];
  affectedNodeIds?: string[];
  details?: Record<string, any>;
  severity?: string;
}

interface AlarmTargets {
  nodeIds: string[];
  edgeIds: string[];
}

interface TopologyAnimation {
  highlightEdges: (edgeIds: string[], color: string) => void;
  clearEdgeHighlight: (edgeIds: string[]) => void;
  triggerErrorAnimation: (edgeId: string, duration: number) => void;
  setNodeError: (nodeId: string, isError: boolean) => void;
  setNodeActive: (nodeId: string, isActive: boolean, force?: boolean) => void;
}

interface UseAlarmHandlerOptions {
  getGraphInstance: () => any;
  topologyAnimation: TopologyAnimation;
}

/**
 * 告警类型映射配置
 */
export const ALARM_REASON_MAP: Record<string, AlarmReasonConfig> = {
  collision: { label: '冲突', color: '#ef4444' },
  multi_connection: { label: '冲突', color: '#ef4444' },
  packet_loss: { label: '丢包', color: '#f97316' },
  bandwidth_exceed: { label: '超载', color: '#f59e0b' },
  bandwidth_overflow: { label: '超载', color: '#f59e0b' },
  congestion: { label: '超载', color: '#f59e0b' },
  value_overflow: { label: '超载', color: '#f59e0b' },
  disconnect: { label: '链路断开', color: '#60a5fa' },
  link_down: { label: '链路断开', color: '#60a5fa' },
  device_failure: { label: '链路断开', color: '#60a5fa' },
};

// 告警高亮持续时间
export const ALARM_HIGHLIGHT_DURATION = 2800;

/**
 * 告警处理 Composable
 * @param {Object} options 配置选项
 * @param {Function} options.getGraphInstance - 获取图实例的函数
 * @param {Object} options.topologyAnimation - 拓扑动画对象
 */
export function useAlarmHandler(options: UseAlarmHandlerOptions) {
  const { getGraphInstance, topologyAnimation } = options;
  const { highlightEdges, clearEdgeHighlight, triggerErrorAnimation, setNodeError, setNodeActive } =
    topologyAnimation;

  /**
   * 获取告警原因配置
   * @param {string} alarmType - 告警类型
   * @returns {Object} 告警配置
   */
  function getAlarmReason(alarmType?: string): AlarmReasonConfig {
    const key = (alarmType || '').toLowerCase();
    return ALARM_REASON_MAP[key] || { label: '告警', color: '#94a3b8' };
  }

  /**
   * 收集告警关联的目标（节点和边）
   * @param {Object} alarm - 告警对象
   * @returns {Object} { nodeIds: string[], edgeIds: string[] }
   */
  function collectAlarmTargets(alarm: Alarm): AlarmTargets {
    const graph = getGraphInstance();
    const nodeIds = new Set<string>();
    const edgeIds = new Set<string>();

    if (!graph || !alarm) {
      return { nodeIds: [], edgeIds: [] };
    }

    const addByCell = (cellId?: string) => {
      if (!cellId) return;
      const cell = graph.getCellById(cellId);
      if (!cell) return;
      if (cell.isEdge?.()) {
        edgeIds.add(cellId);
      } else {
        nodeIds.add(cellId);
      }
    };

    addByCell(alarm.targetId);
    addByCell(alarm.targetEdgeId);
    addByCell(alarm.targetNodeId);

    if (alarm.edgeId) {
      edgeIds.add(alarm.edgeId);
    }
    if (Array.isArray(alarm.edgeIds)) {
      alarm.edgeIds.forEach((id) => id && edgeIds.add(id));
    }

    // 兼容驼峰和下划线两种格式
    const affectedNodesList = alarm.affectedNodes || alarm.affected_nodes || [];
    if (Array.isArray(affectedNodesList)) {
      affectedNodesList.forEach((id) => id && nodeIds.add(id));
    }
    if (Array.isArray(alarm.affectedNodeIds)) {
      alarm.affectedNodeIds.forEach((id) => id && nodeIds.add(id));
    }

    const details = alarm.details || {};
    addByCell(details.edgeId || details.edge_id);

    // 优先处理 details 中的 nodeId
    const detailNodeId = details.nodeId || details.node_id;
    if (detailNodeId) {
      nodeIds.add(detailNodeId);
    }

    if (Array.isArray(details.connections)) {
      details.connections.forEach((conn: any) => {
        const connEdgeId = conn?.edgeId || conn?.edge_id;
        if (connEdgeId) {
          edgeIds.add(connEdgeId);
        }
      });
    }

    // 通过端口ID查找关联的节点和边
    const portId = details.portId || details.port_id;
    if (portId) {
      const edges = graph.getEdges?.() || [];
      edges.forEach((edge: any) => {
        const sourcePortId = edge.getSourcePortId?.();
        const targetPortId = edge.getTargetPortId?.();
        if (sourcePortId === portId || targetPortId === portId) {
          edgeIds.add(edge.id);
        }
      });
      // 如果还没有找到节点，通过端口遍历节点查找
      if (nodeIds.size === 0) {
        const nodes = graph.getNodes?.() || [];
        nodes.forEach((node: any) => {
          const data = node.getData?.() || {};
          const ports = data.ports || [];
          const hit = ports.some((p: any) => p.id === portId);
          if (hit) {
            nodeIds.add(node.id);
          }
        });
      }
    }

    // 如果有节点但没有边，补充与节点相关的边
    if (nodeIds.size > 0 && edgeIds.size === 0) {
      const edges = graph.getEdges?.() || [];
      edges.forEach((edge: any) => {
        const sourceId = edge.getSourceCellId?.();
        const targetId = edge.getTargetCellId?.();
        if (nodeIds.has(sourceId) || nodeIds.has(targetId)) {
          edgeIds.add(edge.id);
        }
      });
    }

    // 如果有多个节点，补充节点之间的边
    if (nodeIds.size >= 2) {
      const edges = graph.getEdges?.() || [];
      edges.forEach((edge: any) => {
        const sourceId = edge.getSourceCellId?.();
        const targetId = edge.getTargetCellId?.();
        if (nodeIds.has(sourceId) && nodeIds.has(targetId)) {
          edgeIds.add(edge.id);
        }
      });
    }

    return {
      nodeIds: Array.from(nodeIds),
      edgeIds: Array.from(edgeIds),
    };
  }

  /**
   * 处理告警点击
   * @param {Object} alarm - 告警对象
   */
  function handleAlarmClick(alarm: Alarm) {
    const graph = getGraphInstance();
    if (!graph) return;

    const reason = getAlarmReason(alarm?.alarmType);
    const { nodeIds, edgeIds } = collectAlarmTargets(alarm);

    // 优先聚焦到节点（告警通常关联到设备）
    const focusId = nodeIds[0] || edgeIds[0] || alarm?.targetId;

    if (focusId) {
      const cell = graph.getCellById(focusId);
      if (cell) {
        graph.centerCell(cell);
      }
    }

    // 高亮边（如果有）
    if (edgeIds.length > 0) {
      highlightEdges(edgeIds, reason.color);
      setTimeout(() => clearEdgeHighlight(edgeIds), ALARM_HIGHLIGHT_DURATION);
      if (alarm?.severity === 'error' || alarm?.severity === 'critical') {
        edgeIds.forEach((edgeId) => triggerErrorAnimation(edgeId, ALARM_HIGHLIGHT_DURATION));
      }
    }

    // 高亮节点（始终执行，即使没有边）
    if (nodeIds.length > 0) {
      nodeIds.forEach((nodeId) => {
        setNodeError(nodeId, true);
        // 同时设置节点为活跃状态增强视觉效果（force=true 强制生效）
        setNodeActive(nodeId, true, true);
      });
      setTimeout(() => {
        nodeIds.forEach((nodeId) => {
          setNodeError(nodeId, false);
          setNodeActive(nodeId, false, true);
        });
      }, ALARM_HIGHLIGHT_DURATION);
    }
  }

  /**
   * 处理告警过滤变化
   * @param {Object} filter - 过滤条件
   */
  function handleAlarmFilterChange(filter: Record<string, any>) {
    // 告警过滤逻辑（预留扩展）
  }

  return {
    // 常量
    ALARM_REASON_MAP,
    ALARM_HIGHLIGHT_DURATION,

    // 方法
    getAlarmReason,
    collectAlarmTargets,
    handleAlarmClick,
    handleAlarmFilterChange,
  };
}

export default useAlarmHandler;

/**
 * 带宽数据管理Composable
 * 管理带宽数据缓存（600秒滑动窗口）
 * 提供数据聚合和计算功能
 */
import { ref, computed, watch, type Ref, type ComputedRef } from 'vue';

interface BandwidthDataPoint {
  timestamp: number;
  portId: string;
  bandwidthMbps: number;
  bandwidth?: number;
  protocol?: string;
  messageCount?: number;
}

interface PortStats {
  portId: string;
  dataPoints: number;
  averageBandwidth: string;
  peakBandwidth: string;
  messageCount: number;
}

interface OverallStats {
  totalDataPoints: number;
  totalPorts: number;
  averageBandwidth: string;
  peakBandwidth: string;
  totalMessages: number;
}

interface ChartData {
  xData: string[];
  yData: number[];
}

interface MultiPortSeries {
  name: string;
  data: number[];
  xData: string[];
}

export function useBandwidthData() {
  const rawData: Ref<BandwidthDataPoint[]> = ref([]); // 原始带宽数据
  const timeWindow = 600; // 600秒时间窗口
  const selectedPortId: Ref<string | null> = ref(null); // 当前选择的端口
  const autoCleanInterval: Ref<number | null> = ref(null); // 自动清理定时器

  /**
   * 添加带宽数据
   */
  const addBandwidthData = (data: BandwidthDataPoint | BandwidthDataPoint[]) => {
    if (Array.isArray(data)) {
      rawData.value = [...rawData.value, ...data];
    } else {
      rawData.value.push(data);
    }

    // 清理超过时间窗口的数据
    cleanOldData();
  };

  /**
   * 清理超过时间窗口的数据
   */
  const cleanOldData = () => {
    const now = Date.now() / 1000;
    const cutoffTime = now - timeWindow;

    rawData.value = rawData.value.filter((item) => item.timestamp >= cutoffTime);
  };

  /**
   * 获取所有端口列表
   */
  const portList: ComputedRef<string[]> = computed(() => {
    const ports = new Set<string>();
    rawData.value.forEach((item) => {
      if (item.portId) {
        ports.add(item.portId);
      }
    });
    return Array.from(ports);
  });

  /**
   * 获取指定端口的数据
   */
  const getPortData = (portId: string): BandwidthDataPoint[] => {
    return rawData.value.filter((item) => item.portId === portId);
  };

  /**
   * 获取当前选择端口的数据
   */
  const currentPortData: ComputedRef<BandwidthDataPoint[]> = computed(() => {
    if (!selectedPortId.value) {
      return [];
    }
    return getPortData(selectedPortId.value);
  });

  /**
   * 格式化为ECharts数据格式
   */
  const formatForChart = (portId: string | null = null): ChartData => {
    const targetPortId = portId || selectedPortId.value;
    if (!targetPortId) {
      return { xData: [], yData: [] };
    }

    const portData = getPortData(targetPortId);

    // 按时间戳排序
    const sortedData = portData.sort((a, b) => a.timestamp - b.timestamp);

    // 提取时间和带宽值
    const xData = sortedData.map((item) => {
      const date = new Date(item.timestamp * 1000);
      return date.toLocaleTimeString();
    });

    const yData = sortedData.map((item) => item.bandwidthMbps || 0);

    return { xData, yData };
  };

  /**
   * 获取多端口数据（用于多条曲线）
   */
  const formatMultiPortForChart = (portIds: string[]): MultiPortSeries[] => {
    const series: MultiPortSeries[] = [];

    portIds.forEach((portId) => {
      const { xData, yData } = formatForChart(portId);
      series.push({
        name: portId,
        data: yData,
        xData: xData,
      });
    });

    return series;
  };

  /**
   * 计算端口的平均带宽
   */
  const calculateAverageBandwidth = (portId: string): string => {
    const portData = getPortData(portId);
    if (portData.length === 0) return '0';

    const sum = portData.reduce((acc, item) => acc + (item.bandwidthMbps || 0), 0);
    return (sum / portData.length).toFixed(2);
  };

  /**
   * 计算端口的峰值带宽
   */
  const calculatePeakBandwidth = (portId: string): string => {
    const portData = getPortData(portId);
    if (portData.length === 0) return '0';

    const max = Math.max(...portData.map((item) => item.bandwidthMbps || 0));
    return max.toFixed(2);
  };

  /**
   * 获取端口统计信息
   */
  const getPortStats = (portId: string): PortStats => {
    const portData = getPortData(portId);

    return {
      portId,
      dataPoints: portData.length,
      averageBandwidth: calculateAverageBandwidth(portId),
      peakBandwidth: calculatePeakBandwidth(portId),
      messageCount: portData.reduce((acc, item) => acc + (item.messageCount || 0), 0),
    };
  };

  /**
   * 获取所有端口的统计信息
   */
  const getAllPortsStats: ComputedRef<PortStats[]> = computed(() => {
    return portList.value.map((portId) => getPortStats(portId));
  });

  /**
   * 获取总体统计信息
   */
  const overallStats: ComputedRef<OverallStats> = computed(() => {
    if (rawData.value.length === 0) {
      return {
        totalDataPoints: 0,
        totalPorts: 0,
        averageBandwidth: '0',
        peakBandwidth: '0',
        totalMessages: 0,
      };
    }

    const allBandwidths = rawData.value.map((item) => item.bandwidthMbps || 0);
    const sum = allBandwidths.reduce((acc, val) => acc + val, 0);
    const max = Math.max(...allBandwidths);

    return {
      totalDataPoints: rawData.value.length,
      totalPorts: portList.value.length,
      averageBandwidth: (sum / rawData.value.length).toFixed(2),
      peakBandwidth: max.toFixed(2),
      totalMessages: rawData.value.reduce((acc, item) => acc + (item.messageCount || 0), 0),
    };
  });

  /**
   * 启动自动清理
   */
  const startAutoClean = () => {
    if (autoCleanInterval.value) return;

    // 每10秒清理一次过期数据
    autoCleanInterval.value = window.setInterval(() => {
      cleanOldData();
    }, 10000);
  };

  /**
   * 停止自动清理
   */
  const stopAutoClean = () => {
    if (autoCleanInterval.value) {
      clearInterval(autoCleanInterval.value);
      autoCleanInterval.value = null;
    }
  };

  /**
   * 清空数据
   */
  const clearData = () => {
    rawData.value = [];
    selectedPortId.value = null;
    stopAutoClean();
  };

  const getBandwidthValue = (item: Partial<BandwidthDataPoint>): number => {
    return Math.max(0, Number(item.bandwidth ?? item.bandwidthMbps ?? 0));
  };

  const addDataPoint = (data: Partial<BandwidthDataPoint> & Record<string, any>) => {
    const bandwidth = getBandwidthValue(data);
    rawData.value.push({
      timestamp: Number(data.timestamp ?? Date.now()),
      portId: String(data.portId ?? data.protocol ?? 'default'),
      bandwidth,
      bandwidthMbps: bandwidth,
      protocol: data.protocol,
      messageCount: data.messageCount,
    });

    if (rawData.value.length > 100) {
      rawData.value = rawData.value.slice(-100);
    }
    rawData.value.sort((a, b) => a.timestamp - b.timestamp);
  };

  const bandwidthHistory = rawData;

  const currentBandwidth = computed(() => {
    const latest = rawData.value[rawData.value.length - 1];
    return latest ? getBandwidthValue(latest) : 0;
  });

  const peakBandwidth = computed(() => {
    return rawData.value.length ? Math.max(...rawData.value.map(getBandwidthValue)) : 0;
  });

  const averageBandwidth = computed(() => {
    if (!rawData.value.length) return 0;
    return (
      rawData.value.reduce((sum, item) => sum + getBandwidthValue(item), 0) / rawData.value.length
    );
  });

  const getProtocolStats = () => {
    return rawData.value.reduce<Record<string, { total: number; count: number }>>((stats, item) => {
      const protocol = item.protocol || 'unknown';
      stats[protocol] ||= { total: 0, count: 0 };
      stats[protocol].total += getBandwidthValue(item);
      stats[protocol].count += 1;
      return stats;
    }, {});
  };

  const getProtocolUtilization = (protocol: string): number => {
    const stats = getProtocolStats();
    const protocolTotal = stats[protocol]?.total || 0;
    const total = Object.values(stats).reduce((sum, item) => sum + item.total, 0);
    return total ? (protocolTotal / total) * 100 : 0;
  };

  const getUtilization = (maxBandwidth: number): number => {
    if (maxBandwidth <= 0) {
      throw new Error('最大带宽必须大于 0');
    }
    return (currentBandwidth.value / maxBandwidth) * 100;
  };

  const getTimeWindow = (startTime: number, endTime: number) => {
    return rawData.value.filter((item) => item.timestamp >= startTime && item.timestamp <= endTime);
  };

  const getWindowAverage = (startTime: number, endTime: number): number => {
    const windowData = getTimeWindow(startTime, endTime);
    if (!windowData.length) return 0;
    return windowData.reduce((sum, item) => sum + getBandwidthValue(item), 0) / windowData.length;
  };

  const getWindowPeak = (startTime: number, endTime: number): number => {
    const windowData = getTimeWindow(startTime, endTime);
    return windowData.length ? Math.max(...windowData.map(getBandwidthValue)) : 0;
  };

  const getVariance = (): number => {
    if (!rawData.value.length) return 0;
    const average = averageBandwidth.value;
    return (
      rawData.value.reduce((sum, item) => {
        const diff = getBandwidthValue(item) - average;
        return sum + diff * diff;
      }, 0) / rawData.value.length
    );
  };

  const getStandardDeviation = (): number => Math.sqrt(getVariance());

  const detectSpikes = (multiplier = 2) => {
    const average = averageBandwidth.value;
    const threshold = average * multiplier;
    return rawData.value.filter((item) => getBandwidthValue(item) >= threshold);
  };

  const exportCSV = (): string => {
    const lines = rawData.value.map(
      (item) => `${item.timestamp},${getBandwidthValue(item)},${item.protocol || ''}`
    );
    return ['timestamp,bandwidth,protocol', ...lines].join('\n');
  };

  const exportJSON = (): string => JSON.stringify(rawData.value);

  // 监听数据变化，自动启动清理
  watch(
    () => rawData.value.length,
    (newLength) => {
      if (newLength > 0 && !autoCleanInterval.value) {
        startAutoClean();
      } else if (newLength === 0) {
        stopAutoClean();
      }
    }
  );

  return {
    rawData,
    selectedPortId,
    portList,
    currentPortData,
    overallStats,
