/**
 * 故障注入 Composable
 * @param {Ref<string>} sessionId - 会话ID
 * @returns {Object} 故障注入方法和状态
 */
export function useFaultInjection(sessionId: Ref<string | null>) {
  // 活跃的故障列表
  const faults: Ref<Fault[]> = ref([]);
  const faultEvents: Ref<FaultEvent[]> = ref([]);
  const loading: Ref<boolean> = ref(false);

  // 计算属性：按目标分组的故障
  const faultsByTarget: ComputedRef<Record<string, Fault[]>> = computed(() => {
    const grouped: Record<string, Fault[]> = {};
    faults.value.forEach((fault) => {
      const key = fault.targetKey || fault.targetId;
      if (!key) return;
      if (!grouped[key]) grouped[key] = [];
      grouped[key].push(fault);
    });
    return grouped;
  });

  // 计算属性：活跃故障数量
  const activeFaultCount: ComputedRef<number> = computed(() => {
    return faults.value.filter((f) => f.status === 'active').length;
  });

  function normalizeFault(raw: any): Fault | null {
    if (!raw) return null;
    const fault: Fault = {
      faultId: raw.faultId || raw.fault_id || raw.id,
      sessionId: raw.sessionId || raw.session_id,
      faultType: raw.faultType || raw.fault_type || raw.type,
      targetType: raw.targetType || raw.target_type || raw.targetType || 'edge',
      targetId: raw.targetId || raw.target_id || raw.targetId,
      targetKey: raw.targetId || raw.target_id || raw.targetId,
      targetName:
        raw.targetName ||
        raw.target_name ||
        raw.target_label ||
        raw.targetAlias ||
        raw.params?.target_name ||
        raw.params?.targetName,
      params: raw.params || {},
      status: raw.status || 'active',
      startAt: raw.startAt || raw.start_at,
      endAt: raw.endAt || raw.end_at,
      priority: raw.priority ?? 0,
      createTime: raw.createTime || raw.create_time,
      updateTime: raw.updateTime || raw.update_time,
    };
    return fault;
  }

  function upsertFault(local: Fault) {
    const idx = faults.value.findIndex((f) => f.faultId === local.faultId);
    if (idx >= 0) {
      faults.value[idx] = { ...faults.value[idx], ...local };
    } else {
      faults.value.push(local);
    }
  }

  async function fetchFaults(): Promise<Fault[]> {
    if (!sessionId.value) return [];
    loading.value = true;
    try {
      // http 客户端已解包 payload.data，res 直接是故障列表
      const res = await getFaultsApi(sessionId.value);
      const list = Array.isArray(res) ? res : [];
      // 只保留待生效和生效中的故障，避免已清除/过期占位
      faults.value = list
        .map(normalizeFault)
        .filter((f): f is Fault => f !== null && (f.status === 'active' || f.status === 'pending'));
      return faults.value;
    } finally {
      loading.value = false;
    }
  }

  /**
   * 注入故障
   * @param {Object} config - 故障配置
   * @returns {Promise<Object>} 故障信息（包含 _action: 'created'|'updated' 标识）
   */
  async function injectFault(config: FaultConfig): Promise<Fault> {
    if (!sessionId.value) {
      throw new Error('仿真会话不存在');
    }

    const { type, targetId, targetType, params = {}, targetName, targetLabel } = config;

    if (!FAULT_TYPE_CONFIG[type]) {
      throw new Error(`不支持的故障类型: ${type}`);
    }

    const expectedTargetType = FAULT_TYPE_CONFIG[type].targetType;
    if (targetType !== expectedTargetType) {
      throw new Error(`故障类型 ${type} 只能应用于 ${expectedTargetType}`);
    }

    // 始终调用后端，后端实现幂等（同 target+type 会更新而非新增）
    const payload = {
      faultType: type,
      targetId,
      targetType,
      params: {
        ...params,
        targetName: targetName || targetLabel,
        target_name: targetName || targetLabel,
      },
      // 便于后端记录友好名称
      targetName: targetName || targetLabel,
    };

    const response = await injectFaultApi(sessionId.value, payload);
    // 后端返回已解包的数据
    const raw = response || { ...payload, faultId: `fault-${Date.now()}` };
    const fault = normalizeFault(raw);
    if (fault) {
      // 保留后端返回的 _action 标识
      fault._action = raw._action || 'created';
      // 覆盖/补充前端友好名称
      fault.targetName = fault.targetName || targetName || targetLabel;
      upsertFault(fault);
    }
    return fault!;
  }

  /**
   * 清除故障
   * @param {string} faultId - 故障ID
   */
  async function clearFault(faultId: string) {
    if (!sessionId.value) {
      throw new Error('仿真会话不存在');
    }

    await clearFaultApi(sessionId.value, faultId);

    // 直接从列表移除
    const idx = faults.value.findIndex((f) => f.faultId === faultId);
    if (idx >= 0) faults.value.splice(idx, 1);
  }

  /**
   * 清除所有故障（调用后端批量清除接口）
   */
  async function clearAllFaults() {
    if (!sessionId.value) {
      throw new Error('仿真会话不存在');
    }

    await clearAllFaultsApi(sessionId.value);

    // 直接清空列表
    faults.value = [];
  }

  /**
   * 清除指定目标的所有故障
   * @param {string} targetId - 目标ID
   */
  async function clearFaultsByTarget(targetId: string) {
    const targetFaults = faults.value.filter(
      (f) => f.targetId === targetId && f.status === 'active'
    );

    for (const fault of targetFaults) {
      await clearFault(fault.faultId);
    }
  }

  /**
   * 检查目标是否有活跃故障
   * @param {string} targetId - 目标ID
   * @returns {boolean}
   */
  function hasActiveFault(targetId: string): boolean {
    return faults.value.some((f) => f.targetId === targetId && f.status === 'active');
  }

  /**
   * 获取目标的活跃故障
   * @param {string} targetId - 目标ID
   * @returns {Array}
   */
  function getActiveFaults(targetId: string): Fault[] {
    return faults.value.filter((f) => f.targetId === targetId && f.status === 'active');
  }

  /**
   * 重置故障列表
   */
  function reset() {
    faults.value = [];
    faultEvents.value = [];
  }

  function ingestFaultEvents(events: FaultEvent[] = []) {
    events.forEach((evt) => {
      const fault = normalizeFault(evt?.fault);
      if (!fault) return;
      const action = evt?.action;
      // 维护事件窗口
      faultEvents.value.push({ ...evt, fault });
      if (faultEvents.value.length > 200) {
        faultEvents.value.splice(0, faultEvents.value.length - 200);
      }

      // 清除/过期事件：直接移除列表
      if (action === 'cleared' || action === 'expired') {
        const idx = faults.value.findIndex((f) => f.faultId === fault.faultId);
        if (idx >= 0) faults.value.splice(idx, 1);
        return;
      }

      if (action === 'created' || action === 'updated' || action === 'activated') {
        upsertFault(fault);
      }
    });
  }

  return {
    // 状态
    faults,
    faultsByTarget,
    activeFaultCount,
    faultEvents,
    loading,

    // 方法
    injectFault,
    clearFault,
    clearAllFaults,
    clearFaultsByTarget,
    hasActiveFault,
    getActiveFaults,
    reset,
    fetchFaults,
    ingestFaultEvents,
  };
}

export default useFaultInjection;

/**
 * 故障注入 UI 交互 Composable
 *
 * 管理故障注入模式下的 UI 交互逻辑
 * - 边的选中与高亮
 * - 模式进入/退出
 * - 事件监听
 */
import { ref, computed, type Ref, type ComputedRef } from 'vue';
import { ElMessage } from 'element-plus';

// 统一消息配置：短时长 + 合并同类
const msgOpts = { duration: 1500, grouping: true };

interface DockState {
  fault: boolean;
  [key: string]: any;
}

interface FaultInjection {
  faults: Ref<any[]>;
  clearFault: (faultId: string) => Promise<void>;
  clearAllFaults: () => Promise<void>;
  injectFault: (payload: any) => Promise<any>;
  fetchFaults: () => Promise<any[]>;
}

interface FaultTemplate {
  label?: string;
  payload: {
    type: string;
    params?: Record<string, any>;
  };
}

interface UseFaultInjectionUIOptions {
  getGraphInstance: () => any;
  dockState: DockState;
  faultInjection: FaultInjection;
}

/**
 * 故障注入 UI 交互
 * @param {Object} options 配置选项
 * @param {Function} options.getGraphInstance - 获取图实例的函数
 * @param {Ref} options.dockState - dock 状态
 * @param {Object} options.faultInjection - useFaultInjection 返回的对象
 */
export function useFaultInjectionUI(options: UseFaultInjectionUIOptions) {
  const { getGraphInstance, dockState, faultInjection } = options;

  // 选中的链路
  const selectedEdge: Ref<any> = ref(null);

  // 保存边的原始样式
  const edgeOriginalStyles = new Map<string, { stroke: string; strokeWidth: number }>();

  // 已注入故障的边 ID 集合
  const faultedEdges = new Set<string>();

  // 是否处于故障注入模式
  const isFaultInjectionMode: ComputedRef<boolean> = computed(() => dockState.fault);

  function shortId(id?: string): string {
    if (!id) return '未知链路';
    const str = String(id);
    if (str.length <= 12) return str;
    return `${str.slice(0, 6)}...${str.slice(-4)}`;
  }

  /**
   * 获取选中边的 ID
   */
  function getSelectedEdgeId(): string {
    if (!selectedEdge.value) return '';
    return formatEdgeLabel(selectedEdge.value);
  }

  /**
   * 设置边的事件监听
   * @param {Object} graph - 图实例
   */
  function setupEdgeEvents(graph: any) {
    if (!graph) return;

    // 监听边点击事件
    graph.on('edge:click', ({ edge, e }: any) => {
      if (isFaultInjectionMode.value) {
        selectedEdge.value = edge;
        highlightSelectedEdge(edge);
      }
    });

    // 监听空白区域点击，取消选中
    graph.on('blank:click', () => {
      if (isFaultInjectionMode.value && selectedEdge.value) {
        clearSelectedEdge();
      }
    });
  }

  /**
   * 高亮选中的边
   * @param {Object} edge - 边实例
   */
  function highlightSelectedEdge(edge: any) {
    const graph = getGraphInstance();
    if (!graph || !edge) return;

    const selectedId = edge.id || edge.getID?.();

    graph.getEdges().forEach((e: any) => {
      const eId = e.id || e.getID?.();
      // 保存原始样式（如果还没保存）
      if (!edgeOriginalStyles.has(eId)) {
        edgeOriginalStyles.set(eId, {
          stroke: e.attr('line/stroke') || '#64748b',
          strokeWidth: e.attr('line/strokeWidth') || 2,
        });
      }

      if (eId === selectedId) {
        // 选中的边：红色、加粗（故障模式下锁定的边）
        e.attr('line/stroke', '#ef4444');
        e.attr('line/strokeWidth', 6);
      } else {
        // 其他边：恢复原始样式
        const original = edgeOriginalStyles.get(eId);
        if (original) {
          e.attr('line/stroke', original.stroke);
          e.attr('line/strokeWidth', original.strokeWidth);
        }
      }
    });
  }

  /**
   * 清除选中的边
   */
  function clearSelectedEdge() {
    selectedEdge.value = null;
    const graph = getGraphInstance();
    if (!graph) return;

    // 恢复所有边的原始样式（除了已注入故障的边）
    graph.getEdges().forEach((e: any) => {
      const eId = e.id || e.getID?.();
      if (faultedEdges.has(eId)) return; // 保持故障边的红色
      const original = edgeOriginalStyles.get(eId);
      if (original) {
        e.attr('line/stroke', original.stroke);
        e.attr('line/strokeWidth', original.strokeWidth);
      }
    });
  }

  /**
   * 退出故障注入模式（清除所有故障和选中状态）
   */
  async function exitFaultMode() {
    clearSelectedEdge();
    clearAllFaultMarks();
    // 清除所有故障
    await faultInjection.clearAllFaults();
    dockState.fault = false;
  }

  /**
   * 清除单个故障
   * @param {string} faultId - 故障ID
   */
  async function handleFaultClear(faultId: string) {
    // 先找到这个故障对应的边 ID
    const fault = faultInjection.faults.value?.find((f: any) => f.faultId === faultId);
    const edgeId = fault?.targetId || fault?.targetKey;

    await faultInjection.clearFault(faultId);

    // 清除边的故障标记
    if (edgeId) {
      // 检查这条边是否还有其他故障
      const remainingFaults = faultInjection.faults.value?.filter(
        (f: any) => (f.targetId === edgeId || f.targetKey === edgeId) && f.faultId !== faultId
      );
      if (!remainingFaults?.length) {
        clearEdgeFaultMark(edgeId);
      }
    }

    ElMessage.success({ message: '故障已清除', ...msgOpts });
  }

  /**
   * 清除所有故障
   */
  async function handleClearAllFaults() {
    await faultInjection.clearAllFaults();
    clearAllFaultMarks();
    ElMessage.success({ message: '已清除全部故障', ...msgOpts });
  }

  /**
   * 应用故障模板
   * @param {Object} tpl - 模板对象
   * @param {Ref} hoveredEdge - 悬停的边
   */
  async function handleFaultTemplate(tpl: FaultTemplate, hoveredEdge?: Ref<any>) {
    const edge = selectedEdge.value || hoveredEdge?.value;
    const targetId =
      edge?.id || edge?.getID?.() || edge?.getData?.()?.id || edge?.getData?.()?.edgeId;

    if (!targetId) {
      ElMessage.warning({ message: '请先点击链路选中后再应用模板', ...msgOpts });
      return;
    }

    const payload = {
      type: tpl.payload.type,
      targetId,
      targetType: 'edge' as const,
      targetName: formatEdgeLabel(edge),
      // 将友好名称也放入参数，便于后端/事件返回时携带
      params: {
        ...(tpl.payload.params || {}),
        targetName: formatEdgeLabel(edge),
        target_name: formatEdgeLabel(edge),
      },
    };

    const result = await faultInjection.injectFault(payload);
    const faultLabel = tpl.label || tpl.payload.type;
    if (result?._action === 'updated') {
      ElMessage.info({ message: `${faultLabel} 已更新`, ...msgOpts });
    } else {
      ElMessage.success({ message: `${faultLabel} 已注入`, ...msgOpts });
    }

    // 注入后高亮为红色粗线，提示当前链路有故障
    markEdgeAsFaulted(edge);
  }

  /**
   * 将边标记为故障状态（红色粗线）
   */
  function markEdgeAsFaulted(edge: any) {
    if (!edge) return;
    const graph = getGraphInstance();
    if (!graph) return;

    const edgeId = edge.id || edge.getID?.();
    if (!edgeId) return;

    // 记录故障边
    faultedEdges.add(edgeId);

    // 从图中获取边实例并设置样式
    const graphEdge = graph.getCellById(edgeId);
    if (graphEdge?.attr) {
      graphEdge.attr('line/stroke', '#ef4444');
      graphEdge.attr('line/strokeWidth', 6);
    }
  }

  /**
   * 生成链路友好标签：设备A(端口) → 设备B(端口)
   */
  function formatEdgeLabel(edge: any): string {
    if (!edge) return '未知链路';
    const data = edge.getData?.() || {};

    // 优先用图元上已有的友好名称
    const alias = data.alias || data.label || data.name || data.title;
    const id = edge.id || edge.getID?.() || data.id || data.edgeId;

    const sourceNode = edge.getSourceNode?.();
    const targetNode = edge.getTargetNode?.();
    const sourceData = sourceNode?.getData?.() || {};
    const targetData = targetNode?.getData?.() || {};

    const srcName = sourceData.name || sourceData.label || sourceData.deviceName;
    const dstName = targetData.name || targetData.label || targetData.deviceName;
    const srcPort = data.sourcePortName || data.sourcePort || sourceData.portName;
    const dstPort = data.targetPortName || data.targetPort || targetData.portName;

    if (srcName || dstName) {
      const left = srcName || '源设备';
      const right = dstName || '目标设备';
      const leftPort = srcPort ? `(${srcPort})` : '';
      const rightPort = dstPort ? `(${dstPort})` : '';
      return `${left}${leftPort} → ${right}${rightPort}`;
    }

    return alias || shortId(id);
  }

  /**
   * 清除边的故障标记
   */
  function clearEdgeFaultMark(edgeId: string) {
    if (!edgeId) return;
    faultedEdges.delete(edgeId);

    const graph = getGraphInstance();
    if (!graph) return;

    const edge = graph.getCellById(edgeId);
    if (!edge) return;

    const original = edgeOriginalStyles.get(edgeId);
    if (original) {
      edge.attr('line/stroke', original.stroke);
      edge.attr('line/strokeWidth', original.strokeWidth);
    }
  }

  /**
   * 清除所有故障边标记
   */
  function clearAllFaultMarks() {
    const graph = getGraphInstance();
    if (!graph) return;

    faultedEdges.forEach((edgeId) => {
      const edge = graph.getCellById(edgeId);
      if (!edge) return;
      const original = edgeOriginalStyles.get(edgeId);
      if (original) {
        edge.attr('line/stroke', original.stroke);
        edge.attr('line/strokeWidth', original.strokeWidth);
      }
    });
    faultedEdges.clear();
  }

  /**
   * 刷新故障列表
   */
  async function refreshFaults() {
    await faultInjection.fetchFaults();
  }

  return {
    // 状态
    selectedEdge,
    isFaultInjectionMode,

    // 方法
    getSelectedEdgeId,
    setupEdgeEvents,
    highlightSelectedEdge,
    clearSelectedEdge,
    exitFaultMode,
    handleFaultClear,
    handleClearAllFaults,
    handleFaultTemplate,
    refreshFaults,
  };
}

export default useFaultInjectionUI;

/**
 * 健康自检 Composable
 * 用于仿真前的配置完整性和有效性检查
 *
 * 检查项目：
 * 1. 拓扑完整性检查 - 节点数量、连接存在性
 * 2. 端口配置完整性检查 - 各协议类型必需参数
 * 3. 连接有效性检查 - 协议类型匹配、端口存在性
 * 4. 通信参数一致性检查 - 波特率匹配、IP地址有效性
 * 5. 配置冲突检测 - 回环
 */

/**
 * 检查结果状态
 */
export type CheckStatus = 'success' | 'warning' | 'error';

/**
 * 检查项结果
 */
export interface CheckItem {
  id: string;
  category: string;
  name: string;
  status: CheckStatus;
  message: string;
  suggestion?: string;
  details?: Record<string, any>;
}

/**
 * 健康检查报告
 */
export interface HealthReport {
  healthy: boolean;
  canSimulate: boolean;
  totalChecks: number;
  passedChecks: number;
  warningChecks: number;
  errorChecks: number;
  items: CheckItem[];
  timestamp: string;
}

// 协议类型必需参数配置
const PROTOCOL_REQUIRED_PARAMS: Record<string, string[]> = {
  // 目前协议编辑界面仅提供波特率，数据位/停止位/校验暂未收集
  RS422: ['baudRate'],
  RS485: ['baudRate'],
  CAN: ['baudRate'],
  LAN: ['ipAddress', 'port', 'protocol'],
  '1553B': ['busAddress', 'rtAddress', 'subAddress'],
};

// 协议类型显示名称
const PROTOCOL_NAMES: Record<string, string> = {
  RS422: 'RS-422',
  RS485: 'RS-485',
  CAN: 'CAN 总线',
  LAN: '以太网',
  '1553B': 'MIL-STD-1553B',
};

// 参数显示名称
const PARAM_NAMES: Record<string, string> = {
  baudRate: '波特率',
  dataBits: '数据位',
  stopBits: '停止位',
  parity: '校验方式',
  canMode: '工作模式',
  ipAddress: 'IP 地址',
  port: '端口号',
  protocol: '协议类型',
  busAddress: '总线地址',
  rtAddress: 'RT 地址',
  subAddress: '子地址',
};

export function useHealthCheck() {
  /**
   * 执行健康自检
   * @param {Object} graph - X6 图实例
   * @param {Function} isSimulationToken - 判断是否为仿真令牌的函数
   * @returns {HealthReport} 健康检查报告
   */
  function runHealthCheck(
    graph: any,
    isSimulationToken: (node: any) => boolean = () => false
  ): HealthReport {
    const items: CheckItem[] = [];
    const timestamp = new Date().toISOString();

    if (!graph) {
      return {
        healthy: false,
        canSimulate: false,
        totalChecks: 1,
        passedChecks: 0,
        warningChecks: 0,
        errorChecks: 1,
        items: [
          {
            id: 'graph-instance',
            category: '系统检查',
            name: '图实例检查',
            status: 'error',
            message: '图实例不存在，无法执行健康检查',
            suggestion: '请刷新页面后重试',
          },
        ],
        timestamp,
      };
    }

    // 获取节点和边
    const nodes = (graph.getNodes?.() || []).filter((node: any) => !isSimulationToken(node));
    const edges = graph.getEdges?.() || [];

    // 1. 拓扑完整性检查
    items.push(...checkTopologyIntegrity(nodes, edges));

    // 2. 端口配置完整性检查
    items.push(...checkPortConfiguration(nodes));

    // 3. 连接有效性检查
    items.push(...checkConnectionValidity(nodes, edges));

    // 4. 通信参数一致性检查
    items.push(...checkParameterConsistency(nodes, edges));

    // 5. 配置冲突检测
    items.push(...checkConfigurationConflicts(nodes, edges));

    // 计算统计信息
    const passedChecks = items.filter((item) => item.status === 'success').length;
    const warningChecks = items.filter((item) => item.status === 'warning').length;
    const errorChecks = items.filter((item) => item.status === 'error').length;

    // 判断是否可以仿真（无致命错误即可）
    const canSimulate = errorChecks === 0 && nodes.length >= 2 && edges.length > 0;

    return {
      healthy: errorChecks === 0 && warningChecks === 0,
      canSimulate,
      totalChecks: items.length,
      passedChecks,
      warningChecks,
      errorChecks,
      items,
      timestamp,
    };
  }

  /**
   * 1. 拓扑完整性检查
   */
  function checkTopologyIntegrity(nodes: any[], edges: any[]): CheckItem[] {
    const items: CheckItem[] = [];

    // 1.1 设备节点数量检查
    if (nodes.length === 0) {
      items.push({
        id: 'topology-nodes-empty',
        category: '拓扑完整性',
        name: '设备节点检查',
        status: 'error',
        message: '拓扑图中没有任何设备节点',
        suggestion: '请从设备库拖拽至少2个设备到画布上',
      });
    } else if (nodes.length === 1) {
      items.push({
        id: 'topology-nodes-single',
        category: '拓扑完整性',
        name: '设备节点检查',
        status: 'error',
        message: '仅有1个设备节点，无法进行通信仿真',
        suggestion: '通信仿真至少需要2个设备节点',
      });
    } else {
      items.push({
        id: 'topology-nodes-ok',
        category: '拓扑完整性',
        name: '设备节点检查',
        status: 'success',
        message: `共有 ${nodes.length} 个设备节点`,
      });
    }

    // 1.2 连接检查
    if (edges.length === 0) {
      items.push({
        id: 'topology-edges-empty',
        category: '拓扑完整性',
        name: '通信连接检查',
        status: 'error',
        message: '没有建立任何设备间的通信连接',
        suggestion: '请使用端口连线功能建立设备间的通信链路',
      });
    } else {
      items.push({
        id: 'topology-edges-ok',
        category: '拓扑完整性',
        name: '通信连接检查',
        status: 'success',
        message: `共建立 ${edges.length} 条通信链路`,
      });
    }

    // 1.3 检查孤立节点（有节点但没有任何连接）
    if (nodes.length > 1 && edges.length > 0) {
      const connectedNodeIds = new Set<string>();
      edges.forEach((edge: any) => {
        const sourceId = edge.getSourceCellId?.();
        const targetId = edge.getTargetCellId?.();
        if (sourceId) connectedNodeIds.add(sourceId);
        if (targetId) connectedNodeIds.add(targetId);
      });

      const isolatedNodes = nodes.filter((node: any) => !connectedNodeIds.has(node.id));

      if (isolatedNodes.length > 0) {
        const nodeNames = isolatedNodes
          .map((node: any) => {
            const data = node.getData?.() || {};
            return data.name || data.label || node.id;
          })
          .join('、');

        items.push({
          id: 'topology-isolated-nodes',
          category: '拓扑完整性',
          name: '孤立节点检查',
          status: 'warning',
          message: `发现 ${isolatedNodes.length} 个孤立设备：${nodeNames}`,
          suggestion: '孤立设备不参与通信仿真，建议建立连接或移除',
          details: { isolatedNodes: isolatedNodes.map((n: any) => n.id) },
        });
      }
    }

    return items;
  }

  /**
   * 2. 端口配置完整性检查
   */
  function checkPortConfiguration(nodes: any[]): CheckItem[] {
    const items: CheckItem[] = [];
    const portIssues: any[] = [];

    // 优先从 params 取值，不存在时回退到 messageConfig.header，并尝试别名
    const getParamValue = (port: any, key: string) => {
      const params = port?.params || {};
      const header = port?.messageConfig?.header || {};
      const lowerKey = key ? key.charAt(0).toLowerCase() + key.slice(1) : '';
      const aliasMap: Record<string, string[]> = {
        baudRate: ['speed'],
        ipAddress: ['ip'],
        protocol: ['proto'],
      };
      const aliases = aliasMap[key] || [];
      const aliasParamVal = aliases
        .map((a) => params[a])
        .find((v) => v !== undefined && v !== null && v !== '');
      const aliasHeaderVal = aliases
        .map((a) => header[a])
        .find((v) => v !== undefined && v !== null && v !== '');
      return (
        params[key] ??
        params[lowerKey] ??
        aliasParamVal ??
        header[key] ??
        header[lowerKey] ??
        aliasHeaderVal ??
        null
      );
    };

    nodes.forEach((node: any) => {
      const data = node.getData?.() || {};
      const nodeName = data.name || data.label || node.id;
      const ports = data.ports || [];

      if (ports.length === 0) {
        portIssues.push({
          nodeId: node.id,
          nodeName,
          issue: 'no-ports',
          message: `设备 "${nodeName}" 没有配置任何端口`,
        });
        return;
      }

      ports.forEach((port: any) => {
        const portName = port.interfaceName || port.name || port.id;
        const interfaceType = (port.interfaceType || port.busType || '').toUpperCase();

        // 检查协议类型
        if (!interfaceType) {
          portIssues.push({
            nodeId: node.id,
            nodeName,
            portId: port.id,
            portName,
            issue: 'no-protocol',
            message: `端口 "${portName}" 未配置协议类型`,
          });
          return;
        }

        // 检查必需参数
        const requiredParams = PROTOCOL_REQUIRED_PARAMS[interfaceType];
        if (requiredParams) {
          const missingParams = requiredParams.filter((param) => {
            const value = getParamValue(port, param);
            return value === undefined || value === null || value === '';
          });

          if (missingParams.length > 0) {
            const missingParamNames = missingParams.map((p) => PARAM_NAMES[p] || p).join('、');
            portIssues.push({
              nodeId: node.id,
              nodeName,
              portId: port.id,
              portName,
              interfaceType,
              issue: 'missing-params',
              message: `"${nodeName}" 的端口 "${portName}" 缺少参数：${missingParamNames}`,
              missingParams,
            });
          }
        }

        // LAN协议特殊检查：IP地址格式
        const ipAddress = getParamValue(port, 'ipAddress');
        if (interfaceType === 'LAN' && ipAddress) {
          const ipPattern =
            /^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
          if (!ipPattern.test(ipAddress)) {
            portIssues.push({
              nodeId: node.id,
              nodeName,
              portId: port.id,
              portName,
              issue: 'invalid-ip',
              message: `端口 "${portName}" 的IP地址格式无效：${ipAddress}`,
            });
          }
        }
      });
    });

    // 汇总端口配置检查结果
    if (portIssues.length === 0) {
      items.push({
        id: 'port-config-ok',
        category: '端口配置',
        name: '端口参数完整性',
        status: 'success',
        message: '所有端口配置参数完整',
      });
    } else {
      // 按严重程度分类
      const errorIssues = portIssues.filter(
        (i) => i.issue === 'no-ports' || i.issue === 'no-protocol'
      );
      const warningIssues = portIssues.filter(
        (i) => i.issue === 'missing-params' || i.issue === 'invalid-ip'
      );

      if (errorIssues.length > 0) {
        items.push({
          id: 'port-config-error',
          category: '端口配置',
          name: '端口基础配置',
          status: 'error',
          message: `${errorIssues.length} 个端口存在严重配置问题`,
          suggestion: '请为所有端口配置协议类型',
          details: { issues: errorIssues },
        });
      }

      if (warningIssues.length > 0) {
        items.push({
          id: 'port-config-warning',
          category: '端口配置',
          name: '端口参数配置',
          status: 'warning',
          message: `${warningIssues.length} 个端口参数配置不完整`,
          suggestion: '双击设备节点完善端口参数配置',
          details: { issues: warningIssues },
        });
      }
    }

    return items;
  }

  /**
   * 3. 连接有效性检查
   */
  function checkConnectionValidity(nodes: any[], edges: any[]): CheckItem[] {
    const items: CheckItem[] = [];
    const connectionIssues: any[] = [];

    // 构建节点端口映射
    const nodePortMap = new Map();
    nodes.forEach((node: any) => {
      const data = node.getData?.() || {};
      const ports = data.ports || [];
      nodePortMap.set(node.id, {
        name: data.name || data.label || node.id,
        ports: new Map(ports.map((p: any) => [p.id, p])),
      });
    });

    edges.forEach((edge: any) => {
      const sourceNodeId = edge.getSourceCellId?.();
      const targetNodeId = edge.getTargetCellId?.();
      const sourcePortId = edge.getSourcePortId?.();
      const targetPortId = edge.getTargetPortId?.();

      const sourceNode = nodePortMap.get(sourceNodeId);
      const targetNode = nodePortMap.get(targetNodeId);

      // 检查节点存在性
      if (!sourceNode || !targetNode) {
        connectionIssues.push({
          edgeId: edge.id,
          issue: 'invalid-node',
          message: '连接引用了不存在的设备节点',
        });
        return;
      }

      // 检查端口存在性
      const sourcePort = sourceNode.ports.get(sourcePortId);
      const targetPort = targetNode.ports.get(targetPortId);

      if (!sourcePort) {
        connectionIssues.push({
          edgeId: edge.id,
          issue: 'invalid-source-port',
          message: `设备 "${sourceNode.name}" 上不存在源端口`,
        });
      }

      if (!targetPort) {
        connectionIssues.push({
          edgeId: edge.id,
          issue: 'invalid-target-port',
          message: `设备 "${targetNode.name}" 上不存在目标端口`,
        });
      }

      // 检查协议类型匹配
      if (sourcePort && targetPort) {
        const sourceType = (sourcePort.interfaceType || sourcePort.busType || '').toUpperCase();
        const targetType = (targetPort.interfaceType || targetPort.busType || '').toUpperCase();

        if (sourceType && targetType && sourceType !== targetType) {
          const sourceTypeName = PROTOCOL_NAMES[sourceType] || sourceType;
          const targetTypeName = PROTOCOL_NAMES[targetType] || targetType;
          connectionIssues.push({
            edgeId: edge.id,
            issue: 'protocol-mismatch',
            message: `协议类型不匹配：${sourceNode.name}(${sourceTypeName}) ↔ ${targetNode.name}(${targetTypeName})`,
            sourceType,
            targetType,
          });
        }
      }
    });

    // 汇总连接有效性检查结果
    if (connectionIssues.length === 0 && edges.length > 0) {
      items.push({
        id: 'connection-validity-ok',
        category: '连接有效性',
        name: '连接配置检查',
        status: 'success',
        message: '所有通信连接配置有效',
      });
    } else if (connectionIssues.length > 0) {
      const protocolMismatch = connectionIssues.filter((i) => i.issue === 'protocol-mismatch');
      const invalidRefs = connectionIssues.filter((i) => i.issue !== 'protocol-mismatch');

      if (invalidRefs.length > 0) {
        items.push({
          id: 'connection-invalid-refs',
          category: '连接有效性',
          name: '连接引用检查',
          status: 'error',
          message: `${invalidRefs.length} 条连接引用无效`,
          suggestion: '请检查连接是否正确关联到设备端口',
          details: { issues: invalidRefs },
        });
      }

      if (protocolMismatch.length > 0) {
        items.push({
          id: 'connection-protocol-mismatch',
          category: '连接有效性',
          name: '协议类型匹配',
          status: 'warning',
          message: `${protocolMismatch.length} 条连接的协议类型不匹配`,
          suggestion: '建议连接相同协议类型的端口以确保通信兼容性',
          details: { issues: protocolMismatch },
        });
      }
    }

    return items;
  }

  /**
   * 4. 通信参数一致性检查
   */
  function checkParameterConsistency(nodes: any[], edges: any[]): CheckItem[] {
    const items: CheckItem[] = [];
    const parameterIssues: any[] = [];

    // 构建节点端口映射
    const nodePortMap = new Map();
    nodes.forEach((node: any) => {
      const data = node.getData?.() || {};
      const ports = data.ports || [];
      nodePortMap.set(node.id, {
        name: data.name || data.label || node.id,
        ports: new Map(ports.map((p: any) => [p.id, p])),
      });
    });

    edges.forEach((edge: any) => {
      const sourceNodeId = edge.getSourceCellId?.();
      const targetNodeId = edge.getTargetCellId?.();
      const sourcePortId = edge.getSourcePortId?.();
      const targetPortId = edge.getTargetPortId?.();

      const sourceNode = nodePortMap.get(sourceNodeId);
      const targetNode = nodePortMap.get(targetNodeId);

      if (!sourceNode || !targetNode) return;

      const sourcePort = sourceNode.ports.get(sourcePortId);
      const targetPort = targetNode.ports.get(targetPortId);

      if (!sourcePort || !targetPort) return;

      const sourceParams = sourcePort.params || {};
      const targetParams = targetPort.params || {};
      const sourceType = (sourcePort.interfaceType || sourcePort.busType || '').toUpperCase();
      const targetType = (targetPort.interfaceType || targetPort.busType || '').toUpperCase();

      // 只检查相同协议类型的参数一致性
      if (sourceType !== targetType) return;

      // RS422/RS485/CAN: 检查波特率一致性
      if (['RS422', 'RS485', 'CAN'].includes(sourceType)) {
        const sourceBaudRate = sourceParams.baudRate;
        const targetBaudRate = targetParams.baudRate;

        if (sourceBaudRate && targetBaudRate && sourceBaudRate !== targetBaudRate) {
          parameterIssues.push({
            edgeId: edge.id,
            issue: 'baudrate-mismatch',
            message: `波特率不一致：${sourceNode.name}(${sourceBaudRate}) ↔ ${targetNode.name}(${targetBaudRate})`,
            sourceValue: sourceBaudRate,
            targetValue: targetBaudRate,
          });
        }
      }

      // RS422/RS485: 检查数据位、停止位、校验方式一致性
      if (['RS422', 'RS485'].includes(sourceType)) {
        if (
          sourceParams.dataBits &&
          targetParams.dataBits &&
          sourceParams.dataBits !== targetParams.dataBits
        ) {
          parameterIssues.push({
            edgeId: edge.id,
            issue: 'databits-mismatch',
            message: `数据位不一致：${sourceNode.name}(${sourceParams.dataBits}) ↔ ${targetNode.name}(${targetParams.dataBits})`,
          });
        }

        if (
          sourceParams.parity &&
          targetParams.parity &&
          sourceParams.parity !== targetParams.parity
        ) {
          parameterIssues.push({
            edgeId: edge.id,
            issue: 'parity-mismatch',
            message: `校验方式不一致：${sourceNode.name}(${sourceParams.parity}) ↔ ${targetNode.name}(${targetParams.parity})`,
          });
        }
      }
    });

    // 汇总参数一致性检查结果
    if (parameterIssues.length === 0 && edges.length > 0) {
      items.push({
        id: 'param-consistency-ok',
        category: '参数一致性',
        name: '通信参数一致性',
        status: 'success',
        message: '所有连接的通信参数配置一致',
      });
    } else if (parameterIssues.length > 0) {
      items.push({
        id: 'param-consistency-warning',
        category: '参数一致性',
        name: '通信参数一致性',
        status: 'warning',
        message: `${parameterIssues.length} 条连接存在参数不一致`,
        suggestion: '通信双方参数不一致可能导致仿真结果不准确',
        details: { issues: parameterIssues },
      });
    }

    return items;
  }

  /**
   * 5. 配置冲突检测
   */
  function checkConfigurationConflicts(nodes: any[], edges: any[]): CheckItem[] {
    const items: CheckItem[] = [];

    // 回环检测（自连接）
    const loopbackEdges = edges.filter((edge: any) => {
      const sourceId = edge.getSourceCellId?.();
      const targetId = edge.getTargetCellId?.();
      return sourceId && targetId && sourceId === targetId;
    });

    if (loopbackEdges.length > 0) {
      items.push({
        id: 'conflict-loopback',
        category: '配置冲突',
        name: '回环连接检测',
        status: 'warning',
        message: `检测到 ${loopbackEdges.length} 个回环连接（设备自连接）`,
        suggestion: '回环连接通常用于自测试场景，请确认是否符合预期',
        details: { edgeIds: loopbackEdges.map((e: any) => e.id) },
      });
    } else {
      items.push({
        id: 'conflict-loopback-ok',
        category: '配置冲突',
        name: '回环连接检测',
        status: 'success',
        message: '未检测到回环连接',
      });
    }

    return items;
  }

  /**
   * 获取检查结果的汇总文本
   */
  function getSummaryText(report: HealthReport): string {
    if (report.healthy) {
      return '✅ 健康检查通过，所有配置正常';
    } else if (report.canSimulate) {
      return `⚠️ 检查完成，有 ${report.warningChecks} 项警告，可以执行仿真`;
    } else {
      return `❌ 检查未通过，有 ${report.errorChecks} 项错误需要修复`;
    }
  }

  /**
   * 按分类分组检查项
   */
  function groupItemsByCategory(items: CheckItem[]): Record<string, CheckItem[]> {
    const groups: Record<string, CheckItem[]> = {};
    items.forEach((item) => {
      if (!groups[item.category]) {
        groups[item.category] = [];
      }
      groups[item.category].push(item);
    });
    return groups;
  }

  return {
    runHealthCheck,
    getSummaryText,
    groupItemsByCategory,
    PROTOCOL_REQUIRED_PARAMS,
    PROTOCOL_NAMES,
    PARAM_NAMES,
  };
}

/**
 * 仿真API Composable
 * 封装所有仿真相关的HTTP请求，统一错误处理和loading状态管理
 */
import { ref, type Ref } from 'vue';
import {
  createSimulationSession,
  startSimulationSession,
  stopSimulationSession,
  getSimulationStatus,
  getSimulationMessages,
  getSimulationBandwidth,
  getSimulationAlarms,
  exportSimulationData,
} from '@/api/simulation/simulation';

/**
 * 仿真会话创建参数
 */
export interface SimulationSessionParams {
  projectId: number | string;
  versionId: number | string;
}

/**
 * 仿真会话数据
 */
export interface SimulationSessionData {
  sessionId: string;
  projectId: number;
  versionId: number;
  status: string;
  createdAt: string;
}

/**
 * 仿真状态数据
 */
export interface SimulationStatusData {
  sessionId: string;
  status: 'idle' | 'running' | 'paused' | 'stopped' | 'error';
  startTime?: string;
  endTime?: string;
  messageCount: number;
  alarmCount: number;
  errorCount: number;
}

/**
 * 仿真报文数据
 */
export interface SimulationMessage {
  id: string;
  timestamp: number;
  sourceNode: string;
  targetNode: string;
  protocolType: string;
  messageType: string;
  data: any;
  size: number;
}

/**
 * 仿真带宽数据
 */
export interface SimulationBandwidth {
  timestamp: number;
  portId: string;
  bandwidth: number;
  utilization: number;
}

/**
 * 仿真告警数据
 */
export interface SimulationAlarm {
  alarmId: string;
  timestamp: number;
  severity: 'info' | 'warning' | 'error' | 'critical';
  message: string;
  nodeId?: string;
  edgeId?: string;
  details?: any;
}

/**
 * 数据导出参数
 */
export interface ExportDataParams {
  exportFormat: 'json' | 'csv' | 'excel';
  dataType: 'messages' | 'bandwidth' | 'alarms' | 'all';
}

/**
 * 数据导出结果
 */
export interface ExportDataResult {
  downloadUrl: string;
  fileName: string;
  fileSize: number;
}

/**
 * 仿真API返回类型
 */
export interface UseSimulationApiReturn {
  loading: Ref<boolean>;
  error: Ref<string | null>;
  createSession: (
    projectId: number | string,
    versionId: number | string
  ) => Promise<SimulationSessionData>;
  startSession: (sessionId: string) => Promise<any>;
  stopSession: (sessionId: string) => Promise<any>;
  fetchStatus: (sessionId: string) => Promise<SimulationStatusData | null>;
  fetchMessages: (sessionId: string, limit?: number) => Promise<SimulationMessage[]>;
  fetchBandwidth: (sessionId: string, portId?: string | null) => Promise<SimulationBandwidth[]>;
  fetchAlarms: (sessionId: string) => Promise<SimulationAlarm[]>;
  exportData: (
    sessionId: string,
    exportFormat?: string,
    dataType?: string
  ) => Promise<ExportDataResult>;
}

export function useSimulationApi(): UseSimulationApiReturn {
  const loading = ref<boolean>(false);
  const error = ref<string | null>(null);

  /**
   * 创建仿真会话
   */
  const createSession = async (
    projectId: number | string,
    versionId: number | string
  ): Promise<SimulationSessionData> => {
    loading.value = true;
    error.value = null;

    try {
      const response = await createSimulationSession({
        projectId,
        versionId,
      });
      return response;
    } catch (err: any) {
      error.value = err.message;
      throw err;
    } finally {
      loading.value = false;
    }
  };

  /**
   * 启动仿真
   */
  const startSession = async (sessionId: string): Promise<any> => {
    loading.value = true;
    error.value = null;

    try {
      const response = await startSimulationSession(sessionId);
      return response;
    } catch (err: any) {
      error.value = err.message;
      throw err;
    } finally {
      loading.value = false;
    }
  };

  /**
   * 停止仿真
   */
  const stopSession = async (sessionId: string): Promise<any> => {
    loading.value = true;
    error.value = null;

    try {
      const response = await stopSimulationSession(sessionId);
      return response;
    } catch (err: any) {
      error.value = err.message;
      throw err;
    } finally {
      loading.value = false;
    }
  };

  /**
   * 获取仿真状态
   */
  const fetchStatus = async (sessionId: string): Promise<SimulationStatusData | null> => {
    try {
      const response = await getSimulationStatus(sessionId);
      return response;
    } catch (err) {
      console.error('获取仿真状态失败:', err);
      return null;
    }
  };

  /**
   * 获取报文数据
   */
  const fetchMessages = async (
    sessionId: string,
    limit: number = 100
  ): Promise<SimulationMessage[]> => {
    try {
      const response = await getSimulationMessages(sessionId, limit);
      return response || [];
    } catch (err) {
      console.error('获取报文数据失败:', err);
      return [];
    }
  };

  /**
   * 获取带宽数据
   */
  const fetchBandwidth = async (
    sessionId: string,
    portId: string | null = null
  ): Promise<SimulationBandwidth[]> => {
    try {
      const response = await getSimulationBandwidth(sessionId, portId);
      return response || [];
    } catch (err) {
      console.error('获取带宽数据失败:', err);
      return [];
    }
  };

  /**
   * 获取告警数据
   */
  const fetchAlarms = async (sessionId: string): Promise<SimulationAlarm[]> => {
    try {
      const response = await getSimulationAlarms(sessionId);
      return response || [];
    } catch (err) {
      console.error('获取告警数据失败:', err);
      return [];
    }
  };

  /**
   * 导出数据
   */
  const exportData = async (
    sessionId: string,
    exportFormat: string = 'json',
    dataType: string = 'messages'
  ): Promise<ExportDataResult> => {
    loading.value = true;
    error.value = null;

    try {
      const response = await exportSimulationData(sessionId, {
        exportFormat,
        dataType,
      });
      return response;
    } catch (err: any) {
      error.value = err.message;
      throw err;
    } finally {
      loading.value = false;
    }
  };

  return {
    loading,
    error,
    createSession,
    startSession,
    stopSession,
    fetchStatus,
    fetchMessages,
    fetchBandwidth,
    fetchAlarms,
    exportData,
  };
}

/**
 * 仿真控制 Composable
 *
 * 管理仿真会话的生命周期和状态
 */
import {
  ref,
  reactive,
  computed,
  watch,
  onUnmounted,
  isRef,
  type Ref,
  type ComputedRef,
} from 'vue';
import {
  createSimulationSession,
  startSimulationSession,
  pauseSimulationSession,
  resumeSimulationSession,
  stopSimulationSession,
  stepSimulationSession,
  setSimulationSpeed,
} from '@/api/simulation/simulation';

/**
 * 仿真状态枚举
 */
export const SimulationStatus = {
  IDLE: 'idle',
  RUNNING: 'running',
  PAUSED: 'paused',
  STOPPED: 'stopped',
} as const;

export type SimulationStatusType = (typeof SimulationStatus)[keyof typeof SimulationStatus];

/**
 * 仿真速度范围
 */
export const SpeedRange = {
  MIN: 0.5,
  MAX: 4.0,
  DEFAULT: 1.0,
};

interface SimulationState {
  status: SimulationStatusType;
  elapsedTime: number;
  speed: number;
  messageCount: number;
  alarmCount: number;
  startTime: number | null;
}

interface SessionOptions {
  speed?: number;
  [key: string]: any;
}

interface StatusUpdate {
  status?: SimulationStatusType;
  speed?: number;
  elapsedTime?: number;
  messageCount?: number;
  alarmCount?: number;
}

interface StatsUpdate {
  messageCount?: number;
  alarmCount?: number;
  elapsedTime?: number;
}

/**
 * 限制速度值在有效范围内
 * @param {number} speed - 速度值
 * @returns {number} 限制后的速度值
 */
export function clampSpeed(speed: number): number {
  if (typeof speed !== 'number' || isNaN(speed)) {
    return SpeedRange.DEFAULT;
  }
  return Math.max(SpeedRange.MIN, Math.min(SpeedRange.MAX, speed));
}

/**
 * 验证状态转换是否有效
 * @param {string} currentStatus - 当前状态
 * @param {string} targetStatus - 目标状态
 * @returns {boolean} 是否可以转换
 */
export function isValidTransition(
  currentStatus: SimulationStatusType,
  targetStatus: SimulationStatusType
): boolean {
  const validTransitions: Record<SimulationStatusType, SimulationStatusType[]> = {
    [SimulationStatus.IDLE]: [SimulationStatus.RUNNING],
    [SimulationStatus.RUNNING]: [SimulationStatus.PAUSED, SimulationStatus.STOPPED],
    [SimulationStatus.PAUSED]: [SimulationStatus.RUNNING, SimulationStatus.STOPPED],
    [SimulationStatus.STOPPED]: [SimulationStatus.RUNNING],
  };

  const allowed = validTransitions[currentStatus] || [];
  return allowed.includes(targetStatus);
}

/**
 * 仿真控制 Composable
 * @param {Ref<number>} projectId - 项目ID
 * @param {Ref<number|undefined>} versionId - 版本ID
 * @returns {Object} 仿真控制方法和状态
 */
export function useSimulationControl(
  projectId: Ref<number> | number,
  versionId?: Ref<number | undefined> | number
) {
  const projectIdRef = isRef(projectId) ? projectId : ref(projectId);
  const versionIdRef = isRef(versionId) ? versionId : ref(versionId);

  // 会话ID
  const sessionId: Ref<string | null> = ref(null);

  // 仿真状态
  const simulationState = reactive<SimulationState>({
    status: SimulationStatus.IDLE,
    elapsedTime: 0,
    speed: SpeedRange.DEFAULT,
    messageCount: 0,
    alarmCount: 0,
    startTime: null,
  });

  // 计时器
  let timerInterval: number | null = null;

  // 计算属性
  const isRunning: ComputedRef<boolean> = computed(
    () => simulationState.status === SimulationStatus.RUNNING
  );
  const isPaused: ComputedRef<boolean> = computed(
    () => simulationState.status === SimulationStatus.PAUSED
  );
  const isStopped: ComputedRef<boolean> = computed(
    () => simulationState.status === SimulationStatus.STOPPED
  );
  const isIdle: ComputedRef<boolean> = computed(
    () => simulationState.status === SimulationStatus.IDLE
  );
  const currentTime = computed({
    get: () => simulationState.elapsedTime,
    set: (value: number) => {
      simulationState.elapsedTime = value;
    },
  });
  const speed = computed({
    get: () => simulationState.speed,
    set: (value: number) => {
      simulationState.speed = value;
    },
  });
  const formattedTime = computed(() => {
    const totalMilliseconds = Math.max(0, simulationState.elapsedTime) * 1000;
    const hours = Math.floor(totalMilliseconds / 3600000);
    const minutes = Math.floor((totalMilliseconds % 3600000) / 60000);
    const seconds = Math.floor((totalMilliseconds % 60000) / 1000);
    const milliseconds = Math.floor(totalMilliseconds % 1000);
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(
      seconds
    ).padStart(2, '0')}.${String(milliseconds).padStart(3, '0')}`;
  });

  // 最近一次前端主动设置速度的时间戳（用于防止状态回写冲掉本地设置）
  const lastSpeedSetAt: Ref<number> = ref(0);

  /**
   * 启动计时器
   */
  function startTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
    }

    const startTimestamp = Date.now() - simulationState.elapsedTime * 1000;

    timerInterval = window.setInterval(() => {
      if (simulationState.status === SimulationStatus.RUNNING) {
        const elapsed = (Date.now() - startTimestamp) / 1000;
        simulationState.elapsedTime = elapsed * simulationState.speed;
      }
    }, 100); // 每100ms更新一次
  }

  /**
   * 停止计时器
   */
  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  /**
   * 创建仿真会话
   */
  async function createSession(options: SessionOptions = {}): Promise<string> {
    const response = await createSimulationSession({
      projectId: projectIdRef.value,
      versionId: versionIdRef?.value,
      ...options,
    });

    if (response?.sessionId) {
      sessionId.value = response.sessionId;
      return response.sessionId;
    }

    throw new Error('创建仿真会话失败');
  }

  /**
   * 启动仿真
   */
  async function start(options: SessionOptions = {}) {
    if (!isValidTransition(simulationState.status, SimulationStatus.RUNNING)) {
      throw new Error('当前状态不允许启动仿真');
    }

    // 如果没有会话，先创建
    if (!sessionId.value) {
      await createSession(options);
    }

    // 启动仿真
    await startSimulationSession(sessionId.value!, {
      speed: simulationState.speed,
      ...options,
    });

    // 更新状态
    simulationState.status = SimulationStatus.RUNNING;
    simulationState.startTime = Date.now();

    // 启动计时器
    startTimer();
  }

  /**
   * 暂停仿真
   */
  async function pause() {
    if (!isValidTransition(simulationState.status, SimulationStatus.PAUSED)) {
      throw new Error('当前状态不允许暂停仿真');
    }

    if (!sessionId.value) {
      throw new Error('仿真会话不存在');
    }

    await pauseSimulationSession(sessionId.value);

    simulationState.status = SimulationStatus.PAUSED;
    stopTimer();
  }

  /**
   * 继续仿真
   */
  async function resume() {
    if (!isValidTransition(simulationState.status, SimulationStatus.RUNNING)) {
      throw new Error('当前状态不允许继续仿真');
    }

    if (!sessionId.value) {
      throw new Error('仿真会话不存在');
    }

    await resumeSimulationSession(sessionId.value);

    simulationState.status = SimulationStatus.RUNNING;
    startTimer();
  }

  /**
   * 停止仿真
   */
  async function stop() {
    if (!isValidTransition(simulationState.status, SimulationStatus.STOPPED)) {
      // 如果是 idle 状态，直接返回
      if (simulationState.status === SimulationStatus.IDLE) {
        return;
      }
      throw new Error('当前状态不允许停止仿真');
    }

    if (sessionId.value) {
      await stopSimulationSession(sessionId.value);
    }

    simulationState.status = SimulationStatus.STOPPED;
    stopTimer();
  }

  /**
   * 单步执行
   */
  async function step() {
    if (simulationState.status !== SimulationStatus.PAUSED) {
      throw new Error('只有在暂停状态下才能单步执行');
    }

    if (!sessionId.value) {
      throw new Error('仿真会话不存在');
    }

    await stepSimulationSession(sessionId.value);

    // 更新时间（假设每步100ms）
    simulationState.elapsedTime += 0.1;
  }

  /**
   * 设置仿真速度
   */
  async function setSpeed(speed: number) {
    const clampedSpeed = clampSpeed(speed);
    const prevSpeed = simulationState.speed;
    simulationState.speed = clampedSpeed;
    lastSpeedSetAt.value = Date.now();

    // 后端对 <1x 可能异常，传输时最低保持 1x，前端仍按 clampedSpeed 展示/动画
    const backendSpeed = Math.max(1, clampedSpeed);

    // 仅在有有效会话且处于运行/暂停时下发后端
    if (sessionId.value && (isRunning.value || isPaused.value)) {
      try {
        await setSimulationSpeed(sessionId.value, backendSpeed);
      } catch (err) {
        // 回滚到上一次速度，避免卡死
        simulationState.speed = prevSpeed;
        throw err;
      }
    }
  }

  function updateTime(time: number) {
    if (time < 0) {
      throw new Error('仿真时间不能为负数');
    }
    simulationState.elapsedTime = time;
  }

  /**
   * 同步后端状态（WS 状态推送）
   */
  function syncStatus(status: StatusUpdate) {
    if (!status || typeof status !== 'object') return;

    if (status.status) {
      simulationState.status = status.status;
    }
    if (status.speed !== undefined) {
      const now = Date.now();
      const incoming = clampSpeed(Number(status.speed));
      // 如果刚刚（1秒内）本地设置过速度，则不被后端回写立即覆盖
      if (now - lastSpeedSetAt.value > 1000) {
        simulationState.speed = incoming;
      }
    }
    if (status.elapsedTime !== undefined) {
      simulationState.elapsedTime = Number(status.elapsedTime) || 0;
    }
    if (status.messageCount !== undefined) {
      simulationState.messageCount = Number(status.messageCount) || 0;
    }
    if (status.alarmCount !== undefined) {
      simulationState.alarmCount = Number(status.alarmCount) || 0;
    }
  }

  /**
   * 重置状态
   */
  function reset() {
    stopTimer();
    sessionId.value = null;
    simulationState.status = SimulationStatus.IDLE;
    simulationState.elapsedTime = 0;
    simulationState.speed = SpeedRange.DEFAULT;
    simulationState.messageCount = 0;
    simulationState.alarmCount = 0;
    simulationState.startTime = null;
  }

  /**
   * 更新统计数据
   */
  function updateStats(stats: StatsUpdate) {
    if (stats.messageCount !== undefined) {
      simulationState.messageCount = stats.messageCount;
    }
    if (stats.alarmCount !== undefined) {
      simulationState.alarmCount = stats.alarmCount;
    }
    if (stats.elapsedTime !== undefined) {
      simulationState.elapsedTime = stats.elapsedTime;
    }
  }

  // 清理
  onUnmounted(() => {
    stopTimer();
  });

  return {
    // 状态
    sessionId,
    simulationState,
    isRunning,
    isPaused,
    isStopped,
    isIdle,
    currentTime,
    speed,
    formattedTime,

    // 方法
    createSession,
    start,
    pause,
    resume,
    stop,
    step,
    setSpeed,
    updateTime,
    syncStatus,
    reset,
    updateStats,
  };
}

export default useSimulationControl;

/**
 * 仿真数据管理 Composable
 *
 * 管理仿真过程中的带宽、报文、告警数据
 */
import { ref, computed, watch, onUnmounted, type Ref, type ComputedRef } from 'vue';
import { useSimulationWebSocket } from './useSimulationWebSocket';

interface Message {
  [key: string]: any;
  timestamp: number;
  sendTimestamp?: number;
  receiveTimestamp?: number;
  payloadHex?: string;
  fieldValues?: Record<string, any>;
  senderNodeId?: string;
  receiverNodeId?: string;
  senderNodeName?: string;
  receiverNodeName?: string;
  protocolType?: string;
  senderPortId?: string;
  receiverPortId?: string;
  fillStrategy?: string;
  sizeBytes?: number;
  isError?: boolean;
}

interface MessageFilter {
  protocolType?: string;
  senderNodeId?: string;
  receiverNodeId?: string;
  keyword?: string;
  startTime?: number;
  endTime?: number;
  errorOnly?: boolean;
  conditions?: FilterCondition[];
  conditionLogic?: 'and' | 'or';
}

interface FilterCondition {
  type?: string;
  operator?: string;
  value?: string;
  key?: string;
  field?: string;
  min?: number;
  max?: number;
}

interface BandwidthData {
  [key: string]: any;
  timestamp: number;
  protocolType?: string;
  nodeId?: string;
  portId?: string;
}

interface AlarmData {
  [key: string]: any;
  alarmId?: string;
  level?: string;
  type?: string;
  timestamp: number;
}

interface AlarmFilter {
  level?: string;
  type?: string;
}

interface FaultEventData {
  [key: string]: any;
}

interface IncrementalData<T> {
  newData: T[];
  newIndex: number;
}

/**
 * 数据清理配置
 */
const DATA_LIMITS = {
  // 为避免前端内存爆炸，保留一个滑动窗口；总数显示继续累加
  MAX_MESSAGES: 50000,
  MAX_BANDWIDTH_POINTS: 600, // 最大带宽数据点（10分钟，每秒1个）
  MAX_ALARMS: 1000, // 最大告警数量
};

/**
 * 计算报文时延（毫秒）
 */
function getLatencyMs(message: Message): number | null {
  const send = message?.sendTimestamp ?? message?.timestamp;
  const recv = message?.receiveTimestamp;
  if (!send || !recv) return null;
  return Math.max(0, (recv - send) * 1000);
}

/**
 * 单条条件匹配
 */
function matchesCondition(message: Message, condition: FilterCondition): boolean | null {
  if (!condition) return null;
  const type = condition.type || 'payload';
  const operator = (condition.operator || 'includes').toLowerCase();

  if (type === 'payload') {
    const payload = String(message?.payloadHex || '').toLowerCase();
    const value = String(condition.value || '').toLowerCase();
    if (!value) return null;
    if (operator === 'startswith') return payload.startsWith(value);
    if (operator === 'equals') return payload === value;
    return payload.includes(value);
  }

  if (type === 'field') {
    const fieldValues = message?.fieldValues || {};
    const keyFilter = String(condition.key || '').toLowerCase();
    const valueFilter = String(condition.value || '').toLowerCase();
    if (!keyFilter && !valueFilter) return null;
    return Object.entries(fieldValues).some(([k, v]) => {
      const kText = String(k || '').toLowerCase();
      const vText = String(v ?? '').toLowerCase();
      if (keyFilter && !kText.includes(keyFilter)) return false;
      if (valueFilter)
        return vText.includes(valueFilter) || (!keyFilter && kText.includes(valueFilter));
      return true;
    });
  }

  if (type === 'node') {
    const field = condition.field || 'senderNodeId';
    const target = String((message as any)?.[field] || '').toLowerCase();
    const value = String(condition.value || '').toLowerCase();
    if (!value) return null;
    return target.includes(value);
  }

  if (type === 'protocol') {
    const protocol = String(message?.protocolType || '').toLowerCase();
    const value = String(condition.value || '').toLowerCase();
    if (!value) return null;
    if (operator === 'equals') return protocol === value;
    return protocol.includes(value);
  }

  if (type === 'size') {
    const size = Number(message?.sizeBytes || 0);
    const min =
      condition.min !== undefined && condition.min !== null ? Number(condition.min) : null;
    const max =
      condition.max !== undefined && condition.max !== null ? Number(condition.max) : null;
    if (min === null && max === null) return null;
    if (Number.isFinite(min) && size < min!) return false;
    if (Number.isFinite(max) && size > max!) return false;
    return true;
  }

  if (type === 'latency') {
    const latency = getLatencyMs(message);
    if (latency === null) return false;
    const min =
      condition.min !== undefined && condition.min !== null ? Number(condition.min) : null;
    const max =
      condition.max !== undefined && condition.max !== null ? Number(condition.max) : null;
    if (min === null && max === null) return null;
    if (Number.isFinite(min) && latency < min!) return false;
    if (Number.isFinite(max) && latency > max!) return false;
    return true;
  }

  return null;
}

/**
 * 多条件匹配（支持 AND / OR）
 */
function matchesConditions(message: Message, filter: MessageFilter): boolean {
  const conditions = Array.isArray(filter?.conditions) ? filter.conditions : [];
  if (!conditions.length) return true;

  const normalized = conditions
    .map((c) => ({
      ...c,
      type: c?.type || 'payload',
    }))
    .filter((c) => {
      if (c.type === 'size' || c.type === 'latency') {
        return c.min !== undefined || c.max !== undefined;
      }
      return Boolean(String(c.value || c.key || '').trim());
    });

  if (!normalized.length) return true;

  const logic = (filter?.conditionLogic || 'and').toLowerCase() === 'or' ? 'or' : 'and';
  const results = normalized
    .map((cond) => matchesCondition(message, cond))
    .filter((res) => res !== null);

  if (!results.length) return true;
  return logic === 'or' ? results.some(Boolean) : results.every(Boolean);
}

/**
 * 报文过滤器
 * @param {Array} messages - 报文列表
 * @param {Object} filter - 过滤条件
 * @returns {Array} 过滤后的报文列表
 */
export function filterMessages(messages: Message[], filter: MessageFilter): Message[] {
  if (!messages || !Array.isArray(messages)) {
    return [];
  }

  if (!filter || Object.keys(filter).length === 0) {
    return messages;
  }

  return messages.filter((msg) => {
    // 协议类型过滤
    if (filter.protocolType && msg.protocolType !== filter.protocolType) {
      return false;
    }

    // 源节点过滤
    if (filter.senderNodeId && msg.senderNodeId !== filter.senderNodeId) {
      return false;
    }

    // 目标节点过滤
    if (filter.receiverNodeId && msg.receiverNodeId !== filter.receiverNodeId) {
      return false;
    }

    // 关键字过滤（搜索报文内容）
    if (filter.keyword) {
      const keyword = filter.keyword.toLowerCase();
      const searchFields = [
        msg.senderNodeName,
        msg.receiverNodeName,
        msg.protocolType,
        msg.payloadHex,
        msg.senderPortId,
        msg.receiverPortId,
        msg.fillStrategy,
        ...(msg.fieldValues ? Object.values(msg.fieldValues) : []),
      ]
        .filter(Boolean)
        .map((s) => String(s).toLowerCase());

      if (!searchFields.some((field) => field.includes(keyword))) {
        return false;
      }
    }

    // 时间范围过滤
    if (filter.startTime && msg.timestamp < filter.startTime) {
      return false;
    }
    if (filter.endTime && msg.timestamp > filter.endTime) {
      return false;
    }

    // 错误报文过滤
    if (filter.errorOnly && !msg.isError) {
      return false;
    }

    // 多条件过滤
    if (!matchesConditions(msg, filter)) {
      return false;
    }

    return true;
  });
}

/**
 * 检查报文是否匹配过滤条件
 * @param {Object} message - 报文
 * @param {Object} filter - 过滤条件
 * @returns {boolean} 是否匹配
 */
export function matchesFilter(message: Message, filter: MessageFilter): boolean {
  return filterMessages([message], filter).length > 0;
}

/**
 * 清理旧数据，保留最新的数据
 * @param {Array} data - 数据数组
 * @param {number} maxLength - 最大长度
 * @returns {Array} 清理后的数据
 */
export function cleanupOldData<T>(data: T[], maxLength: number): T[] {
  // maxLength 无效或无限时不做截断
  if (
    !Array.isArray(data) ||
    !Number.isFinite(maxLength) ||
    maxLength <= 0 ||
    data.length <= maxLength
  ) {
    return data;
  }
  return data.slice(-maxLength);
}

/**
 * 提取增量数据
 * @param {Array} data - 完整数据数组
 * @param {number} lastIndex - 上次推送的索引
 * @returns {Object} { newData: Array, newIndex: number }
 */
export function extractIncrementalData<T>(data: T[], lastIndex: number): IncrementalData<T> {
  if (!Array.isArray(data)) {
    return { newData: [], newIndex: 0 };
  }

  const newData = data.slice(lastIndex);
  return {
    newData,
    newIndex: data.length,
  };
}

/**
 * 仿真数据管理 Composable
 * @param {Ref<string>} sessionId - 会话ID
 * @returns {Object} 数据管理方法和状态
 */
export function useSimulationData(sessionId: Ref<string | null> = ref(null)) {
  // 原始数据
  const bandwidthData: Ref<BandwidthData[]> = ref([]);
  const messageData: Ref<Message[]> = ref([]);
  const alarmData: Ref<AlarmData[]> = ref([]);
  const faultEventData: Ref<FaultEventData[]> = ref([]);
  const statistics: Ref<Record<string, any>> = ref({});

  // 过滤条件
  const messageFilter: Ref<MessageFilter> = ref({});
  const alarmFilter: Ref<AlarmFilter> = ref({});

  // 增量数据追踪
  const lastMessageIndex: Ref<number> = ref(0);
  const lastBandwidthIndex: Ref<number> = ref(0);
  const lastAlarmIndex: Ref<number> = ref(0);
  const lastFaultEventIndex: Ref<number> = ref(0);

  // WebSocket 连接
  const wsManager = useSimulationWebSocket();

  // 计算属性：过滤后的报文
  const filteredMessages: ComputedRef<Message[]> = computed(() => {
    return filterMessages(messageData.value, messageFilter.value);
  });

  // 计算属性：过滤后的告警
  const filteredAlarms: ComputedRef<AlarmData[]> = computed(() => {
    if (!alarmFilter.value || Object.keys(alarmFilter.value).length === 0) {
      return alarmData.value;
    }

    return alarmData.value.filter((alarm) => {
      if (alarmFilter.value.level && alarm.level !== alarmFilter.value.level) {
        return false;
      }
      if (alarmFilter.value.type && alarm.type !== alarmFilter.value.type) {
        return false;
      }
      return true;
    });
  });

  // 计算属性：按协议类型分组的带宽数据
  const bandwidthByProtocol: ComputedRef<Record<string, BandwidthData[]>> = computed(() => {
    const grouped: Record<string, BandwidthData[]> = {};
    bandwidthData.value.forEach((item) => {
      const protocol = item.protocolType || 'unknown';
      if (!grouped[protocol]) {
        grouped[protocol] = [];
      }
      grouped[protocol].push(item);
    });
    return grouped;
  });

  // 计算属性：最新的带宽数据（每个端口）
  const latestBandwidth: ComputedRef<BandwidthData[]> = computed(() => {
    const latest: Record<string, BandwidthData> = {};
    bandwidthData.value.forEach((item) => {
      const key = `${item.nodeId}:${item.portId}`;
      if (!latest[key] || item.timestamp > latest[key].timestamp) {
        latest[key] = item;
      }
    });
    return Object.values(latest);
  });

  /**
   * 更新带宽数据
   */
  function updateBandwidthData(newData: BandwidthData[]) {
    if (!newData || !Array.isArray(newData)) return;

    bandwidthData.value = cleanupOldData(
      [...bandwidthData.value, ...newData],
      DATA_LIMITS.MAX_BANDWIDTH_POINTS
    );
  }

  /**
   * 更新报文数据
   */
  function updateMessageData(newData: Message[]) {
    if (!newData || !Array.isArray(newData)) return;

    messageData.value = cleanupOldData(
      [...messageData.value, ...newData],
      DATA_LIMITS.MAX_MESSAGES
    );
  }

  /**
   * 更新告警数据
   */
  function updateAlarmData(newData: AlarmData[]) {
    if (!newData || !Array.isArray(newData)) return;

    alarmData.value = cleanupOldData([...alarmData.value, ...newData], DATA_LIMITS.MAX_ALARMS);
  }

  /**
   * 设置报文过滤条件
   */
  function setMessageFilter(filter: MessageFilter) {
    messageFilter.value = filter || {};
    // 过滤条件变化后清空累计数量，等待新数据重新累计
    messageData.value = [];
    lastMessageIndex.value = 0;
    wsManager.messagesData.value = [];
  }

  /**
   * 设置告警过滤条件
   */
  function setAlarmFilter(filter: AlarmFilter) {
    alarmFilter.value = filter || {};
  }

  /**
   * 清空所有数据
   */
  function clearData() {
    bandwidthData.value = [];
    messageData.value = [];
    alarmData.value = [];
    faultEventData.value = [];
    statistics.value = {};
    lastMessageIndex.value = 0;
    lastBandwidthIndex.value = 0;
    lastAlarmIndex.value = 0;
    lastFaultEventIndex.value = 0;
  }

  /**
   * 获取增量报文数据
   */
  function getNewMessages(): Message[] {
    const result = extractIncrementalData(messageData.value, lastMessageIndex.value);
    lastMessageIndex.value = result.newIndex;
    return result.newData;
  }

  /**
   * 获取增量带宽数据
   */
  function getNewBandwidth(): BandwidthData[] {
    const result = extractIncrementalData(bandwidthData.value, lastBandwidthIndex.value);
    lastBandwidthIndex.value = result.newIndex;
    return result.newData;
  }

  /**
   * 获取增量告警数据
   */
  function getNewAlarms(): AlarmData[] {
    const result = extractIncrementalData(alarmData.value, lastAlarmIndex.value);
    lastAlarmIndex.value = result.newIndex;
    return result.newData;
  }

  /**
   * 获取增量故障事件
   */
  function getNewFaultEvents(): FaultEventData[] {
    const result = extractIncrementalData(faultEventData.value, lastFaultEventIndex.value);
    lastFaultEventIndex.value = result.newIndex;
    return result.newData;
  }

  function addMessage(message: Partial<Message> & Record<string, any>) {
    const nextMessage = message as Message;
    const latest = messageData.value[messageData.value.length - 1];
    messageData.value.push(nextMessage);
    if (latest && (nextMessage.timestamp || 0) < (latest.timestamp || 0)) {
      messageData.value.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));
    }
    if (messageData.value.length >= 1500) {
      messageData.value.splice(0, messageData.value.length - 1000);
    }
  }

  function addAlarm(alarm: Partial<AlarmData> & Record<string, any>) {
    alarmData.value = cleanupOldData(
      [...alarmData.value, alarm as AlarmData],
      DATA_LIMITS.MAX_ALARMS
    );
  }

  function updateStatistics(nextStatistics: Record<string, any>) {
    statistics.value = { ...(nextStatistics || {}) };
  }

  function getMessagesByProtocol(protocol: string) {
    return messageData.value.filter(
      (message) => (message.protocol || message.protocolType) === protocol
    );
  }

  function getMessagesByTimeRange(startTime: number, endTime: number) {
    return messageData.value.filter(
      (message) => message.timestamp >= startTime && message.timestamp <= endTime
    );
  }

  function getLatestMessages(limit: number) {
    return [...messageData.value]
      .sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0))
      .slice(0, limit);
  }

  function getAlarmsByLevel(level: string) {
    return alarmData.value.filter((alarm) => alarm.level === level);
  }

  function getAlarmsByType(type: string) {
    return alarmData.value.filter((alarm) => alarm.type === type);
  }

  function getAlarmCounts() {
    return alarmData.value.reduce<Record<string, number>>((counts, alarm) => {
      const level = alarm.level || 'unknown';
      counts[level] = (counts[level] || 0) + 1;
      return counts;
    }, {});
  }

  function clearAcknowledgedAlarms() {
    alarmData.value = alarmData.value.filter((alarm) => !alarm.acknowledged);
  }

  function getMessageRate() {
    const total = Number(statistics.value.total_messages || statistics.value.total || 0);
    const duration = Number(statistics.value.duration || 0);
    return duration ? total / duration : 0;
  }

  function getProtocolDistribution() {
    const source = (statistics.value.messages_by_protocol || {}) as Record<string, unknown>;
    const total = Object.values(source).reduce<number>((sum, value) => sum + Number(value || 0), 0);
    if (!total) return {};
    return Object.entries(source).reduce<Record<string, number>>((result, [protocol, count]) => {
      result[protocol] = (Number(count || 0) / total) * 100;
      return result;
    }, {});
  }

  function getAverageLatency() {
    const latencies = messageData.value
      .map((message) => {
        const sent = message.sent_time ?? message.sendTimestamp;
        const received = message.received_time ?? message.receiveTimestamp;
        return sent !== undefined && received !== undefined
          ? Number(received) - Number(sent)
          : null;
      })
      .filter((latency): latency is number => latency !== null);

    return latencies.length
      ? latencies.reduce((sum, latency) => sum + latency, 0) / latencies.length
      : 0;
  }

  function detectPattern(protocol: string) {
    const messages = getMessagesByProtocol(protocol).sort(
      (a, b) => (a.timestamp || 0) - (b.timestamp || 0)
    );
    if (messages.length < 3) {
      return { isPeriodic: false, period: 0 };
    }
    const intervals = messages.slice(1).map((message, index) => {
      return (message.timestamp || 0) - (messages[index].timestamp || 0);
    });
    const period = intervals.reduce((sum, interval) => sum + interval, 0) / intervals.length;
    const isPeriodic = intervals.every((interval) => Math.abs(interval - period) <= period * 0.1);
    return { isPeriodic, period };
  }

  function getCommunicationPairs() {
    return messageData.value.reduce<Record<string, number>>((pairs, message) => {
      const source = message.source || message.senderNodeId || message.senderNodeName;
      const target = message.target || message.receiverNodeId || message.receiverNodeName;
      if (!source || !target) return pairs;
      const key = `${source}->${target}`;
      pairs[key] = (pairs[key] || 0) + 1;
      return pairs;
    }, {});
  }

  function exportMessagesCSV() {
    const lines = messageData.value.map((message) => {
      return [
        message.id || '',
        message.timestamp || '',
        message.protocol || message.protocolType || '',
        message.source || message.senderNodeId || '',
        message.target || message.receiverNodeId || '',
      ].join(',');
    });
    return ['id,timestamp,protocol,source,target', ...lines].join('\n');
  }

  function exportAlarmsJSON() {
    return JSON.stringify(alarmData.value);
  }

  function exportSummary() {
    return { ...statistics.value };
  }

  function clearMessages() {
    messageData.value = [];
  }

  function clearAlarms() {
    alarmData.value = [];
  }

  // 监听 WebSocket 数据
  watch(
    () => wsManager.messagesData.value,
    (newData) => {
      if (newData && newData.length > 0) {
        updateMessageData(newData);
      }
    }
  );

  watch(
    () => wsManager.bandwidthData.value,
    (newData) => {
      if (newData && newData.length > 0) {
        updateBandwidthData(newData);
      }
    }
  );

  watch(
    () => wsManager.alarmsData.value,
    (newData) => {
      if (newData && newData.length > 0) {
        updateAlarmData(newData);
      }
    }
  );

  watch(
    () => wsManager.faultEventsData.value,
    (newData) => {
      if (newData && newData.length > 0) {
        faultEventData.value = cleanupOldData([...faultEventData.value, ...newData], 200);
      }
    }
  );

  // 监听会话ID变化，连接/断开 WebSocket
  watch(sessionId, (newSessionId, oldSessionId) => {
    if (oldSessionId) {
      wsManager.disconnect();
    }
    if (newSessionId) {
      wsManager.connect(newSessionId);
    }
  });

  // 清理
  onUnmounted(() => {
    wsManager.disconnect();
  });

  return {
    // 数据
    bandwidthData,
    messageData,
    messages: messageData,
    alarmData,
    alarms: alarmData,
    statistics,
    statusData: wsManager.statusData,
    filteredMessages,
    filteredAlarms,
    bandwidthByProtocol,
    latestBandwidth,
    faultEventData,

    // 过滤条件
    messageFilter,
    alarmFilter,

    // 方法
    updateBandwidthData,
    updateMessageData,
    updateAlarmData,
    setMessageFilter,
    setAlarmFilter,
    clearData,
    clear: clearData,
    addMessage,
    addAlarm,
    updateStatistics,
    getMessagesByProtocol,
    getMessagesByTimeRange,
    getLatestMessages,
    getAlarmsByLevel,
    getAlarmsByType,
    getAlarmCounts,
    clearAcknowledgedAlarms,
    getMessageRate,
    getProtocolDistribution,
    getAverageLatency,
    detectPattern,
    getCommunicationPairs,
    exportMessagesCSV,
    exportAlarmsJSON,
    exportSummary,
    clearMessages,
    clearAlarms,
    getNewMessages,
    getNewBandwidth,
    getNewAlarms,
    getNewFaultEvents,
  };
}

export default useSimulationData;

/**
 * 仿真数据管理 Composable
 * 优化 WebSocket 数据更新性能
 */
import { shallowRef, onUnmounted } from 'vue';

// 数据限制配置
const MAX_BANDWIDTH_POINTS = 120; // 最多保留120个数据点（2分钟，每秒1个）
const MAX_MESSAGES = 50; // 最多保留50条报文
const MAX_ALARMS = 50; // 最多保留50条告警
const BANDWIDTH_TIME_WINDOW = 120; // 120秒时间窗口

interface BandwidthDataItem {
  timestamp: number;
  portId?: string;
  [key: string]: any;
}

interface MessageDataItem {
  messageId: string;
  sendTimestamp?: number;
  timestamp?: number;
  senderNodeId?: string;
  sender?: string;
  senderPortId?: string;
  receiverNodeId?: string;
  receiver?: string;
  receiverPortId?: string;
  protocolType?: string;
  protocol?: string;
  sizeBytes?: number;
  size?: number;
  receiveTimestamp?: number;
  [key: string]: any;
}

interface AlarmDataItem {
  [key: string]: any;
}

export function useSimulationDataManager() {
  // 使用 shallowRef 减少深度监听开销
  const bandwidthData = shallowRef<BandwidthDataItem[]>([]);
  const messageData = shallowRef<MessageDataItem[]>([]);
  const alarmData = shallowRef<AlarmDataItem[]>([]);

  // 用于去重的Set
  const seenMessageIds = new Set<string>();
  const seenBandwidthKeys = new Set<string>();

  /**
   * 更新带宽数据（增量追加，自动去重和清理）
   */
  function updateBandwidthData(newData: BandwidthDataItem[]) {
    if (!newData || newData.length === 0) return;

    const now = Date.now() / 1000;
    const cutoffTime = now - BANDWIDTH_TIME_WINDOW;

    // 过滤重复数据
    const uniqueNew = newData.filter((item) => {
      const key = `${item.timestamp}-${item.portId || 'all'}`;
      if (seenBandwidthKeys.has(key)) return false;
      seenBandwidthKeys.add(key);
      return true;
    });

    if (uniqueNew.length === 0) return;

    // 合并新数据
    const merged = [...bandwidthData.value, ...uniqueNew];

    // 过滤旧数据并限制数量
    const filtered = merged
      .filter((item) => item.timestamp >= cutoffTime)
      .slice(-MAX_BANDWIDTH_POINTS);

    // 清理去重集合中的旧键
    if (seenBandwidthKeys.size > MAX_BANDWIDTH_POINTS * 2) {
      seenBandwidthKeys.clear();
      filtered.forEach((item) => {
        seenBandwidthKeys.add(`${item.timestamp}-${item.portId || 'all'}`);
      });
    }

    bandwidthData.value = filtered;
  }

  /**
   * 更新报文数据（增量追加，自动去重）
   */
  function updateMessageData(newData: MessageDataItem[]) {
    if (!newData || newData.length === 0) return;

    // 过滤重复数据并格式化
    const uniqueNew = newData
      .filter((msg) => {
        if (!msg.messageId || seenMessageIds.has(msg.messageId)) return false;
        seenMessageIds.add(msg.messageId);
        return true;
      })
      .map((msg) => ({
        messageId: msg.messageId,
        sendTimestamp: msg.sendTimestamp || msg.timestamp,
        senderNodeId: msg.senderNodeId || msg.sender,
        senderPortId: msg.senderPortId,
        receiverNodeId: msg.receiverNodeId || msg.receiver,
        receiverPortId: msg.receiverPortId,
        protocolType: msg.protocolType || msg.protocol,
        sizeBytes: msg.sizeBytes || msg.size,
        receiveTimestamp: msg.receiveTimestamp,
      }));

    if (uniqueNew.length === 0) return;

    // 追加并限制数量
    const merged = [...messageData.value, ...uniqueNew].slice(-MAX_MESSAGES);

    // 清理去重集合
    if (seenMessageIds.size > MAX_MESSAGES * 2) {
      seenMessageIds.clear();
      merged.forEach((msg) => seenMessageIds.add(msg.messageId));
    }

    messageData.value = merged;
  }

  /**
   * 更新告警数据
   */
  function updateAlarmData(newData: AlarmDataItem[]) {
    if (!newData || newData.length === 0) return;

    // 追加并限制数量
    alarmData.value = [...alarmData.value, ...newData].slice(-MAX_ALARMS);
  }

  /**
   * 清空所有数据
   */
  function clearAllData() {
    bandwidthData.value = [];
    messageData.value = [];
    alarmData.value = [];
    seenMessageIds.clear();
    seenBandwidthKeys.clear();
  }

  // 组件卸载时清理
  onUnmounted(() => {
    clearAllData();
  });

  return {
    bandwidthData,
    messageData,
    alarmData,
    updateBandwidthData,
    updateMessageData,
    updateAlarmData,
    clearAllData,
  };
}

/**
 * 仿真报告 Composable
 *
 * 管理仿真报告的生成和格式化
 */
import type { Ref } from 'vue';

interface MessageItem {
  messageId?: string;
  [key: string]: any;
}

interface AlarmItem {
  alarmType?: string;
  type?: string;
  severity?: string;
  level?: string;
  [key: string]: any;
}

interface BandwidthItem {
  protocolType?: string;
  protocol_type?: string;
  bandwidthMbps?: number;
  bandwidth_mbps?: number;
  loadPercent?: number;
  load_percent?: number;
  [key: string]: any;
}

interface SimulationState {
  elapsedTime: number;
  startTime: number | string | Date;
  [key: string]: any;
}

interface BandwidthStat {
  protocol: string;
  avgBandwidth: string;
  maxBandwidth: string;
  avgLoad: string;
}

interface AlarmStat {
  type: string;
  level: string;
  count: number;
}

interface SimulationSummary {
  duration: string;
  messageCount: number;
  alarmCount: number;
  bandwidthStats: BandwidthStat[];
  alarmStats: AlarmStat[];
  startTime: string;
}

/**
 * 格式化持续时间
 * @param {number} seconds - 秒数
 * @returns {string} 格式化后的时间字符串
 */
export function formatDuration(seconds: number): string {
  const total = Math.max(0, Math.floor(seconds || 0));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const parts: string[] = [];
  if (h > 0) parts.push(`${h}小时`);
  if (m > 0) parts.push(`${m}分`);
  parts.push(`${s}秒`);
  return parts.join('');
}

/**
 * 格式化日期时间
 * @param {number|string|Date} ts - 时间戳
 * @returns {string} 格式化后的日期时间字符串
 */
export function formatDateTime(ts: number | string | Date): string {
  if (!ts) return '-';
  const date = new Date(ts);
  if (Number.isNaN(date.getTime())) return '-';
  const pad = (n: number) => (n < 10 ? `0${n}` : `${n}`);
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

interface UseSimulationReportOptions {
  messageData: Ref<MessageItem[]>;
  alarmData: Ref<AlarmItem[]>;
  bandwidthData: Ref<BandwidthItem[]>;
  simulationState: SimulationState;
}

/**
 * 仿真报告 Composable
 * @param {Object} options 配置选项
 * @param {Ref} options.messageData - 报文数据
 * @param {Ref} options.alarmData - 告警数据
 * @param {Ref} options.bandwidthData - 带宽数据
 * @param {Object} options.simulationState - 仿真状态
 */
export function useSimulationReport(options: UseSimulationReportOptions) {
  const { messageData, alarmData, bandwidthData, simulationState } = options;

  /**
   * 构建仿真摘要报告
   * @returns {Object} 仿真摘要
   */
  function buildSimulationSummary(): SimulationSummary {
    const messageCount = messageData.value.length;
    const alarmCount = alarmData.value.length;
    const duration = formatDuration(simulationState.elapsedTime);
    const startTime = formatDateTime(simulationState.startTime);

    // 带宽统计
    const bandwidthStatsMap: Record<
      string,
      {
        protocol: string;
        total: number;
        max: number;
        loadTotal: number;
        count: number;
      }
    > = {};

    bandwidthData.value.forEach((item) => {
      const protocol = item.protocolType || item.protocol_type || '未知协议';
      if (!bandwidthStatsMap[protocol]) {
        bandwidthStatsMap[protocol] = {
          protocol,
          total: 0,
          max: 0,
          loadTotal: 0,
          count: 0,
        };
      }
      const stat = bandwidthStatsMap[protocol];
      const bw = Number(item.bandwidthMbps || item.bandwidth_mbps || 0);
      const load = Number(item.loadPercent || item.load_percent || 0);
      stat.total += bw;
      stat.loadTotal += load;
      stat.count += 1;
      stat.max = Math.max(stat.max, bw);
    });

    const bandwidthStats: BandwidthStat[] = Object.values(bandwidthStatsMap).map((item) => ({
      protocol: item.protocol,
      avgBandwidth: `${(item.total / item.count || 0).toFixed(3)} Mbps`,
      maxBandwidth: `${item.max.toFixed(3)} Mbps`,
      avgLoad: `${(item.loadTotal / item.count || 0).toFixed(1)}%`,
    }));

    // 告警统计
    const alarmStatsMap: Record<string, AlarmStat> = {};
    alarmData.value.forEach((alarm) => {
      const type = alarm.alarmType || alarm.type || '未知类型';
      const level = alarm.severity || alarm.level || 'info';
      const key = `${type}-${level}`;
      if (!alarmStatsMap[key]) {
        alarmStatsMap[key] = { type, level, count: 0 };
      }
      alarmStatsMap[key].count += 1;
    });
    const alarmStats = Object.values(alarmStatsMap);

    return {
      duration,
      messageCount,
      alarmCount,
      bandwidthStats,
      alarmStats,
      startTime,
    };
  }

  return {
    // 工具函数
    formatDuration,
    formatDateTime,

    // 方法
    buildSimulationSummary,
  };
}

export default useSimulationReport;

/**
 * 仿真WebSocket Composable
 * 封装WebSocket连接、消息处理、自动重连
 * 提供响应式数据流（优化版）
 */
import { ref, shallowRef, onUnmounted, type Ref, type ShallowRef } from 'vue';
import { ElMessage } from 'element-plus';
import request from '@/utils/request';

/**
 * WebSocket消息类型
 */
export type WebSocketMessageType =
  | 'status'
  | 'messages'
  | 'bandwidth'
  | 'alarms'
  | 'animation'
  | 'faults'
  | 'pong';

/**
 * WebSocket消息结构
 */
export interface WebSocketMessage {
  type: WebSocketMessageType;
  data: any;
}

/**
 * 仿真状态数据
 */
export interface SimulationStatusData {
  sessionId: string;
  status: 'idle' | 'running' | 'paused' | 'stopped' | 'error';
  startTime?: string;
  endTime?: string;
  messageCount: number;
  alarmCount: number;
  errorCount: number;
}

/**
 * 仿真报文数据
 */
export interface SimulationMessage {
  id: string;
  timestamp: number;
  sourceNode: string;
  targetNode: string;
  protocolType: string;
  messageType: string;
  data: any;
  size: number;
}

/**
 * 带宽数据点
 */
export interface BandwidthDataPoint {
  timestamp: number;
  portId: string;
  bandwidth: number;
  utilization: number;
}

/**
 * 告警数据
 */
export interface AlarmData {
  alarmId: string;
  timestamp: number;
  severity: 'info' | 'warning' | 'error' | 'critical';
  message: string;
  nodeId?: string;
  edgeId?: string;
  details?: any;
}

/**
 * 动画事件数据
 */
export interface AnimationEvent {
  type: 'traffic' | 'error' | 'node-active' | 'node-error';
  edgeId?: string;
  nodeId?: string;
  protocolType?: string;
  duration?: number;
}

/**
 * 故障事件数据
 */
export interface FaultEvent {
  faultId: string;
  timestamp: number;
  faultType: string;
  targetNode?: string;
  targetEdge?: string;
  parameters: any;
}

/**
 * WebSocket返回类型
 */
export interface UseSimulationWebSocketReturn {
  connected: Ref<boolean>;
  statusData: Ref<SimulationStatusData | null>;
  messagesData: ShallowRef<SimulationMessage[]>;
  bandwidthData: ShallowRef<BandwidthDataPoint[]>;
  alarmsData: ShallowRef<AlarmData[]>;
  animationData: ShallowRef<AnimationEvent[]>;
  faultEventsData: ShallowRef<FaultEvent[]>;
  connect: (sessionId: string) => void;
  disconnect: () => void;
  clearData: () => void;
}

export function useSimulationWebSocket(): UseSimulationWebSocketReturn {
  const ws = ref<WebSocket | null>(null);
  const connected = ref<boolean>(false);
  const reconnectAttempts = ref<number>(0);
  const maxReconnectAttempts = 5;
  const reconnectDelay = 3000; // 3秒

  // 数据流（使用shallowRef优化性能）
  const statusData = ref<SimulationStatusData | null>(null);
  const messagesData = shallowRef<SimulationMessage[]>([]);
  const bandwidthData = shallowRef<BandwidthDataPoint[]>([]);
  const alarmsData = shallowRef<AlarmData[]>([]);
  const animationData = shallowRef<AnimationEvent[]>([]);
  const faultEventsData = shallowRef<FaultEvent[]>([]);

  let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  let heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  // 已弹出通知的告警ID集合，防止重复弹出
  const notifiedAlarmIds = new Set<string>();

  /**
   * 连接WebSocket
   */
  const connect = (sessionId: string): void => {
    void connectInternal(sessionId);
  };

  const connectInternal = async (sessionId: string): Promise<void> => {
    if (ws.value && ws.value.readyState === WebSocket.OPEN) {
      console.log('WebSocket已连接');
      return;
    }

    let wsTicket = '';
    try {
      const ticketResp = await request<{ wsTicket?: string; ws_ticket?: string }>({
        url: '/auth/ws-ticket',
        method: 'post',
        data: { session_id: sessionId },
      });
      wsTicket = ticketResp.wsTicket || ticketResp.ws_ticket || '';
    } catch (err) {
      console.error('获取WebSocket票据失败:', err);
      ElMessage.error('获取实时连接凭据失败');
      return;
    }

    if (!wsTicket) {
      ElMessage.error('实时连接凭据为空');
      return;
    }

    // 构建WebSocket URL，携带一次性ticket通过后端鉴权
    const buildWsUrl = (ticket: string): string => {
      const baseApi = import.meta.env.VITE_APP_BASE_API || '';
      const ticketQuery = `?ticket=${encodeURIComponent(ticket)}`;
      const relativePath = `/simulation/sessions/${sessionId}/ws${ticketQuery}`;

      // 如果 baseApi 是完整的 http(s) 地址，直接转换为 ws(s) 连接到真实后端
      if (/^https?:\/\//i.test(baseApi)) {
        const apiUrl = new URL(baseApi);
        const wsProtocol = apiUrl.protocol === 'https:' ? 'wss:' : 'ws:';
        const basePath = apiUrl.pathname.replace(/\/$/, '');
        return `${wsProtocol}//${apiUrl.host}${basePath}${relativePath}`;
      }

      // 默认走当前站点 + API 前缀（走本地代理）
      const apiPrefix = (baseApi.startsWith('/') ? baseApi : `/${baseApi}`).replace(/\/$/, '');
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const wsHost = window.location.host;
      return `${protocol}//${wsHost}${apiPrefix}${relativePath}`;
    };

    const wsUrl = buildWsUrl(wsTicket);

    try {
      ws.value = new WebSocket(wsUrl);

      ws.value.onopen = () => {
        console.log('WebSocket连接成功');
        connected.value = true;
        reconnectAttempts.value = 0;

        // 启动心跳
        startHeartbeat();
      };

      ws.value.onmessage = (event: MessageEvent) => {
        try {
          const message: WebSocketMessage = JSON.parse(event.data);
          handleMessage(message);
        } catch (err) {
          console.error('解析WebSocket消息失败:', err);
        }
      };

      ws.value.onerror = (error: Event) => {
        console.error('WebSocket错误:', error);
        connected.value = false;
      };

      ws.value.onclose = () => {
        console.log('WebSocket连接关闭');
        connected.value = false;
        stopHeartbeat();

        // 尝试重连
        attemptReconnect(sessionId);
      };
    } catch (err) {
      console.error('创建WebSocket连接失败:', err);
      ElMessage.error('无法建立实时连接');
    }
  };

  /**
   * 处理接收到的消息
   */
  const handleMessage = (message: WebSocketMessage): void => {
    const { type, data } = message;

    switch (type) {
      case 'status':
        statusData.value = data;
        break;

      case 'messages': {
        // 追加新报文，保留滑动窗口，避免前端内存爆炸
        const WS_MESSAGE_LIMIT = 50000;
        const merged = [...messagesData.value, ...data];
        messagesData.value = WS_MESSAGE_LIMIT ? merged.slice(-WS_MESSAGE_LIMIT) : merged;
        break;
      }

      case 'bandwidth': {
        // 追加带宽数据，保持最新600秒数据（对齐长窗口需求）
        const now = Date.now() / 1000;
        const cutoff = now - 600;
        const merged = [...bandwidthData.value, ...data];
        // 过滤旧数据并限制数量
        bandwidthData.value = merged.filter((item) => item.timestamp >= cutoff).slice(-600);
        break;
      }

      case 'alarms':
        // 追加告警，限制最多200条
        alarmsData.value = [...alarmsData.value, ...data].slice(-200);
        // 显示新告警通知
        if (data.length > 0) {
          const latestAlarm = data[data.length - 1];
          showAlarmNotification(latestAlarm);
        }
        break;

      case 'animation':
        // 动画事件，保留最近100条供拓扑动画消费
        animationData.value = [...animationData.value, ...data].slice(-100);
        break;

      case 'faults':
        // 故障事件增量，保留最近200条
        faultEventsData.value = [...faultEventsData.value, ...data].slice(-200);
        break;

      case 'pong':
        // 心跳响应
        break;

      default:
        console.warn('未知的消息类型:', type);
    }
  };

  /**
   * 显示告警通知（去重处理，同一告警只弹一次）
   */
  const showAlarmNotification = (alarm: AlarmData): void => {
    // 检查是否已经弹出过该告警
    if (notifiedAlarmIds.has(alarm.alarmId)) {
      return;
    }

    // 标记为已弹出
    notifiedAlarmIds.add(alarm.alarmId);

    // 限制缓存大小，避免内存泄漏
    if (notifiedAlarmIds.size > 500) {
      const firstId = notifiedAlarmIds.values().next().value;
      if (firstId) {
        notifiedAlarmIds.delete(firstId);
      }
    }

    const severityMap: Record<string, 'info' | 'warning' | 'error'> = {
      info: 'info',
      warning: 'warning',
      error: 'error',
      critical: 'error',
    };

    const type = severityMap[alarm.severity] || 'warning';
    ElMessage({
      type,
      message: alarm.message,
      duration: 5000,
    });
  };

  /**
   * 启动心跳
   */
  const startHeartbeat = (): void => {
    heartbeatTimer = setInterval(() => {
      if (ws.value && ws.value.readyState === WebSocket.OPEN) {
        ws.value.send(JSON.stringify({ type: 'ping' }));
      }
    }, 30000); // 每30秒发送一次心跳
  };

  /**
   * 停止心跳
   */
  const stopHeartbeat = (): void => {
    if (heartbeatTimer) {
      clearInterval(heartbeatTimer);
      heartbeatTimer = null;
    }
  };

  /**
   * 尝试重连
   */
  const attemptReconnect = (sessionId: string): void => {
    if (reconnectAttempts.value >= maxReconnectAttempts) {
      console.log('达到最大重连次数，停止重连');
      ElMessage.error('实时连接已断开，请刷新页面');
      return;
    }

    reconnectAttempts.value++;
    console.log(`尝试重连 (${reconnectAttempts.value}/${maxReconnectAttempts})`);

    reconnectTimer = setTimeout(() => {
      connect(sessionId);
    }, reconnectDelay);
  };

  /**
   * 断开连接
   */
  const disconnect = (): void => {
    if (reconnectTimer) {
      clearTimeout(reconnectTimer);
      reconnectTimer = null;
    }

    stopHeartbeat();

    if (ws.value) {
      ws.value.close();
      ws.value = null;
    }

    connected.value = false;
  };

  /**
   * 清空数据
   */
  const clearData = (): void => {
    statusData.value = null;
    messagesData.value = [];
    bandwidthData.value = [];
    alarmsData.value = [];
    animationData.value = [];
    faultEventsData.value = [];
    notifiedAlarmIds.clear();
  };

  // 组件卸载时断开连接
  onUnmounted(() => {
    disconnect();
  });

  return {
    connected,
    statusData,
    messagesData,
    bandwidthData,
    alarmsData,
    animationData,
    faultEventsData,
    connect,
    disconnect,
    clearData,
  };
}

/**
 * 拓扑动画 Composable
 *
 * 管理拓扑图上的动画效果：
 * - 链路光点动画（数据传输）
 * - 链路错误闪烁
 * - 节点呼吸灯效果
 */
import { ref, onUnmounted, type Ref } from 'vue';

/**
 * 协议类型到颜色的映射
 */
export const PROTOCOL_COLORS: Record<string, string> = {
  '1553B': '#f97316', // 橙色
  'MIL-STD-1553B': '#f97316',
  CAN: '#3b82f6', // 蓝色
  RS422: '#22c55e', // 绿色
  RS485: '#22c55e', // 绿色
  LAN: '#e2e8f0', // 白色
  Ethernet: '#e2e8f0', // 白色
  default: '#94a3b8', // 灰色
};

/**
 * 获取协议对应的颜色
 * @param protocolType - 协议类型
 * @returns 颜色值
 */
export function getProtocolColor(protocolType: string): string {
  if (!protocolType) {
    return PROTOCOL_COLORS.default;
  }

  const normalizedType = protocolType.toUpperCase().replace(/[-_\s]/g, '');

  // 精确匹配
  if (PROTOCOL_COLORS[protocolType]) {
    return PROTOCOL_COLORS[protocolType];
  }

  // 模糊匹配
  if (normalizedType.includes('1553')) {
    return PROTOCOL_COLORS['1553B'];
  }
  if (normalizedType.includes('CAN')) {
    return PROTOCOL_COLORS['CAN'];
  }
  if (normalizedType.includes('RS422') || normalizedType.includes('RS485')) {
    return PROTOCOL_COLORS['RS422'];
  }
  if (normalizedType.includes('LAN') || normalizedType.includes('ETHERNET')) {
    return PROTOCOL_COLORS['LAN'];
  }

  return PROTOCOL_COLORS.default;
}

/**
 * 验证协议颜色映射的完整性
 * @param protocolTypes - 协议类型列表
 * @returns 是否所有协议都有对应颜色
 */
export function validateProtocolColors(protocolTypes: string[]): boolean {
  const colors = new Set<string>();

  for (const type of protocolTypes) {
    const color = getProtocolColor(type);
    if (color === PROTOCOL_COLORS.default) {
      return false;
    }
    colors.add(color);
  }

  // 确保不同协议映射到不同颜色
  return colors.size === protocolTypes.length;
}

/**
 * DAG 图实例接口（简化版）
 */
export interface DagGraph {
  getCellById: (id: string) => any;
  getEdges?: () => any[];
  getNodes?: () => any[];
  findViewByCell: (cell: any) => any;
}

/**
 * DAG 组件引用接口
 */
export interface DagRef {
  getGraph?: () => DagGraph | null;
}

/**
 * 速度源类型
 */
export type SpeedSource = number | Ref<number> | (() => number) | { value: number } | null;

/**
 * 拓扑动画返回类型
 */
export interface UseTopologyAnimationReturn {
  isAnimating: Ref<boolean>;
  activeNodes: Ref<Set<string>>;
  activeEdges: Ref<Set<string>>;
  errorEdges: Ref<Set<string>>;
  startAnimation: () => void;
  stopAnimation: () => void;
  triggerTrafficAnimation: (edgeId: string, protocolType: string, duration?: number) => void;
  triggerErrorAnimation: (edgeId: string, duration?: number) => void;
  setNodeActive: (nodeId: string, active?: boolean, force?: boolean) => void;
  setNodeError: (nodeId: string, hasError?: boolean) => void;
  highlightEdges: (edgeIds: string[], color?: string) => void;
  clearEdgeHighlight: (edgeIds: string[]) => void;
  getProtocolColor: (protocolType: string) => string;
}

/**
 * 拓扑动画 Composable
 * @param dagRef - DAG 组件引用
 * @param speedSource - 速度倍率源
 * @returns 动画控制方法
 */
export function useTopologyAnimation(
  dagRef: Ref<DagRef | null>,
  speedSource: SpeedSource = null
): UseTopologyAnimationReturn {
  // 动画状态
  const isAnimating = ref<boolean>(false);
  const activeNodes = ref<Set<string>>(new Set());
  const activeEdges = ref<Set<string>>(new Set());
  const errorEdges = ref<Set<string>>(new Set());

  // 动画定时器
  const animationTimers = ref<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  // 节流配置
  const THROTTLE_INTERVAL = 100; // 基准 100ms 节流

  // 上次动画触发时间
  const lastAnimationTime = ref<Map<string, number>>(new Map());

  /**
   * 当前速度倍率
   */
  function getSpeedFactor(): number {
    const val =
      typeof speedSource === 'function'
        ? speedSource()
        : speedSource && typeof speedSource === 'object' && 'value' in speedSource
          ? speedSource.value
          : speedSource;
    const num = Number(val) || 1;
    return Math.max(0.5, Math.min(num, 4));
  }

  /**
   * 获取图实例
   */
  function getGraph(): DagGraph | null {
    return dagRef.value?.getGraph?.() || null;
  }

  /**
   * 节流检查
   */
  function shouldThrottle(key: string): boolean {
    const now = Date.now();
    const factor = getSpeedFactor();
    const interval = Math.max(20, THROTTLE_INTERVAL / factor);
    const lastTime = lastAnimationTime.value.get(key) || 0;

    if (now - lastTime < interval) {
      return true;
    }

    lastAnimationTime.value.set(key, now);
    return false;
  }

  /**
   * 启动全局动画
   */
  function startAnimation(): void {
    isAnimating.value = true;
  }

  /**
   * 停止全局动画
   */
  function stopAnimation(): void {
    isAnimating.value = false;

    // 清除所有动画定时器
    animationTimers.value.forEach((timer) => clearTimeout(timer));
    animationTimers.value.clear();

    // 重置所有状态
    activeNodes.value.clear();
    activeEdges.value.clear();
    errorEdges.value.clear();

    // 重置图形样式
    const graph = getGraph();
    if (graph) {
      resetGraphStyles(graph);
    }
  }

  /**
   * 重置图形样式
   */
  function resetGraphStyles(graph: DagGraph): void {
    const edges = graph.getEdges?.() || [];
    const nodes = graph.getNodes?.() || [];

    edges.forEach((edge) => {
      edge.attr('line/stroke', '#b1b1b7');
      edge.attr('line/strokeWidth', 2);
      edge.attr('line/strokeDasharray', null);
    });

    nodes.forEach((node) => {
      // 通过 findViewByCell 获取节点视图
      const nodeView = graph.findViewByCell(node);
      if (nodeView && nodeView.container) {
        nodeView.container.classList.remove('node-breathing', 'node-error');
        // 重置 SVG 元素样式
        const svgEl = nodeView.container.querySelector('rect, circle, ellipse, path');
        if (svgEl) {
          svgEl.style.stroke = '';
          svgEl.style.strokeWidth = '';
          svgEl.style.filter = '';
        }
      }
    });
  }

  /**
   * 触发链路流量动画
   * @param edgeId - 边ID
   * @param protocolType - 协议类型
   * @param duration - 动画持续时间（毫秒）
   */
  function triggerTrafficAnimation(
    edgeId: string,
    protocolType: string,
    duration: number = 1000
  ): void {
    if (!isAnimating.value) return;
    if (shouldThrottle(`traffic-${edgeId}`)) return;

    const graph = getGraph();
    if (!graph) return;

    const edge = graph.getCellById(edgeId);
    if (!edge) return;

    const color = getProtocolColor(protocolType);

    // 设置边的动画样式
    edge.attr('line/stroke', color);
    edge.attr('line/strokeWidth', 3);
    edge.attr('line/strokeDasharray', '5 5');

    // 添加到活跃边集合
    activeEdges.value.add(edgeId);

    // 创建光点动画（使用 CSS 动画）
    const edgeView = graph.findViewByCell(edge);
    if (edgeView) {
      const pathEl = edgeView.findOne('path');
      if (pathEl) {
        pathEl.classList.add('edge-traffic-animation');
        pathEl.style.setProperty('--traffic-color', color);
      }
    }

    // 设置定时器恢复样式
    const factor = getSpeedFactor();
    const adjustedDuration = Math.max(200, duration / factor);

    const timerId = setTimeout(() => {
      edge.attr('line/stroke', '#b1b1b7');
      edge.attr('line/strokeWidth', 2);
      edge.attr('line/strokeDasharray', null);
      activeEdges.value.delete(edgeId);

      if (edgeView) {
        const pathEl = edgeView.findOne('path');
        if (pathEl) {
          pathEl.classList.remove('edge-traffic-animation');
        }
      }

      animationTimers.value.delete(edgeId);
    }, adjustedDuration);

    animationTimers.value.set(edgeId, timerId);
  }

  /**
   * 触发链路错误动画
   * @param edgeId - 边ID
   * @param duration - 动画持续时间（毫秒）
   */
  function triggerErrorAnimation(edgeId: string, duration: number = 2000): void {
    if (shouldThrottle(`error-${edgeId}`)) return;

    const graph = getGraph();
    if (!graph) return;

    const edge = graph.getCellById(edgeId);
    if (!edge) return;

    // 设置错误样式
    edge.attr('line/stroke', '#ef4444');
    edge.attr('line/strokeWidth', 4);

    // 添加到错误边集合
    errorEdges.value.add(edgeId);

    // 创建闪烁动画
    const edgeView = graph.findViewByCell(edge);
    if (edgeView) {
      const pathEl = edgeView.findOne('path');
      if (pathEl) {
        pathEl.classList.add('edge-error-animation');
      }
    }

    // 设置定时器恢复样式
    const factor = getSpeedFactor();
    const adjustedDuration = Math.max(300, duration / factor);

    const timerId = setTimeout(() => {
      edge.attr('line/stroke', '#b1b1b7');
      edge.attr('line/strokeWidth', 2);
      errorEdges.value.delete(edgeId);

      if (edgeView) {
        const pathEl = edgeView.findOne('path');
        if (pathEl) {
          pathEl.classList.remove('edge-error-animation');
        }
      }

      animationTimers.value.delete(`error-${edgeId}`);
    }, adjustedDuration);

    animationTimers.value.set(`error-${edgeId}`, timerId);
  }

  /**
   * 设置节点活跃状态（呼吸灯效果）
   * @param nodeId - 节点ID
   * @param active - 是否活跃
   * @param force - 是否强制设置（忽略 isAnimating 状态）
   */
  function setNodeActive(nodeId: string, active: boolean = true, force: boolean = false): void {
    // 如果不是强制模式且动画未启动，则跳过
    if (!force && !isAnimating.value && active) return;

    const graph = getGraph();
    if (!graph) return;

    const node = graph.getCellById(nodeId);
    if (!node) return;

    // 通过 findViewByCell 获取节点视图
    const nodeView = graph.findViewByCell(node);
    if (!nodeView || !nodeView.container) return;

    if (active) {
      activeNodes.value.add(nodeId);
      nodeView.container.classList.add('node-breathing');
    } else {
      activeNodes.value.delete(nodeId);
      nodeView.container.classList.remove('node-breathing');
    }
  }

  /**
   * 设置节点错误状态
   * @param nodeId - 节点ID
   * @param hasError - 是否有错误
   */
  function setNodeError(nodeId: string, hasError: boolean = true): void {
    const graph = getGraph();
    if (!graph) return;

    const node = graph.getCellById(nodeId);
    if (!node) return;

    // 方式1: 通过 findViewByCell 获取节点视图的容器元素并添加 CSS 类
    const nodeView = graph.findViewByCell(node);
    if (nodeView && nodeView.container) {
      if (hasError) {
        nodeView.container.classList.add('node-error');
        // 同时给 SVG 元素添加红色边框效果
        const svgEl = nodeView.container.querySelector('rect, circle, ellipse, path');
        if (svgEl) {
          svgEl.style.stroke = '#ef4444';
          svgEl.style.strokeWidth = '3px';
          svgEl.style.filter = 'drop-shadow(0 0 10px rgba(239, 68, 68, 0.9))';
        }
      } else {
        nodeView.container.classList.remove('node-error');
        const svgEl = nodeView.container.querySelector('rect, circle, ellipse, path');
        if (svgEl) {
          svgEl.style.stroke = '';
          svgEl.style.strokeWidth = '';
          svgEl.style.filter = '';
        }
      }
    }

    // 方式2: 通过 X6 的 attr API 设置样式（兼容不同节点类型）
    // 尝试多个可能的形状属性名
    const shapeAttrs = ['body', 'rect', 'circle', 'ellipse', 'path', 'polygon'];

    if (hasError) {
      // 保存原始样式
      const originalStyles: Record<string, any> = {};
      shapeAttrs.forEach((shape) => {
        const stroke = node.attr(`${shape}/stroke`);
        const strokeWidth = node.attr(`${shape}/strokeWidth`);
        if (stroke !== undefined) {
          originalStyles[shape] = { stroke, strokeWidth };
        }
      });
      node.setData({ _originalStyles: originalStyles }, { silent: true });

      // 设置错误样式 - 尝试所有可能的形状
      shapeAttrs.forEach((shape) => {
        node.attr(`${shape}/stroke`, '#ef4444', { silent: true });
        node.attr(`${shape}/strokeWidth`, 3, { silent: true });
      });
    } else {
      // 恢复原始样式
      const data = node.getData() || {};
      const originalStyles = data._originalStyles || {};

      shapeAttrs.forEach((shape) => {
        const original = originalStyles[shape];
        if (original) {
          node.attr(`${shape}/stroke`, original.stroke || '#e2e8f0', { silent: true });
          node.attr(`${shape}/strokeWidth`, original.strokeWidth || 1, { silent: true });
        } else {
          node.attr(`${shape}/stroke`, '#e2e8f0', { silent: true });
          node.attr(`${shape}/strokeWidth`, 1, { silent: true });
        }
      });
    }
  }

  /**
   * 高亮指定的边
   * @param edgeIds - 边ID列表
   * @param color - 高亮颜色
   */
  function highlightEdges(edgeIds: string[], color: string = '#3b82f6'): void {
    const graph = getGraph();
    if (!graph) return;

    edgeIds.forEach((edgeId) => {
      const edge = graph.getCellById(edgeId);
      if (edge) {
        edge.attr('line/stroke', color);
        edge.attr('line/strokeWidth', 3);
      }
    });
  }

  /**
   * 清除边高亮
   * @param edgeIds - 边ID列表
   */
  function clearEdgeHighlight(edgeIds: string[]): void {
    const graph = getGraph();
    if (!graph) return;

    edgeIds.forEach((edgeId) => {
      const edge = graph.getCellById(edgeId);
      if (edge) {
        edge.attr('line/stroke', '#b1b1b7');
        edge.attr('line/strokeWidth', 2);
      }
    });
  }

  // 清理
  onUnmounted(() => {
    stopAnimation();
  });

  return {
    // 状态
    isAnimating,
    activeNodes,
    activeEdges,
    errorEdges,

    // 方法
    startAnimation,
    stopAnimation,
    triggerTrafficAnimation,
    triggerErrorAnimation,
    setNodeActive,
    setNodeError,
    highlightEdges,
    clearEdgeHighlight,
    getProtocolColor,
  };
}

export default useTopologyAnimation;
